Object.assign(window.TEM8_DICTIONARY, {"pacific":{"media":{"uk":"media/uk/pacific__gb_1.mp3","us":"media/us/pacific__us_1.mp3"},"oxford":{"phon":"pəˈsɪfɪk","pos":"adjective","senses":[{"en":"peaceful or loving peace","cn":"平静的；和平的；爱和平的"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"太平洋","en":"The Pacific or the Pacific Ocean is a very large sea to the west of North and South America, and to the east of Asia and Australia.","ex":{"en":"...an island in the Pacific.","cn":"太平洋岛屿"}},{"pos":"ADJ 形容词","cn":"太平洋里的；与太平洋有关的","en":"Pacific is used to describe things that are in or that relate to the Pacific Ocean.","ex":{"en":"...the tiny Pacific island of Pohnpei.","cn":"太平洋小岛波纳佩"}}]},"examples":[{"en":"a normally pacific community","cn":"平日里静悄悄的社区"}]},"passing":{"media":{"uk":"media/uk/passing__gb_1.mp3","us":"media/us/passing__us_1.mp3"},"oxford":{"phon":"ˈpɑːsɪŋ","pos":"noun","senses":[{"en":"the process of time going by","cn":"（时间、岁月的）流逝，推移","ex":{"en":"The colour of the wood darkens with the passing of time.","cn":"木头的颜色随日久而变深。"}},{"en":"the fact of something ending or of somebody dying","cn":"（事物的）结束，消亡；（人的）亡故，逝世","lab":"formal","ex":{"en":"When the government is finally brought down, no one will mourn its passing.","cn":"当政府最终垮台，将不会有人为它的消亡而悲哀。"}},{"en":"the act of making something become a law","cn":"（法律等的）通过","ex":{"en":"the passing of a resolution/law","cn":"决议／法律的通过"}},{"en":"lasting only for a short period of time and then disappearing","cn":"暂时的；瞬间的","ex":{"en":"a passing phase/thought/interest","cn":"过渡阶段；一闪念；一时之兴"},"pos":"adjective"},{"en":"going past","cn":"经过的；过往的","ex":{"en":"the noise of passing cars","cn":"过往车辆的嘈杂"},"pos":"adjective"},{"en":"going by in time","cn":"（时间）流逝的，过去的","ex":{"en":"I love him more with each passing day.","cn":"随着时间的流逝，我越发爱他了。"},"pos":"adjective"},{"en":"a mark that achieves the required standard in an exam, a test, etc.","cn":"（考试、测验等）及格的","lab":"North American English","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"短暂的；一时的；转瞬即逝的","en":"A passing fashion, activity, or feeling lasts for only a short period of time and is not worth taking very seriously.","ex":{"en":"Hamnett does not believe environmental concern is a passing fad","cn":"哈姆内特认为对环境的关注不是一时心血来潮。"}},{"pos":"N-SING 单数名词","cn":"结束；消失","en":"The passing of something such as a time or system is the fact of its coming to an end.","ex":{"en":"It was an historic day, yet its passing was not marked by the slightest excitement","cn":"那是具有历史意义的一天，但是一天过去了，也没有一丝的兴奋激动。"}},{"pos":"N-SING 单数名词","cn":"逝世；去世；过世","en":"You can refer to someone's death as their passing, if you want to avoid using the word 'death' because you think it might upset or offend people.","ex":{"en":"His passing will be mourned by many people.","cn":"很多人都会哀悼他的逝世。"}},{"pos":"N-SING 单数名词","cn":"（时光的）流逝，推移","en":"The passing of a period of time is the fact or process of its going by.","ex":{"en":"The passing of time brought a sense of emptiness","cn":"时间的流逝带来了一丝空虚感。"}},{"pos":"ADJ 形容词","cn":"顺便的；顺带的","en":"A passing mention or reference is brief and is made while you are talking or writing about something else.","ex":{"en":"It was just a passing comment, he didn't go on about it","cn":"那只是一笔带过的评论，他没有继续论述。"}},{"pos":"PHRASE 短语","cn":"顺便；顺带","en":"If you mention something in passing, you mention it briefly while you are talking or writing about something else.","ex":{"en":"In passing, it should be noted that","cn":"顺便提一下，应该注意…"}},{"pos":"PHRASE 短语","cn":"持续不断地","en":"If something changes with each passing year or with every passing day, it changes continuously.","ex":{"en":"His stomach had grown more prominent with every passing year","cn":"他的肚子一年比一年鼓。"}}]},"examples":[{"en":"When the government is finally brought down, no one will mourn its passing.","cn":"当政府最终垮台，将不会有人为它的消亡而悲哀。"},{"en":"He only mentioned it in passing and didn't give any details.","cn":"他只是随口提及而已，并没有谈任何细节。"}]},"participants":{"oxford":{"phon":"pɑːˈtɪsɪpənt","pos":"noun","senses":[{"en":"a person who is taking part in an activity or event","cn":"参与者；参加者"}]}},"partly":{"media":{"uk":"media/uk/partly__gb_1.mp3","us":"media/us/partly__us_1.mp3"},"oxford":{"phon":"ˈpɑːtli","pos":"adverb","senses":[{"en":"to some extent; not completely","cn":"一定程度上；部分地","ex":{"en":"Some people are unwilling to attend the classes partly because of the cost involved.","cn":"有些人不愿来上课，部分原因是所需的费用问题。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"部分地；不完全地；在某种程度上","en":"You use partly to indicate that something happens or exists to some extent, but not completely.","ex":{"en":"It's partly my fault","cn":"这在一定程度上是我的错。"}}]},"examples":[{"en":"Some people are unwilling to attend the classes partly because of the cost involved.","cn":"有些人不愿来上课，部分原因是所需的费用问题。"},{"en":"I didn’t enjoy the trip very much, partly because of the weather.","cn":"我旅行过得不太愉快，部分是因为天气的缘故。"}]},"pain":{"media":{"uk":"media/uk/pain__gb_1.mp3","us":"media/us/pain__us_1.mp3"},"oxford":{"phon":"peɪn","pos":"noun","senses":[{"en":"the feelings that you have in your body when you have been hurt or when you are ill","cn":"（身体上的）疼痛","g":"[uncountable, countable]","ex":{"en":"a cry of pain","cn":"痛苦的喊叫"}},{"en":"mental or emotional difficulty","cn":"痛苦；苦恼；烦恼","g":"[uncountable, countable]","ex":{"en":"the pain of separation","cn":"离别的痛苦"}},{"en":"a person or thing that is very annoying","cn":"极讨厌的人（或事物）","g":"[countable]","lab":"informal","ex":{"en":"She can be a real pain when she's in a bad mood.","cn":"她脾气不好时，真是令人头痛。"}},{"en":"to cause somebody pain or make them unhappy","cn":"使痛苦；使苦恼","lab":"old use","ex":{"en":"She was deeply pained by the accusation.","cn":"这一指控使她极为痛苦。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"痛；疼痛","en":"Pain is the feeling of great discomfort you have, for example when you have been hurt or when you are ill.","ex":{"en":"...back pain.","cn":"背痛"}},{"pos":"N-UNCOUNT 不可数名词","cn":"痛苦；悲痛","en":"Pain is the feeling of unhappiness that you have when something unpleasant or upsetting happens.","ex":{"en":"...grey eyes that seemed filled with pain.","cn":"似乎充满了痛苦的灰眼睛"}},{"pos":"VERB 动词","cn":"使痛苦；使苦恼","en":"If a fact or idea pains you, it makes you feel upset and disappointed.","ex":{"en":"This public acknowledgment of Ted's disability pained my mother","cn":"这一下大家都知道了特德的残疾，这让母亲非常痛苦。"}},{"pos":"PHRASE 短语","cn":"讨厌鬼，烦心事（英国英语亦用a pain in the arse, a pain in the backside等，美国英语亦用a pain in the ass, a pain in the butt等，但多数人认为具冒犯意味）","en":"In informal English, if you call someone or something a pain or a pain in the neck, you mean that they are very annoying or irritating. Expressions such as a pain in the arse and a pain in the backside in British English, or a pain in the ass and a pain in the butt in American English, are also used, but most people consider them offensive."},{"pos":"PHRASE 短语","cn":"（尤指为避免困境而）急切想做，迫切想要做","en":"If someone is at pains to do something, they are very eager and anxious to do it, especially because they want to avoid a difficult situation.","ex":{"en":"Mobil is at pains to point out that the chances of an explosion at the site are remote.","cn":"美孚公司急于说明那个地点发生爆炸的可能性微乎其微。"}},{"pos":"PHRASE 短语","cn":"作为辛劳的回报；付出千辛万苦，到头来却…","en":"You say that something was all you got for your pains when you are mentioning the disappointing result of situation into which you put a lot of work or effort.","ex":{"en":"All Corfield got for his pains was a bullet in the head","cn":"科菲尔德千辛万苦，到头来却被一枪爆头。"}},{"pos":"PREP-PHRASE 短语介词","cn":"如违反则以…处罚","en":"If someone is ordered not to do something on pain of or under pain of death, imprisonment, or arrest, they will be killed, put in prison, or arrested if they do it.","ex":{"en":"We were forbidden, under pain of imprisonment, to use our native language.","cn":"我们被禁止使用母语，违者将被关进监狱。"}},{"pos":"PHRASE 短语","cn":"煞费苦心；尽心竭力","en":"If you take pains to do something or go to great pains to do something, you try hard to do it, because you think it is important to do it.","ex":{"en":"Social workers went to great pains to acknowledge men's domestic rights","cn":"社会工作者尽量尊重男性的家庭权利。"}}]},"examples":[{"en":"They were required to cut pollution levels, on pain of a £10 000 fine if they disobeyed.","cn":"他们被要求降低污染水平，违则罚款 1 万英镑。"},{"en":"It's a pain having to go all that way for just one meeting.","cn":"只为开一次会，要跑那么远的路，真烦死人了。"}]},"partners":{"oxford":{"phon":"ˈpɑːtnə(r)","pos":"noun","senses":[{"en":"the person that you are married to or having a sexual relationship with","cn":"配偶；性伴侣"},{"en":"one of the people who owns a business and shares the profits, etc.","cn":"合伙人"}]},"media":{"uk":"media/uk/partner__gb_1.mp3","us":"media/us/partner__us_1.mp3"}},"payday":{"media":{"uk":"media/uk/payday__gb_1.mp3","us":"media/us/payday__us_1.mp3"},"oxford":{"phon":"ˈpeɪdeɪ","pos":"noun","senses":[{"en":"the day on which you get your wages or salary","cn":"发薪日；发工资日","ex":{"en":"Friday is payday.","cn":"星期五是发薪日。"}}]},"examples":[{"en":"Friday is payday.","cn":"星期五是发薪日。"}]},"part":{"media":{"uk":"media/uk/part__gb_1.mp3","us":"media/us/part__us_1.mp3"},"oxford":{"phon":"pɑːt","pos":"noun","senses":[{"en":"some but not all of a thing","cn":"部分","g":"[uncountable]","sc":"some","ex":{"en":"We spent part of the time in the museum.","cn":"我们花了一部分时间在博物馆。"}},{"en":"a section, piece or feature of something","cn":"片段；部分；一点","g":"[countable]","sc":"piece","ex":{"en":"The mountains are covered with snow for a large part of the year.","cn":"一年大部分时间，那些高山都被积雪覆盖。"}},{"en":"an element or member of something; a person or thing that helps to make up a whole or belongs in it","cn":"成员；成分；部分","g":"[uncountable]","sc":"member","ex":{"en":"Snacks can be part of a healthy eating plan.","cn":"零食可以是健康饮食计划的一部分。"}},{"en":"a separate piece or area of a human or animal body or of a plant","cn":"器官；部位；组成部分","g":"[countable]","sc":"of body/plant","ex":{"en":"The cancer could spread to other parts of the body.","cn":"癌症可能会扩散到身体的其他部位。"}},{"en":"a piece of a machine or structure","cn":"部件；零件","g":"[countable]","sc":"of machine","ex":{"en":"The factory manufactures aircraft parts.","cn":"该工厂生产飞机零部件。"}},{"en":"an area or a region of the world, a country, a town, etc.","cn":"（世界、国家或城镇等的）区域，地区","g":"[countable]","sc":"region/area","ex":{"en":"The island is mostly flat, but there are some hilly parts.","cn":"岛上大部分地势平坦，但也有一些丘陵地区。"}},{"en":"a region or an area","cn":"区域；地区","g":"[plural]","lab":"old-fashioned, informal，，","sc":"region/area","ex":{"en":"She's not from these parts.","cn":"她不是这一带的人。"}},{"en":"a section of a book, television series, etc., especially one that is published or broadcast separately","cn":"（书、电视剧等，尤指单独发行或播出的）部，集，部分","g":"[countable]","sc":"of book/series","ex":{"en":"The documentary was screened in four parts.","cn":"这部纪录片分四个部分播出。"}},{"en":"a role played by an actor in a play, film, etc.; the words spoken by an actor in a particular role","cn":"角色；台词","g":"[countable]","lab":"figurative","sc":"for actor","ex":{"en":"She played the part of Juliet.","cn":"她扮演朱丽叶一角。"}},{"en":"the way in which somebody/something is involved in an action or situation","cn":"参加；参与","g":"[countable, usually singular, uncountable]","sc":"involvement","ex":{"en":"Luck played a big part in their success.","cn":"运气在他们的成功中起了很大的作用。"}},{"en":"music for a particular voice or instrument in a group singing or playing together","cn":"部；声部；音部；段落","g":"[countable]","sc":"in music","ex":{"en":"the clarinet part","cn":"单簧管部"}},{"en":"a unit of measurement that allows you to compare the different amounts of substances in something","cn":"（度量单位的）等份，份","g":"[countable]","sc":"equal portion","ex":{"en":"Add three parts wine to one part water.","cn":"一份水兑上三份葡萄酒。"}},{"en":"a line on a person’s head where the hair is divided with a comb","cn":"（头发的）分缝，发缝，分线","g":"[countable]","lab":"North American English","sc":"in hair"},{"en":"if a person parts from another person, or two people part, they leave each other","cn":"离开；分别","g":"[intransitive]","lab":"formal","sc":"leave somebody","ex":{"en":"We parted at the airport.","cn":"我们在机场分手了。"},"pos":"verb"},{"en":"to prevent somebody from being with somebody else","cn":"分离；分开；隔离","g":"[transitive, often passive]","lab":"formal","sc":"keep apart","ex":{"en":"I hate being parted from the children.","cn":"我不愿与孩子们分开。"},"pos":"verb"},{"en":"if two things or parts of things part or you part them, they move away from each other","cn":"分散；分开；解散","g":"[intransitive, transitive]","sc":"move away","ex":{"en":"The crowd parted in front of them.","cn":"人群在他们面前分开了。"},"pos":"verb"},{"en":"to divide your hair into two sections with a comb, creating a line that goes from the back of your head to the front","cn":"分开；梳成分头","g":"[transitive]","sc":"hair","ex":{"en":"He parts his hair in the middle.","cn":"他梳着中分头。"},"pos":"verb"},{"en":"consisting of two things; to some extent but not completely","cn":"由两部分构成；在一定程度上；部分地","ex":{"en":"She's part French, part English.","cn":"她是英法血统各半。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分；片段","en":"A part of something is one of the pieces, sections, or elements that it consists of.","ex":{"en":"I like that part of Cape Town","cn":"我喜欢开普敦的那片地方。"}},{"pos":"N-COUNT 可数名词","cn":"零件；部件；配件","en":"A part for a machine or vehicle is one of the smaller pieces that is used to make it.","ex":{"en":"...spare parts for military equipment","cn":"军事装备的备用零件"}},{"pos":"QUANT 数量词","cn":"一些；部分","en":"Part of something is some of it.","ex":{"en":"It was a very severe accident and he lost part of his foot","cn":"那是一场非常严重的事故，他有一只脚残废了。"}},{"pos":"ADV 副词","cn":"部分地；半…半…地；既…又…","en":"If you say that something is part one thing, part another, you mean that it is to some extent the first thing and to some extent the second thing.","ex":{"en":"The television producer today has to be part news person, part educator","cn":"今天的电视制片人必须既是新闻人，又是教育者。"}},{"pos":"N-COUNT 可数名词","cn":"份；等分中的一份","en":"You can use part when you are talking about the proportions of substances in a mixture. For example, if you are told to use five parts water to one part paint, the mixture should contain five times as much water as paint.","ex":{"en":"Use turpentine and linseed oil, three parts to two.","cn":"用松节油和亚麻油，比例为3:2。"}},{"pos":"N-COUNT 可数名词","cn":"角色","en":"A part in a play or film is one of the roles in it which an actor or actress can perform.","ex":{"en":"Alf Sjoberg offered her a large part in the play he was directing","cn":"阿尔夫·肖博格让她在其导演的戏中扮演重要角色。"}},{"pos":"N-SING 单数名词","cn":"作用；份儿；参与","en":"Your part in something that happens is your involvement in it.","ex":{"en":"If only he could conceal his part in the accident","cn":"要是他能够隐瞒住自己在这场事故中的责任就好了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"组成部分；成员","en":"If something or someone is part of a group or organization, they belong to it or are included in it.","ex":{"en":"...voting on whether to remain part of the Union or become independent","cn":"决定是留在联盟内还是独立的投票"}},{"pos":"N-COUNT 可数名词","cn":"（头发的）分缝","en":"The part in someone's hair is the line running from the front to the back of their head where their hair lies in different directions.","ex":{"en":"The straight white part in her ebony hair seemed to divide the back of her head in half.","cn":"她乌黑的头发中有条笔直的白色分缝，仿佛将她的后脑勺一分为二。"}},{"pos":"PHRASE 短语","cn":"在…中起作用","en":"If something or someone plays a large or important part in an event or situation, they are very involved in it and have an important effect on what happens.","ex":{"en":"These days work plays an important part in a single woman's life","cn":"现在，工作在单身女性的生活中起着重要作用。"}},{"pos":"PHRASE 短语","cn":"参加；参与","en":"If you take part in an activity, you do it together with other people.","ex":{"en":"Thousands of students have taken part in demonstrations.","cn":"数千学生参加了游行。"}},{"pos":"PHRASE 短语","cn":"不愿参与；不愿介入","en":"If you say that you want no part of something, you mean that you do not want to be involved in it at all.","ex":{"en":"What some other clubs do is unfortunate, but we want no part of it.","cn":"其他一些俱乐部的所作所为令人遗憾，但是我们不愿介入。"}},{"pos":"PHRASE 短语","cn":"在（某人）看来；就（某人）而言","en":"When you are describing people's thoughts or actions, you can say for her part or for my part, for example, to introduce what a particular person thinks or does.","ex":{"en":"For my part, I feel elated and close to tears","cn":"就我而言，我感到非常高兴，都快落泪了。"}},{"pos":"PHRASE 短语","cn":"由某人作出的","en":"If you talk about a feeling or action on someone's part, you are referring to something that they feel or do.","ex":{"en":"...techniques on their part to keep us from knowing exactly what's going on","cn":"他们所采取的防止我们知道具体发生什么事情的手段"}},{"pos":"PHRASE 短语","cn":"大部分；多半；通常","en":"For the most part means mostly or usually.","ex":{"en":"For the most part the Germans kept out of local disputes","cn":"德国人通常不卷入地区冲突。"}},{"pos":"PHRASE 短语","cn":"在某种程度上；部分地","en":"You use in part to indicate that something exists or happens to some extent but not completely.","ex":{"en":"The levels of blood glucose depend in part on what you eat and when you eat","cn":"血糖水平在某种程度上取决于饮食内容和时间。"}},{"pos":"PHRASE 短语","cn":"绝大部分；多数","en":"If you say that something happened for the best part or the better part of a period of time, you mean that it happened for most of that time.","ex":{"en":"He had been in Israel for the best part of twenty-four hours","cn":"他一天24小时多数时间在以色列。"}},{"pos":"","cn":"","en":"part and parcel→see: ;"},{"pos":"V-ERG 及物/不及物动词","cn":"分；分开","en":"If things that are next to each other part or if you part them, they move in opposite directions, so that there is a space between them.","ex":{"en":"Her lips parted as if she were about to take a deep breath","cn":"她张开嘴，好像要深呼吸。"}},{"pos":"VERB 动词","cn":"给（头发） 分缝","en":"If you part your hair in the middle or at one side, you make it lie in two different directions so that there is a straight line running from the front of your head to the back.","ex":{"en":"Picking up a brush, Joanna parted her hair","cn":"乔安娜拿起一把刷子，给头发分缝。"}},{"pos":"V-RECIP 相互动词","cn":"分手；告别；别离","en":"When two people part, or if one person parts from another, they leave each other.","ex":{"en":"He gave me the envelope and we parted","cn":"他给了我那个信封，我们就告别了。"}},{"pos":"V-RECIP 相互动词","cn":"分开；拆散","en":"If you are parted from someone you love, you are prevented from being with them.","ex":{"en":"I don't believe Lotte and I will ever be parted","cn":"我相信洛特和我永远都不会分开。"}},{"pos":"See also:","cn":"","en":"to part company→see: ;"},{"pos":"","cn":"","en":"相关词组：part with"}]},"examples":[{"en":"Come and visit us if you're ever in our part of the world.","cn":"什么时候到我们这个地方来，请来看看我们。"},{"en":"Weber parted company with Marx on a number of important issues.","cn":"韦伯与马克思在若干重大问题上意见有分歧。"}]},"pack":{"media":{"img":["media/pic/cards_comp.jpg","media/thumb/pack.jpg"],"uk":"media/uk/pack__gb_1.mp3","us":"media/us/pack__us_1.mp3"},"oxford":{"phon":"pæk","pos":"verb","senses":[{"en":"to put clothes, etc. into a bag in preparation for a trip away from home","cn":"收拾（行李）；装（箱）","g":"[intransitive, transitive]","sc":"put into container","ex":{"en":"I haven't packed yet.","cn":"我还没收拾行李呢。"}},{"en":"to put something into a container so that it can be stored, transported or sold","cn":"打包；包装","g":"[transitive]","sc":"put into container","ex":{"en":"The pottery was packed in boxes and shipped to the US.","cn":"陶器已装箱运往美国。"}},{"en":"to protect something that breaks easily by surrounding it with soft material","cn":"（在四周填入软料以）包装（易损物品）","g":"[transitive]","sc":"protect","ex":{"en":"The paintings were carefully packed in newspaper.","cn":"这些画被仔细地用报纸裹了起来。"}},{"en":"to preserve food in a particular substance","cn":"（用某物）保存，保藏","g":"[transitive]","sc":"preserve food","ex":{"en":"fish packed in ice","cn":"用冰块保存的鱼"}},{"en":"to fill something with a lot of people or things","cn":"塞进；挤进","g":"[intransitive, transitive]","sc":"fill","ex":{"en":"We all packed together into one car.","cn":"我们大家挤进一辆汽车里。"}},{"en":"to press something such as snow or soil to form a thick hard mass","cn":"堆积；压实","g":"[transitive]","sc":"snow/soil","ex":{"en":"Pack the earth down around the plant.","cn":"把植物周围的土压实。"}},{"en":"to carry a gun","cn":"佩带，携带（枪支）","g":"[transitive, intransitive]","lab":"North American English, informal，，","sc":"carry gun","ex":{"en":"to pack a gun","cn":"佩带枪支"}},{"en":"to have something","cn":"夹带着","g":"[transitive]","sc":"storm","ex":{"en":"A storm packing 75 mph winds swept across the area last night.","cn":"昨晚暴雨和着每小时 75 英里的狂风横扫该地区。"}},{"en":"a container, usually made of paper, that holds a number of the same thing or an amount of something, ready to be sold","cn":"（商品的）纸包，纸袋，纸盒","g":"[countable]","lab":"especially North American English","sc":"container","ex":{"en":"a pack of cigarettes/gum","cn":"一盒香烟／口香糖"},"pos":"noun"},{"en":"a set of different things that are supplied together for a particular purpose","cn":"全套东西","g":"[countable]","sc":"set","ex":{"en":"Send for your free information pack today.","cn":"今天就来信索取免费资讯包。"},"pos":"noun"},{"en":"a number of things that are wrapped or tied together, especially for carrying","cn":"一捆，一包（尤指适于携带的东西）","g":"[countable]","lab":"figurative","sc":"things tied for carrying","ex":{"en":"donkeys carrying packs of wool","cn":"驮着成捆羊毛的驴"},"pos":"noun"},{"en":"a large bag that you carry on your back","cn":"大背包","g":"[countable]","sc":"large bag","ex":{"en":"We passed a group of walkers, carrying huge packs.","cn":"我们与一批背着超大行囊的步行者擦肩而过。"},"pos":"noun"},{"en":"a group of animals that hunt together or are kept for hunting","cn":"一群（动物或猎狗）","g":"[countable + singular or plural verb]","sc":"of animals","ex":{"en":"packs of savage dogs","cn":"成群的野狗"},"pos":"noun"},{"en":"a group of similar people or things, especially one that you do not like or approve of","cn":"群；帮；团伙","g":"[countable + singular or plural verb]","sc":"of people","ex":{"en":"We avoided a pack of journalists waiting outside.","cn":"我们避开了等在门外的一群记者。"},"pos":"noun"},{"en":"all the people who are behind the leaders in a race, competition, etc.","cn":"（统称）竞赛中的落后者","g":"[countable + singular or plural verb]","sc":"of people","ex":{"en":"measures aimed at keeping the company ahead of the pack","cn":"旨在使公司领先所有竞争对手的措施"},"pos":"noun"},{"en":"a complete set of 52 playing cards","cn":"一副（为 52 张）","g":"[countable]","lab":"especially British English","sc":"of cards","ex":{"en":"a pack of cards","cn":"一副纸牌"},"pos":"noun"},{"en":"an organized group of cubs / Cub Scouts or brownies","cn":"一队（男或女幼童军）","g":"[countable + singular or plural verb]","sc":"of Cubs/Brownies","ex":{"en":"to join a Brownie pack","cn":"加入一队幼女童军"},"pos":"noun"},{"en":"a hot or cold piece of soft material that holds liquid, used for treating a wound","cn":"（治创伤用的）裹布，填塞物，敷料","g":"[countable]","sc":"for wound","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…装进行囊；打点（行装）","en":"When you pack a bag, you put clothes and other things into it, because you are leaving a place or going on holiday.","ex":{"en":"When I was 17, I packed my bags and left home","cn":"17岁时，我背起行囊离开了家。"}},{"pos":"VERB 动词","cn":"将…打包；把…装箱","en":"When people pack things, for example in a factory, they put them into containers or parcels so that they can be transported and sold.","ex":{"en":"They offered me a job packing goods in a warehouse","cn":"他们给了我一份在货栈打包的工作。"}},{"pos":"VERB 动词","cn":"挤满；塞满","en":"If people or things pack into a place or if they pack a place, there are so many of them that the place is full.","ex":{"en":"Hundreds of thousands of people packed into the mosque","cn":"几十万人挤进了那座清真寺。"}},{"pos":"N-COUNT 可数名词","cn":"包；盒","en":"A pack of things is a collection of them that is sold or given together in a box or bag.","ex":{"en":"The club will send a free information pack.","cn":"这家俱乐部会邮寄一个免费资料包。"}},{"pos":"N-COUNT 可数名词","cn":"背包；旅行包","en":"A pack is a bag containing your possessions that you carry on your back when you are travelling.","ex":{"en":"I hid the money in my pack.","cn":"我把钱藏在旅行包里。"}},{"pos":"N-COUNT 可数名词","cn":"一群；一伙；一帮","en":"You can refer to a group of people who go around together as a pack, especially when it is a large group that you feel threatened by.","ex":{"en":"...a pack of journalists eager to question him","cn":"一群急着要问他问题的记者"}},{"pos":"N-COUNT 可数名词","cn":"（狼或狗的）一群","en":"A pack of wolves or dogs is a group of them that hunt together."},{"pos":"N-COUNT 可数名词","cn":"（纸牌的）一副","en":"A pack of playing cards is a complete set of playing cards.","ex":{"en":"...a pack of cards.","cn":"一副纸牌"}},{"pos":"VERB 动词","cn":"带（枪）；佩（枪）","en":"If someone packs a gun, they carry it.","ex":{"en":"...eight bodyguards, at least one of them packing a pistol.","cn":"8名保镖，其中至少有1人佩枪"}},{"pos":"VERB 动词","cn":"在（陪审团、委员会、会议等）中安插支持者","en":"If someone packs a jury, committee, or meeting, they make sure that it includes people who support them.","ex":{"en":"Opposition parties have boycotted the proceedings, saying the government has packed the conference with its own supporters","cn":"反对党派抵制了该议程，声称政府在大会上安插了亲信。"}},{"pos":"PHRASE 短语","cn":"一派谎言","en":"If you say that an account is a pack of lies, you mean that it is completely untrue.","ex":{"en":"You told me a pack of lies.","cn":"你跟我说的都是一派胡言。"}},{"pos":"PHRASE 短语","cn":"产生巨大影响；震撼","en":"If something packs a punch, it has a very powerful effect.","ex":{"en":"W. Somerset Maugham's novel still packs an emotional punch.","cn":"威廉·萨默塞特·毛姆的小说仍具有强烈的情感冲击力。"}},{"pos":"PHRASE 短语","cn":"叫…卷铺盖；撵…走；叫…滚蛋","en":"If you send someone packing, you make them go away.","ex":{"en":"I decided I wanted to live alone and I sent him packing.","cn":"我决定要一个人生活，于是叫他走人。"}},{"pos":"PHRASE 短语","cn":"（在竞赛中）领先其他对手","en":"You can say that someone is ahead of the pack or leading the pack if they are ahead of everyone else in a race or competition.","ex":{"en":"The Socialists may still finish ahead of the pack","cn":"社会党最终仍可能会领先。"}},{"pos":"","cn":"","en":"相关词组：pack in pack into pack off pack up"}]},"examples":[{"en":"A storm packing 75 mph winds swept across the area last night.","cn":"昨晚暴雨夹带着每小时 75 英里的狂风横扫该地区。"},{"en":"Are you packing up already? It's only 4 o'clock.","cn":"你已经开始打点行李了？现在才刚刚 4 点钟。"}]},"pager":{"media":{"uk":"media/uk/pager__gb_1.mp3","us":"media/us/pager__us_1.mp3"},"oxford":{"phon":"ˈpeɪdʒə(r)","pos":"noun","senses":[{"en":"a small electronic device that you carry around with you and that shows a message or lets you know when somebody is trying to contact you, for example by making a sound","cn":"寻呼机；传呼机；BP 机","ex":{"en":"For many doctors, pagers are still an important part of everyday life.","cn":"对于许多医生来说，寻呼机仍然是日常生活的重要组成部分。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"寻呼机；传呼机","en":"A pager is a small electronic device which you can carry around with you and which gives you a number or a message when someone is trying to contact you."}]}},"passionate":{"media":{"uk":"media/uk/passionate__gb_1.mp3","us":"media/us/passionate__us_1.mp3"},"oxford":{"phon":"ˈpæʃənət","pos":"adjective","senses":[{"en":"having or showing strong feelings of sexual love or of anger, etc.","cn":"拥有（或表现出）强烈性爱的；情意绵绵的；怒不可遏的","ex":{"en":"to have a passionate nature","cn":"天性易激动"}},{"en":"having or showing strong feelings of enthusiasm for something or belief in something","cn":"热诚的；狂热的","ex":{"en":"a passionate interest in music","cn":"对音乐的浓厚兴趣"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热情的；狂热的","en":"A passionate person has very strong feelings about something or a strong belief in something.","ex":{"en":"...his passionate commitment to peace","cn":"他热情满怀地献身于和平事业"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热恋的；情欲强烈的","en":"A passionate person has strong romantic or sexual feelings and expresses them in their behaviour.","ex":{"en":"...a beautiful, passionate woman of twenty-six.","cn":"美丽而炽烈的26岁女子"}}]},"examples":[{"en":"He took her in his arms and kissed her passionately.","cn":"他把她搂在怀里狂热地亲吻。"},{"en":"a passionate defender of civil liberties","cn":"公民自由权利的积极捍卫者"}]},"packing":{"oxford":{"phon":"ˈpækɪŋ","pos":"noun","senses":[{"en":"the act of putting your possessions, clothes, etc. into bags or boxes in order to take or send them somewhere","cn":"打行李；收拾行囊","ex":{"en":"Have you finished your packing?","cn":"你收拾好行李了吗？"}},{"en":"material used for wrapping around objects in order to protect them, especially before sending them somewhere","cn":"包装材料","lab":"British English","ex":{"en":"The price includes postage and packing.","cn":"本价格包括邮资和包装费。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"包装材料","en":"Packing is the paper, plastic, or other material which is put round things that are being sent somewhere."}]},"media":{"uk":"media/uk/packing__gb_1.mp3","us":"media/us/packing__us_1.mp3"},"examples":[{"en":"( BrE ) The price includes postage and packing.","cn":"本价格包括邮资和包装费。"},{"en":"Have you finished your packing?","cn":"你收拾好行李了吗？"}]},"pad":{"oxford":{"phon":"pæd","pos":"noun","senses":[{"en":"a thick piece of soft material that is used, for example, for cleaning or protecting something or for holding liquid","cn":"（清洁、保护或吸收液体用的）软垫，护垫，垫状物","sc":"of soft material","ex":{"en":"medicated cleansing pads for sensitive skin","cn":"敏感皮肤药物清洗棉"}},{"en":"a number of pieces of paper for writing or drawing on, that are fastened together at one edge","cn":"便笺本；拍纸簿","sc":"of paper","ex":{"en":"a sketch/writing pad","cn":"速写簿；拍纸簿"}},{"en":"the soft part under the foot of a cat, dog, etc.","cn":"爪垫；肉掌","sc":"of animal’s foot","ex":{"en":"A cat detects vibrations through the pads of its feet.","cn":"猫通过脚垫检测振动。"}},{"en":"a small piece of rough material used for cleaning pans, surfaces, etc.","cn":"百洁布，菜瓜布（刷锅等的小块粗糙材料）","sc":"for cleaning","ex":{"en":"a scouring pad","cn":"刷洗用的金属丝球"}},{"en":"a flat surface where a spacecraft or a helicopter takes off and lands","cn":"发射台；停机坪","sc":"for spacecraft/helicopter","ex":{"en":"helicopter landing pads","cn":"直升机停机坪"}},{"en":"a piece of thick material that you wear in some sports, for example football and cricket, to protect parts of your body","cn":"（运动用）防护垫（如护腿、护肘等）","g":"[usually plural]","sc":"for protection","ex":{"en":"knee pads","cn":"护膝"}},{"en":"the large flat leaf of some water plants, especially the water lily","cn":"浮叶（尤见于睡莲）","sc":"of water plants","ex":{"en":"floating lily pads","cn":"睡莲的浮叶"}},{"en":"the place where somebody lives, especially a flat","cn":"住所；（尤指）公寓","g":"[usually singular]","lab":"informal","sc":"flat/apartment","ex":{"en":"He moved back into his old bachelor pad.","cn":"他搬回了他原来的单身公寓。"}},{"en":"to put a layer of soft material in or on something in order to protect it, make it thicker or change its shape","cn":"（用软材料）填充，覆盖，保护","g":"[transitive, often passive]","sc":"add soft material","ex":{"en":"a padded jacket","cn":"有夹层的外套"},"pos":"verb"},{"en":"to walk with quiet steps","cn":"蹑手蹑脚地走","g":"[intransitive]","sc":"walk quietly","ex":{"en":"She padded across the room to the window.","cn":"她蹑手蹑脚地穿过屋子走到窗前。"},"pos":"verb"},{"en":"to dishonestly add items to bills to obtain more money","cn":"虚报（账目）；做黑账","g":"[transitive]","lab":"North American English","sc":"bills","ex":{"en":"to pad bills/expense accounts","cn":"在账单上／开支账上做手脚"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"垫子；衬垫；护垫","en":"A pad is a fairly thick, flat piece of a material such as cloth or rubber. Pads are used, for example, to clean things, to protect things, or to change their shape.","ex":{"en":"He withdrew the needle and placed a pad of cotton-wool over the spot.","cn":"他把针头拔出，在扎针处按了一块药棉。"}},{"pos":"N-COUNT 可数名词","cn":"拍纸簿；便笺本","en":"A pad of paper is a number of pieces of paper which are fixed together along the top or the side, so that each piece can be torn off when it has been used.","ex":{"en":"She wrote on a pad of paper","cn":"她写在了便笺簿上。"}},{"pos":"VERB 动词","cn":"轻步快速地走；蹑手蹑脚地走","en":"When someone pads somewhere, they walk there with steps that are fairly quick, light, and quiet.","ex":{"en":"Freddy speaks very quietly and pads around in soft velvet slippers","cn":"弗蕾迪说话轻声细气，穿着柔软的天鹅绒拖鞋蹑手蹑脚地四处走动。"}},{"pos":"N-COUNT 可数名词","cn":"直升机停机坪；火箭发射台","en":"A pad is a platform or an area of flat, hard ground where helicopters take off and land or rockets are launched.","ex":{"en":"...a little round helicopter pad.","cn":"小型圆形直升机停机坪"}},{"pos":"N-COUNT 可数名词","cn":"住处；（尤指）寓所，公寓","en":"People can refer to the place where they live as their pad, especially if it is a flat.","ex":{"en":"I moved on round the big house to reach my pad","cn":"我绕过大房子走向我的公寓。"}},{"pos":"N-COUNT 可数名词","cn":"指头肚儿；（动物的）爪垫","en":"The pads of a person's fingers and toes or of an animal's feet are the soft, fleshy parts of them.","ex":{"en":"Tap your cheeks all over with the pads of your fingers.","cn":"用手指头肚儿轻拍脸颊一遍。"}},{"pos":"VERB 动词","cn":"给…加衬垫；垫衬","en":"If you pad something, you put something soft in it or over it in order to make it less hard, to protect it, or to give it a different shape.","ex":{"en":"Pad the back of a car seat with a pillow","cn":"用枕头垫一下汽车坐椅靠背。"}},{"pos":"","cn":"","en":"相关词组：pad out"}]},"media":{"uk":"media/uk/pad__gb_1.mp3","us":"media/us/pad__us_1.mp3","img":["media/ldoce/img/pads.jpg"]},"examples":[{"en":"The report was padded out with extracts from previous documents.","cn":"该报告摘抄过去的文件而加长了篇幅。"},{"en":"She padded across the room to the window.","cn":"她蹑手蹑脚地穿过屋子走到窗前。"}]},"parkway":{"media":{"uk":"media/uk/parkway__gb_1.mp3","us":"media/us/parkway__us_1.mp3"},"oxford":{"phon":"ˈpɑːkweɪ","pos":"noun","senses":[{"en":"a wide road with trees and grass along the sides or middle","cn":"（有草木的）大路；绿化道路；林荫大道","lab":"North American English","ex":{"en":"The parkway runs along the lake shore.","cn":"公园大道沿着湖岸延伸。"}},{"en":"used in the names of railway stations that are outside a town or city and close to a park and ride","cn":"公园道（用于城外靠近转乘停车场的车站名）","lab":"British English","ex":{"en":"I got off at Bristol Parkway.","cn":"我在布里斯托尔公园道站下了车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"林阴大道","en":"A parkway is a wide road with trees and grass on both sides."}]}},"payment":{"oxford":{"phon":"ˈpeɪmənt","pos":"noun","senses":[{"en":"the act of paying somebody/something or of being paid","cn":"付款；支付；收款","g":"[uncountable]","ex":{"en":"What method of payment do you prefer?","cn":"您喜欢哪种付款方式？"}},{"en":"a sum of money paid or expected to be paid","cn":"（将付或应付的）款额，款项","g":"[countable]","lab":"British English","ex":{"en":"a cash payment","cn":"现金付款"}},{"en":"a reward or an act of thanks for something you have done","cn":"报答；报偿","g":"[uncountable, singular]","ex":{"en":"Is this all the payment I get for my efforts?","cn":"这就是对我辛劳的全部报偿吗？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"付款额；支付的款项；支付；付款","en":"A payment is an amount of money that is paid to someone, or the act of paying this money.","ex":{"en":"Thousands of its customers are in arrears with loans and mortgage payments","cn":"有数千客户拖欠其贷款和抵押贷款还款。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"支付；付款","en":"Payment is the act of paying money to someone or of being paid.","ex":{"en":"He had sought to obtain payment of a sum which he had claimed was owed to him.","cn":"他声称别人欠他一笔钱，他在想方设法讨要回来。"}}]},"media":{"uk":"media/uk/payment__gb_1.mp3","us":"media/us/payment__us_1.mp3"},"examples":[{"en":"He agreed to make ten monthly payments of £50.","cn":"他同意每月付款 50 英镑，十次付清。"},{"en":"We've put down a 5% deposit on the house.","cn":"我们已支付了房款的 5% 作为订金。"}]},"paperback":{"oxford":{"phon":"ˈpeɪpəbæk","pos":"noun","senses":[{"en":"a book that has a thick paper cover","cn":"平装书；简装书","ex":{"en":"a cheap paperback","cn":"一本廉价的简装书"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"平装本","en":"A paperback is a book with a thin cardboard or paper cover.","ex":{"en":"She said she would buy the book when it comes out in paperback.","cn":"她说等那本书出平装本时再买。"}}]},"media":{"uk":"media/uk/paperback__gb_1.mp3","us":"media/us/paperback__us_1.mp3"},"examples":[{"en":"When is it coming out in paperback?","cn":"这本书的平装本什么时候出版？"},{"en":"a cheap paperback","cn":"一本廉价的简装书"}]},"participate":{"oxford":{"phon":"pɑːˈtɪsɪpeɪt","pos":"verb","senses":[{"en":"to take part in or become involved in an activity","cn":"参加；参与","ex":{"en":"Anyone who wishes to participate is welcome.","cn":"欢迎任何愿意参加的人。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"参与；参加","en":"If you participate in an activity, you take part in it.","ex":{"en":"They expected him to participate in the ceremony","cn":"他们希望他参加典礼。"}}]},"media":{"uk":"media/uk/participate__gb_1.mp3","us":"media/us/participate__us_1.mp3"},"examples":[{"en":"We encourage students to participate fully in the running of the college.","cn":"我们鼓励学生全面参与学院的运作。"},{"en":"Details of the competition are available at all participating stores.","cn":"比赛的详情可在各参与商店取阅。"}]},"pasteboard":{"media":{"uk":"media/uk/pasteboard__gb_1.mp3","us":"media/us/pasteboard__us_1.mp3"},"oxford":{"phon":"ˈpeɪstbɔːd","pos":"noun","senses":[{"en":"a type of thin board made by sticking sheets of paper together","cn":"（用多层纸粘贴的）硬纸板"}]}},"paint":{"media":{"uk":"media/uk/paint__gb_1.mp3","us":"media/us/paint__us_1.mp3","img":["media/ldoce/img/paint.jpg","media/ldoce/img/palette.jpg"]},"oxford":{"phon":"peɪnt","pos":"noun","senses":[{"en":"a liquid that is put on surfaces to give them a particular colour; a layer of this liquid when it has dried on a surface","cn":"油漆；油漆涂层","g":"[uncountable]","ex":{"en":"white paint","cn":"白漆"}},{"en":"tubes or blocks of paint used for painting pictures","cn":"绘画颜料","g":"[plural]","ex":{"en":"oil paints","cn":"油画颜料"}},{"en":"to cover a surface or object with paint","cn":"在…上刷油漆","g":"[transitive, often passive]","lab":"British English","ex":{"en":"Paint the shed with weather-resistant paint.","cn":"用抗风雨的油漆把棚子漆一漆。"},"pos":"verb"},{"en":"to make a picture or design using paints","cn":"用颜料画","g":"[transitive, intransitive]","lab":"US English","ex":{"en":"to paint portraits/pictures","cn":"画肖像；画图"},"pos":"verb"},{"en":"to give a particular impression of somebody/something","cn":"把…描绘成","g":"[transitive]","ex":{"en":"The article paints them as a bunch of petty criminals.","cn":"文章把他们描绘成一伙小犯罪分子。"},"pos":"verb"},{"en":"to put coloured make-up on your nails, lips, etc.","cn":"往（指甲、嘴唇等上）施化妆品；染（指甲）；涂（唇膏）","g":"[transitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"油漆；涂料","en":"Paint is a coloured liquid that you put onto a surface with a brush in order to protect the surface or to make it look nice, or that you use to produce a picture.","ex":{"en":"...a pot of red paint","cn":"一罐红漆"}},{"pos":"N-SING 单数名词","cn":"（已干的）油漆层，涂层","en":"On a wall or object, the paint is the covering of dried paint on it.","ex":{"en":"The paint was peeling on the window frames","cn":"窗框上的油漆在剥落。"}},{"pos":"VERB 动词","cn":"给…上油漆（或涂料）","en":"If you paint a wall or an object, you cover it with paint.","ex":{"en":"They started to mend the woodwork and paint the walls","cn":"他们开始修补木建部分，粉刷墙壁。"}},{"pos":"VERB 动词","cn":"（用颜料）绘，画","en":"If you paint something or paint a picture of it, you produce a picture of it using paint.","ex":{"en":"He is painting a huge volcano","cn":"他正在画一座巨大的火山。"}},{"pos":"VERB 动词","cn":"用漆写（或画）","en":"When you paint a design or message on a surface, you put it on the surface using paint.","ex":{"en":"...a machine for painting white lines down roads","cn":"用漆在马路上划白线的机器"}},{"pos":"VERB 动词","cn":"涂，抹（嘴唇、指甲等）","en":"If a woman paints her lips or nails, she puts a coloured cosmetic on them.","ex":{"en":"She propped the mirror against her handbag and began to paint her lips","cn":"她把镜子靠在手包上支好，开始涂口红。"}},{"pos":"VERB 动词","cn":"描绘；描述","en":"If you paint a grim or vivid picture of something, you give a description of it that is grim or vivid.","ex":{"en":"The report paints a grim picture of life there","cn":"那则报道把那里的生活描绘得很凄惨。"}}]},"examples":[{"en":"A friend painted the children for me (= painted a picture of the children).","cn":"一位朋友给我画了这张孩子们的画像。"},{"en":"The article paints them as a bunch of petty criminals.","cn":"文章把他们描绘成一伙小犯罪分子。"}]},"passage":{"media":{"uk":"media/uk/passage__gb_1.mp3","us":"media/us/passage__us_1.mp3"},"oxford":{"phon":"ˈpæsɪdʒ","pos":"noun","senses":[{"en":"a long narrow area with walls on either side that connects one room or place with another","cn":"通道；走廊","g":"[countable]","sc":"long narrow way","ex":{"en":"A dark narrow passage led to the main hall.","cn":"一条阴暗狭窄的走廊通向大厅。"}},{"en":"a tube in the body through which air, liquid, etc. passes","cn":"（体内通气、输液等的）管路，通道","g":"[countable]","sc":"in the body","ex":{"en":"blocked nasal passages","cn":"鼻道堵塞"}},{"en":"a short section from a book, piece of music, etc.","cn":"章节；段落；乐段","g":"[countable]","lab":"US English","sc":"section from book","ex":{"en":"Read the following passage and answer the questions below.","cn":"阅读下面这段文章并回答后面的问题。"}},{"en":"the process of time passing","cn":"（时间的）流逝，推移","g":"[singular]","lab":"literary","sc":"of time","ex":{"en":"Her confidence grew with the passage of time.","cn":"她的信心与日俱增。"}},{"en":"the process of discussing a bill in a parliament so that it can become law","cn":"通过","g":"[singular]","sc":"of bill in parliament","ex":{"en":"The bill is now guaranteed an easy passage through the House of Representatives.","cn":"现在该法案保证能在众议院顺利通过。"}},{"en":"a journey from one place to another by ship","cn":"（乘船的）航程，旅程","g":"[singular]","sc":"journey by ship","ex":{"en":"Her grandfather had worked his passage (= worked on a ship to pay for the journey) to America.","cn":"她的祖父一路在船上打工支付船费来到美国。"}},{"en":"a way through something","cn":"通路；通道","g":"[singular]","sc":"going through","ex":{"en":"The officers forced a passage through the crowd.","cn":"警察在人群中辟开一条通路。"}},{"en":"the action of going across, through or past something","cn":"穿过；穿越","g":"[uncountable]","lab":"formal","sc":"going through","ex":{"en":"Large trees may obstruct the passage of light.","cn":"大树可能阻挡光线穿过。"}},{"en":"the permission to travel across a particular area of land","cn":"通行许可","g":"[uncountable, countable, usually singular]","sc":"going through","ex":{"en":"We were promised (a) speedy passage through the border.","cn":"我们得到了可以快速通过边境的许诺。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"通道；过道；走廊","en":"A passage is a long narrow space with walls or fences on both sides, which connects one place or room with another.","ex":{"en":"Harry stepped into the passage and closed the door behind him.","cn":"哈里走进过道，随手关上了门。"}},{"pos":"N-COUNT 可数名词","cn":"（书、演讲、乐曲等的）段，节，章","en":"A passage in a book, speech, or piece of music is a section of it that you are considering separately from the rest.","ex":{"en":"He reads a passage from Milton.","cn":"他读了一节弥尔顿的诗。"}},{"pos":"N-COUNT 可数名词","cn":"（人体中的）道，通道","en":"A passage is a long narrow hole or tube in your body, which air or liquid can pass along.","ex":{"en":"...cells that line the air passages.","cn":"气管内壁上的细胞"}},{"pos":"N-COUNT 可数名词","cn":"（人群等中的）通道，通路","en":"A passage through a crowd of people or things is an empty space that allows you to move through them.","ex":{"en":"He cleared a passage for himself through the crammed streets","cn":"他在拥挤的街道上挤出了一条通路。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"通过；经过","en":"The passage of someone or something is their movement from one place to another.","ex":{"en":"Germany had not requested Franco's consent for the passage of troops through Spain","cn":"德国没有征求佛朗哥的同意便让军队通过了西班牙。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"过渡","en":"The passage of someone or something is their progress from one situation or one stage in their development to another.","ex":{"en":"...to ease their passage to a market economy.","cn":"使他们更顺利地过渡到市场经济"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（议案等的）通过","en":"The passage of a bill or act is the official acceptance of it by a parliament or legislature.","ex":{"en":"It's been 200 years since the passage of the Bill of Rights.","cn":"《人权法案》通过已经200年了。"}},{"pos":"N-SING 单数名词","cn":"（时间的）推移，流逝","en":"The passage of a period of time is its passing.","ex":{"en":"An asset that increases in value with the passage of time.","cn":"价值与日俱增的资产"}},{"pos":"N-COUNT 可数名词","cn":"航行；航程","en":"A passage is a journey by ship.","ex":{"en":"We'd arrived the day before after a 10-hour passage from Swansea.","cn":"从斯旺西出发航行10小时后，我们于前天到达。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"通行权；通行许可","en":"If you are granted passage through a country or area of land, you are given permission to go through it.","ex":{"en":"Mr Thomas would be given safe passage to and from Jaffna","cn":"托马斯先生可以安全地往来于贾夫纳。"}}]},"examples":[{"en":"Her grandfather had worked his passage (= worked on a ship to pay for the journey) to America.","cn":"她的祖父一路在船上打工支付船费来到美国。"},{"en":"Read the following passage and answer the questions below.","cn":"阅读下面这段文章并回答后面的问题。"}]},"patch":{"media":{"uk":"media/uk/patch__gb_1.mp3","us":"media/us/patch__us_1.mp3"},"oxford":{"phon":"pætʃ","pos":"noun","senses":[{"en":"a small area of something, especially one which is different from the area around it","cn":"色斑；斑点；（与周围不同的）小块，小片","sc":"small area","ex":{"en":"a black dog with a white patch on its back","cn":"背上有一块白斑的黑狗"}},{"en":"a small piece of material that is used to cover a hole in something or to make a weak area stronger, or as decoration","cn":"补丁；补块","sc":"piece of material","ex":{"en":"I sewed patches on the knees of my jeans.","cn":"我在我的牛仔裤膝部打了补丁。"}},{"en":"a piece of material that you wear over an eye, usually because the eye is damaged","cn":"眼罩","sc":"piece of material","ex":{"en":"He had a black patch over one eye.","cn":"他一只眼戴着黑眼罩。"}},{"en":"a piece of material that you sew onto clothes as part of a uniform","cn":"（制服上的）标记，标识","lab":"North American English","sc":"piece of material","ex":{"en":"He wears a patch from his employer, Verizon.","cn":"他戴着一块雇主弗莱森公司的臂章。"}},{"en":"a piece of material that people can wear on their skin to help them to stop smoking","cn":"戒烟贴片","sc":"piece of material","ex":{"en":"nicotine patches","cn":"尼古丁戒烟贴片"}},{"en":"a small piece of land, especially one used for growing vegetables or fruit","cn":"小块土地；（尤指）菜地，果园","sc":"piece/area of land","ex":{"en":"a vegetable patch","cn":"一块菜地"}},{"en":"an area that somebody works in, knows well or comes from","cn":"工作地；熟悉的地区；家乡","lab":"British English, informal，，","sc":"piece/area of land","ex":{"en":"He knows every house in his patch.","cn":"他熟悉他那地区的每一座房子。"}},{"en":"a period of time of the type mentioned, usually a difficult or unhappy one","cn":"一段（艰难）岁月；一段（痛苦）日子","lab":"informal, especially British English，，","sc":"difficult time","ex":{"en":"to go through a bad/difficult/sticky patch","cn":"经历艰难／困难／不幸的时期"}},{"en":"a small piece of code (= instructions that a computer can understand) which can be added to a computer program to improve it or to correct a fault","cn":"修补（程序）；补丁","sc":"in computing","ex":{"en":"Follow the instructions below to download and install the patch.","cn":"按照下面的说明下载并安装修补程序。"}},{"en":"to cover a hole or a worn place, especially in clothes, with a piece of cloth or other material","cn":"打补丁；缝补；修补","ex":{"en":"patched jeans","cn":"带补丁的牛仔裤"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（表面上）与周围不同的部分","en":"A patch on a surface is a part of it which is different in appearance from the area around it.","ex":{"en":"...the bald patch on the top of his head","cn":"他头顶上的秃斑"}},{"pos":"N-COUNT 可数名词","cn":"（种有某种植物或农作物的）小块土地","en":"A patch of land is a small area of land where a particular plant or crop grows.","ex":{"en":"...a patch of land covered in forest.","cn":"一小块林地"}},{"pos":"N-COUNT 可数名词","cn":"补丁；补片","en":"A patch is a piece of material which you use to cover a hole in something.","ex":{"en":"...jackets with patches on the elbows.","cn":"肘部打着补丁的夹克"}},{"pos":"N-COUNT 可数名词","cn":"（保护受伤眼睛的）眼罩","en":"A patch is a small piece of material which you wear to cover an injured eye.","ex":{"en":"She went to the hospital and found him lying down with a patch over his eye.","cn":"她去了医院，发现他躺着，一只眼睛戴着眼罩。"}},{"pos":"VERB 动词","cn":"补缀；修补","en":"If you patch something that has a hole in it, you mend it by fastening a patch over the hole.","ex":{"en":"He and Walker patched the barn roof","cn":"他和沃克补好了谷仓顶。"}},{"pos":"N-COUNT 可数名词","cn":"补丁","en":"A patch is a piece of computer program code written as a temporary solution for dealing with a virus in computer software and distributed by the makers of the original program.","ex":{"en":"Older machines will need a software patch to be loaded to correct the date.","cn":"老些的机器需要下载软件补丁来修改日期。"}},{"pos":"PHRASE 短语","cn":"一段艰难时期","en":"If you have or go through a bad patch or a rough patch, you have a lot of problems for a time.","ex":{"en":"His marriage was going through a bad patch","cn":"他的婚姻当时麻烦不断。"}},{"pos":"PHRASE 短语","cn":"比不上；远不及","en":"If you say that someone or something is not a patch on another person or thing, you mean that they are not as good as that person or thing.","ex":{"en":"He's not a patch on the rest of the Cabinet","cn":"他远比不上内阁的其他成员。"}},{"pos":"","cn":"","en":"相关词组：patch together patch up"}]},"examples":[{"en":"Just to patch the boat up will cost £10 000.","cn":"小船简单地修一下就得花 1 万英镑。"},{"en":"Follow the instructions below to download and install the patch.","cn":"按照下面的说明下载并安装修补程序。"}]},"patronizing":{"oxford":{"phon":"ˈpætrənaɪzɪŋ","pos":"adjective","senses":[{"en":"showing that you think you are better or more intelligent than somebody else","cn":"自以为高人一等的；摆架子的","ex":{"en":"a patronizing smile","cn":"屈尊俯就的一笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自视高人一等的；屈尊俯就的","en":"If someone is patronizing, they speak or behave towards you in a way that seems friendly, but which shows that they think they are superior to you.","ex":{"en":"The tone of the interview was unnecessarily patronizing.","cn":"面试官的口气让人觉得受了他多大恩惠似的，实在没有必要。"}}]},"media":{"uk":"media/uk/patronizing__gb_1.mp3","us":"media/us/patronizing__us_1.mp3"},"examples":[{"en":"I was only trying to explain; I didn't want to sound patronizing.","cn":"我只是想解释一下而已，绝无自诩清高之意。"},{"en":"He patted her hand patronizingly.","cn":"他以上级姿态拍了拍她的手。"}]},"para":{"media":{"uk":"media/uk/para__gb_1.mp3","us":"media/us/para__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"空降兵；伞兵","en":"A para is a paratrooper .","ex":{"en":"...some guys just out of the paras.","cn":"一些刚刚退役的伞兵"}}]},"oxford":{"phon":"ˈpærə","pos":"noun","senses":[{"en":"a member of the paratroops","cn":"伞兵；空降兵"},{"en":"outside; beyond","cn":"在…之外；超出；越出","ex":{"en":"paranormal","cn":"超常的"},"pos":"prefix"},{"en":"similar to but not official or not fully qualified","cn":"准；近似","ex":{"en":"paramilitary","cn":"准军事的"},"pos":"prefix"}]}},"pays":{"oxford":{"phon":"peɪ","pos":"verb","senses":[{"en":"to give sb money for work, goods, services, etc.","cn":"付费；付酬"},{"en":"to give sb money that you owe them","cn":"交纳；偿还"}]},"media":{"uk":"media/uk/pay__gb_1.mp3","us":"media/us/pay__us_1.mp3"}},"padding":{"media":{"uk":"media/uk/padding__gb_1.mp3","us":"media/us/padding__us_1.mp3"},"oxford":{"phon":"ˈpædɪŋ","pos":"noun","senses":[{"en":"soft material that is placed inside something to make it more comfortable or to change its shape","cn":"衬料；衬垫","ex":{"en":"The shoes have thick padding at the ankle to offer greater support.","cn":"鞋子的脚踝处有厚实的衬垫，可以提供更大的支撑。"}},{"en":"words that are used to make a speech, piece of writing, etc. longer, but that do not contain any interesting information","cn":"赘语；废话；凑篇幅的文字","ex":{"en":"Some of the quotations are useful, others are little more than padding.","cn":"其中一些引文很有用，另一些则只不过是补充而已。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（柔软的）垫料，衬料","en":"Padding is soft material which is put on something or inside it in order to make it less hard, to protect it, or to give it a different shape.","ex":{"en":"...the foam rubber padding on the headphones","cn":"头戴式耳机上的泡沫橡胶垫料"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冗词赘句；凑篇幅的废话","en":"Padding is unnecessary words or information used to make a piece of writing or a speech longer.","ex":{"en":"Of the sonnet eleven of the lines are mere padding and say nothing.","cn":"那首十四行诗中有11行都是废话，毫无意义。"}}]},"examples":[{"en":"a helmet with protective padding","cn":"带有保护衬垫的头盔"}]},"participant":{"oxford":{"phon":"pɑːˈtɪsɪpənt","pos":"noun","senses":[{"en":"a person who is taking part in an activity or event","cn":"参与者；参加者","ex":{"en":"The average age of study participants was 48 years.","cn":"受试者的平均年龄为 48 岁。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"参与者；参加者","en":"The participants in an activity are the people who take part in it.","ex":{"en":"40 of the course participants are offered employment with the company","cn":"上这门课的人中有40个被该公司聘用。"}}]},"media":{"uk":"media/uk/participant__gb_1.mp3","us":"media/us/participant__us_1.mp3"},"examples":[{"en":"He has been an active participant in the discussion.","cn":"他一直积极参与这次讨论。"},{"en":"an active participant in the negotiations","cn":"积极参与谈判的人"}]},"paints":{"oxford":{"phon":"peɪnt","pos":"noun","senses":[{"en":"a liquid that is put on surfaces to give them a particular colour; a layer of this liquid when it has dried on a surface","cn":"油漆；油漆涂层"},{"en":"tubes or blocks of paint used for painting pictures","cn":"绘画颜料"}]},"media":{"uk":"media/uk/paint__gb_1.mp3","us":"media/us/paint__us_1.mp3","img":["media/ldoce/img/paints.jpg"]}},"patients":{"oxford":{"phon":"ˈpeɪʃnt","pos":"noun","senses":[{"en":"a person who is receiving medical treatment, especially in a hospital","cn":"接受治疗者，病人（尤指医院里的）"},{"en":"a person who receives treatment from a particular doctor, dentist, etc. （","cn":"某个医生或牙医等的）病人"}]},"media":{"uk":"media/uk/patient__gb_1.mp3","us":"media/us/patient__us_1.mp3"}},"patience":{"media":{"uk":"media/uk/patience__gb_1.mp3","us":"media/us/patience__us_1.mp3"},"oxford":{"phon":"ˈpeɪʃns","pos":"noun","senses":[{"en":"the ability to stay calm and accept a delay or something annoying without complaining","cn":"耐心；忍耐力","ex":{"en":"She has little patience with (= will not accept or consider) such views.","cn":"她很难接受这类观点。"}},{"en":"the ability to spend a lot of time doing something difficult that needs a lot of attention and effort","cn":"毅力；坚忍；恒心","ex":{"en":"It takes time and patience to photograph wildlife.","cn":"拍摄野生生物要肯花时间，还要有毅力。"}},{"en":"a card game for only one player","cn":"单人纸牌游戏","lab":"British English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"容忍；耐心；忍耐力","en":"If you have patience, you are able to stay calm and not get annoyed, for example when something takes a long time, or when someone is not doing what you want them to do.","ex":{"en":"He doesn't have the patience to wait","cn":"他没有耐心等待。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"单人纸牌游戏","en":"Patience is a card game for only one player.","ex":{"en":"He would often sit and play patience.","cn":"他常常坐着玩单人纸牌游戏。"}},{"pos":"PHRASE 短语","cn":"考验…的耐心；使忍无可忍","en":"If someone tries your patience or tests your patience, they annoy you so much that it is very difficult for you to stay calm.","ex":{"en":"He tended to stutter, which tried her patience","cn":"他老结巴，这叫她难以忍受。"}}]},"examples":[{"en":"Teaching children with special needs requires patience and understanding.","cn":"教导有特殊需要的儿童需要耐心和体谅。"},{"en":"It takes time and patience to photograph wildlife.","cn":"拍摄野生动物要肯花时间，还要有毅力。"}]},"page":{"media":{"uk":"media/uk/page__gb_1.mp3","us":"media/us/page__us_1.mp3"},"oxford":{"phon":"peɪdʒ","pos":"noun","senses":[{"en":"one side or both sides of a sheet of paper in a book, magazine, etc.","cn":"（书刊或纸张的）页，面，张，版","ex":{"en":"Turn to page 64.","cn":"翻到第 64 页。"}},{"en":"a section of data or information that can be shown on a computer screen at any one time","cn":"（计算机的）页面，版面","ex":{"en":"to visit/view a page","cn":"访问／查看页面"}},{"en":"an important event or period of history","cn":"历史篇章，历史篇页（指历史大事或时期）","lab":"literary","ex":{"en":"a glorious page of Arab history","cn":"阿拉伯历史上光辉的篇章"}},{"en":"a small boy who helps or follows a bride during a marriage ceremony","cn":"新娘的伴童；小男傧相","lab":"especially North American English"},{"en":"a boy or young man, usually in uniform, employed in a hotel to open doors, deliver messages for people, etc.","cn":"（旅馆的）行李员，门童","lab":"old-fashioned"},{"en":"a student who works as an assistant to a member of the US Congress","cn":"（美国议员的）青年助理（本身为学生）","lab":"North American English"},{"en":"a boy or young man who worked for a knight while training to be a knight himself","cn":"学习骑士（接受训练期间做侍从，可晋升骑士）"},{"en":"to call somebody’s name over a public address system in order to find them and give them a message","cn":"（在公共传呼系统上）呼叫","ex":{"en":"Why don't you have him paged at the airport?","cn":"你为何不在机场扩音喇叭上呼叫他呢？"},"pos":"verb"},{"en":"to contact somebody by sending a message to their pager","cn":"用传呼机传呼（某人）","ex":{"en":"Page Dr Green immediately.","cn":"立即传呼格林医生。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（书、杂志、报纸等的）页，面，版","en":"A page is one side of one of the pieces of paper in a book, magazine, or newspaper. Each page usually has a number printed at the top or bottom.","ex":{"en":"Where's your book? Take it out and turn to page 4.","cn":"你的书呢？拿出来，翻到第4页。"}},{"pos":"N-COUNT 可数名词","cn":"（书、杂志、报纸等的）纸页","en":"The pages of a book, magazine, or newspaper are the pieces of paper it consists of.","ex":{"en":"He turned the pages of his notebook","cn":"他翻着笔记本。"}},{"pos":"N-COUNT 可数名词","cn":"（历史的）一页（指重大事件或重要时期）","en":"You can refer to an important event or period of time as a page of history.","ex":{"en":"...a new page in the country's political history.","cn":"该国政治史上崭新的一页"}},{"pos":"VERB 动词","cn":"（在公共场合通过广播）呼叫","en":"If someone who is in a public place is paged, they receive a message, often over a speaker, telling them that someone is trying to contact them.","ex":{"en":"He was paged repeatedly as the flight was boarding","cn":"航班登机时，广播里反复呼叫他。"}},{"pos":"N-COUNT 可数名词","cn":"（婚礼上新娘的）男伴童，小男傧相","en":"A page is a small boy who accompanies the bride at a wedding."},{"pos":"N-COUNT 可数名词","cn":"（美国国会或州立法会的）青年助理","en":"A page is a young person who takes messages or does small jobs for members of the United States Congress or state legislatures."},{"pos":"N-COUNT 可数名词","cn":"（旧时做骑士侍从的）实习骑士","en":"In former times, a page was a young boy who was a knight's servant and was learning to be a knight."}]},"examples":[{"en":"Why don't you have him paged at the airport?","cn":"你为何不在机场扩音喇叭上呼叫他呢？"},{"en":"Someone has torn a page out of this book.","cn":"有人从这本书里撕掉了一张。"}]},"painting":{"media":{"img":["media/pic/creativehobbies_comp.jpg","media/thumb/painting.jpg"],"uk":"media/uk/painting__gb_1.mp3","us":"media/us/painting__us_1.mp3"},"oxford":{"phon":"ˈpeɪntɪŋ","pos":"noun","senses":[{"en":"a picture that has been painted","cn":"油画；画作","g":"[countable]","lab":"US English","ex":{"en":"a watercolour/an acrylic painting","cn":"水彩画/丙烯画"}},{"en":"the act or art of using paint to produce pictures","cn":"作画；绘画","g":"[uncountable]","ex":{"en":"Her hobbies include music and painting.","cn":"她的爱好包括音乐和绘画。"}},{"en":"the act of putting paint onto the surface of objects, walls, etc.","cn":"涂漆；刷油漆","g":"[uncountable]","ex":{"en":"painting and decorating","cn":"油漆和装潢"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"画作","en":"A painting is a picture which someone has painted.","ex":{"en":"...a large oil-painting of Queen Victoria.","cn":"维多利亚女王的大幅油画"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绘画","en":"Painting is the activity of painting pictures.","ex":{"en":"...two hobbies she really enjoyed, painting and gardening.","cn":"她的两大嗜好: 绘画和园艺"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粉刷；上漆","en":"Painting is the activity of painting doors, walls, and some other parts of buildings.","ex":{"en":"...painting and decorating.","cn":"粉刷和装潢"}}]},"examples":[{"en":"Her hobbies include music and painting.","cn":"她的爱好包括音乐和绘画。"},{"en":"a collection of paintings by American artists","cn":"美国艺术家绘画作品集"}]},"party":{"media":{"uk":"media/uk/party__gb_1.mp3","us":"media/us/party__us_1.mp3"},"oxford":{"phon":"ˈpɑːti","pos":"noun","senses":[{"en":"a social occasion, often in a person’s home, at which people eat, drink, talk, dance and enjoy themselves","cn":"聚会；宴会；联欢会；派对","g":"[countable]","ex":{"en":"a dinner/tea/cocktail party","cn":"晚宴；茶会；鸡尾酒会"}},{"en":"a political organization that you can vote for in elections and whose members have the same aims and ideas","cn":"政党；党派","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"Do you belong to a political party?","cn":"你加入哪个政党了吗？"}},{"en":"a group of people who are doing something together such as travelling or visiting somewhere","cn":"（一起旅行或参观等的）群，队，组","g":"[countable + singular or plural verb]","ex":{"en":"The school is taking a party of 40 children to France.","cn":"学校将带领一个 40 人的儿童团队前往法国。"}},{"en":"one of the people or groups of people involved in a legal agreement or argument","cn":"（契约或争论的）当事人，一方","g":"[countable]","lab":"formal","ex":{"en":"the guilty/innocent party","cn":"有罪的／无罪的一方"}},{"en":"to enjoy yourself, especially by eating, drinking alcohol and dancing","cn":"寻欢作乐；吃喝玩乐","g":"[intransitive]","lab":"informal","ex":{"en":"They were out partying every night.","cn":"他们每晚都外出寻欢作乐。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"政党；党派","en":"A party is a political organization whose members have similar aims and beliefs. Usually the organization tries to get its members elected to the government of a country.","ex":{"en":"...a member of the Labour party.","cn":"工党党员"}},{"pos":"N-COUNT 可数名词","cn":"聚会；派对","en":"A party is a social event, often in someone's home, at which people enjoy themselves doing things such as eating, drinking, dancing, talking, or playing games.","ex":{"en":"The couple met at a party","cn":"那对情侣是在一个派对上认识的。"}},{"pos":"VERB 动词","cn":"尽情欢乐；纵情狂欢","en":"If you party, you enjoy yourself doing things such as going out to parties, drinking, dancing, and talking to people.","ex":{"en":"They come to eat and drink, to swim, to party. Sometimes they never go to bed","cn":"他们来吃喝、游泳、狂欢，有时都不睡觉。"}},{"pos":"N-COUNT 可数名词","cn":"群；伙；批","en":"A party of people is a group of people who are doing something together, for example travelling together.","ex":{"en":"They became separated from their party.","cn":"他们和伙伴们分开了。"}},{"pos":"N-COUNT 可数名词","cn":"（法律协议或辩论中的）一方","en":"One of the people involved in a legal agreement or dispute can be referred to as a particular party.","ex":{"en":"It has to be proved that they are the guilty party.","cn":"必须证明他们是过错方。"}},{"pos":"PHRASE 短语","cn":"参与，参加（行动或协议）","en":"Someone who is a party to or is party to an action or agreement is involved in it, and therefore partly responsible for it.","ex":{"en":"Crook had resigned his post rather than be party to such treachery.","cn":"克鲁克已经辞职了，不愿参与这种背信弃义的行为。"}}]},"examples":[{"en":"The contract can be terminated by either party with three months' notice.","cn":"合同的任何一方如提前三个月通知，均可终止本合同。"},{"en":"What Hislop brought to the party was real commitment and energy.","cn":"希斯洛普对党的贡献是他全身心的投入和十足的干劲。"}]},"particular":{"media":{"uk":"media/uk/particular__gb_1.mp3","us":"media/us/particular__us_1.mp3"},"oxford":{"phon":"pəˈtɪkjələ(r)","pos":"adjective","senses":[{"en":"used to emphasize that you are referring to one individual person, thing or type of thing and not others","cn":"专指的，特指的（与泛指相对）","g":"[only before noun]","ex":{"en":"There is one particular patient I'd like you to see.","cn":"我想让你见一个病人。"}},{"en":"greater than usual; special","cn":"不寻常的；格外的；特别的","g":"[only before noun]","ex":{"en":"We must pay particular attention to this point.","cn":"我们必须特别注意这一点。"}},{"en":"very definite about what you like and careful about what you choose","cn":"讲究；挑剔","ex":{"en":"She's very particular about her clothes.","cn":"她对衣着特别挑剔。"}},{"en":"a fact or detail, especially one that is officially written down","cn":"（正式记下的）细节，详情","g":"[usually plural]","ex":{"en":"The police officer took down all the particulars of the burglary.","cn":"这名警察记下了窃案发生的详细情况。"},"pos":"noun"},{"en":"written information and details about a property, business, job, etc.","cn":"详细资料；详细介绍材料","g":"[plural]","ex":{"en":"Application forms and further particulars are available from the Personnel Office.","cn":"申请表格及其他详细资料可向人事部索取。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"特定的；特指的","en":"You use particular to emphasize that you are talking about one thing or one kind of thing rather than other similar ones.","ex":{"en":"I remembered a particular story about a postman who was a murderer","cn":"我记得有个故事，讲的是一个邮递员杀人的事情。"}},{"pos":"ADJ 形容词","cn":"特殊的；特别的；独特的","en":"If a person or thing has a particular quality or possession, it is distinct and belongs only to them.","ex":{"en":"I have a particular responsibility to ensure I make the right decision","cn":"我肩负特殊责任，必须确保自己作出的决定是正确的。"}},{"pos":"ADJ 形容词","cn":"格外的；特别的；尤其的","en":"You can use particular to emphasize that something is greater or more intense than usual.","ex":{"en":"Particular emphasis will be placed on oral language training.","cn":"将会特别强调口语训练。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"挑剔的；讲究的","en":"If you say that someone is particular, you mean that they choose things and do things very carefully, and are not easily satisfied.","ex":{"en":"Ted was very particular about the colors he used.","cn":"特德在用色上非常讲究。"}},{"pos":"PHRASE 短语","cn":"尤其；特别","en":"You use in particular to indicate that what you are saying applies especially to one thing or person.","ex":{"en":"The situation in Ethiopia in particular is worrying","cn":"埃塞俄比亚的局势尤其令人担忧。"}},{"pos":"PHRASE 短语","cn":"没什么重要（或特别）的事物（或人）","en":"You use nothing in particular or nobody in particular to mean nothing or nobody important or special.","ex":{"en":"I went along thinking of nothing in particular only looking at things around me","cn":"我一路走着，没想什么特别的事，只是四下张望着。"}}]},"examples":[{"en":"Application forms and further particulars are available from the Personnel Office.","cn":"申请表格及其他详细资料可向人事部索取。"},{"en":"The new contract will be the same in every particular as the old one.","cn":"新合同与旧合同的各项细节将完全相同。"}]},"package":{"oxford":{"phon":"ˈpækɪdʒ","pos":"noun","senses":[{"en":"something that is wrapped in paper or put into a thick envelope so that it can be sent by mail, carried easily, or given as a present","cn":"包裹；小包","lab":"especially North American English","ex":{"en":"A large package has arrived for you.","cn":"你有一个大包裹来了。"}},{"en":"a box, bag, etc. in which things are wrapped or packed; the contents of a box, etc.","cn":"包；盒；袋；包装好的东西","lab":"North American English","ex":{"en":"Check the list of ingredients on the side of the package.","cn":"检查一下包装盒侧面的成分清单。"}},{"en":"a set of items or ideas that must be bought or accepted together","cn":"（必须整体接收的）一套东西，一套建议；一揽子交易","ex":{"en":"an aid/a rescue package","cn":"整体援助／救援方案"}},{"en":"the pay and other benefits that somebody gets from their employer","cn":"薪酬待遇；总薪酬","ex":{"en":"Some CEOs received pay packages of over $10 million.","cn":"有些首席执行官获得了超过 1 000 万美元的总薪酬。"}},{"en":"a set of related programs for a particular type of task, sold and used as a single unit","cn":"软件包","lab":"computing","ex":{"en":"The system came with a database software package.","cn":"本系统配有数据库软件包。"}},{"en":"to put something into a box, bag, etc. to be sold or transported","cn":"将…包装好","ex":{"en":"packaged food/goods","cn":"包装好的食品／商品"},"pos":"verb"},{"en":"to present somebody/something in a particular way","cn":"包装成；使改头换面；把…装扮为","ex":{"en":"politicians who are packaged and presented to the public","cn":"被包装并呈现给公众的政客"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"包裹","en":"A package is a small parcel.","ex":{"en":"I tore open the package.","cn":"我撕开了那个包裹。"}},{"pos":"N-COUNT 可数名词","cn":"包装盒；包装袋","en":"A package is a small container in which a quantity of something is sold. Packages are either small boxes made of thin cardboard, or bags or envelopes made of paper or plastic.","ex":{"en":"...a package of doughnuts","cn":"一包炸面圈"}},{"pos":"N-COUNT 可数名词","cn":"一组建议；一揽子提议","en":"A package is a set of proposals that are made by a government or organization and which must be accepted or rejected as a group.","ex":{"en":"The government has announced a package of measures to help the British film industry","cn":"政府已经公布了帮助英国电影产业的一揽子措施。"}},{"pos":"VERB 动词","cn":"（销售前）包装（产品）","en":"When a product is packaged, it is put into containers to be sold.","ex":{"en":"The beans are then ground and packaged for sale as ground coffee","cn":"然后那些咖啡豆被磨碎，包装好作为咖啡粉出售。"}},{"pos":"VERB 动词","cn":"（为提高吸引力或趣味性而）包装","en":"If something is packaged in a particular way, it is presented or advertised in that way in order to make it seem attractive or interesting.","ex":{"en":"A city has to be packaged properly to be attractive to tourists.","cn":"城市必须进行适当的包装以吸引游客。"}},{"pos":"N-COUNT 可数名词","cn":"包价（旅游）","en":"A package tour, or in British English a package holiday, is a holiday arranged by a travel company in which your travel and your accommodation are booked for you.","ex":{"en":"If you are on a package holiday, your travel company's rep should act on your behalf.","cn":"如果你是参加包价旅游，你的旅行社代表将代为行事。"}}]},"media":{"uk":"media/uk/package__gb_1.mp3","us":"media/us/package__us_1.mp3","img":["media/ldoce/img/parcel.jpg"]},"examples":[{"en":"We package our products in recyclable materials.","cn":"我们用可回收的材料包装我们的产品。"},{"en":"Check the list of ingredients on the side of the package.","cn":"检查一下包装盒侧面的成分清单。"}]},"parent":{"oxford":{"phon":"ˈpeərənt","pos":"noun","senses":[{"en":"a person’s father or mother","cn":"父亲；母亲","g":"[usually plural]","ex":{"en":"He's still living with his parents.","cn":"他还和父母住在一起。"}},{"en":"an animal or a plant which produces other animals or plants","cn":"（动、植物的）亲本，亲代，父本，母本","ex":{"en":"the parent bird/tree","cn":"亲代鸟；亲代树"}},{"en":"an organization that produces and owns or controls smaller organizations of the same type","cn":"创始机构；母公司；总部","ex":{"en":"a parent bank and its subsidiaries","cn":"总行及其附属银行"}},{"en":"to care for your child or children","cn":"抚养；育儿","ex":{"en":"They'd never parented a toddler and a newborn at the same time before.","cn":"他们此前从未同时抚养过正学步的幼儿和刚出生的婴儿。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"父母","en":"Your parents are your mother and father.","ex":{"en":"Children need their parents","cn":"孩子们需要父母。"}},{"pos":"ADJ 形容词","cn":"创始的；母公司的；总公司的","en":"An organization's parent organization is the organization that created it and usually still controls it.","ex":{"en":"Each unit including the parent company has its own, local management.","cn":"包括母公司在内，每个单位都有自己的地方管理层。"}},{"pos":"ADJ 形容词","cn":"（动物、植物或有机体）亲本的，亲代的","en":"The parent animal, plant, or organism of a particular animal, plant or organism is the one that it comes from or is produced by.","ex":{"en":"Parent birds began to hunt for food for their young.","cn":"亲鸟开始为幼鸟寻找食物。"}}]},"media":{"uk":"media/uk/parent__gb_1.mp3","us":"media/us/parent__us_1.mp3"},"examples":[{"en":"Sue and Ben have recently become parents.","cn":"苏和本最近当了爸爸妈妈了。"},{"en":"He's still living with his parents.","cn":"他还和父母住在一起。"}]},"packed":{"media":{"uk":"media/uk/packed__gb_1.mp3","us":"media/us/packed__us_1.mp3"},"oxford":{"phon":"pækt","pos":"adjective","senses":[{"en":"extremely full of people","cn":"异常拥挤的；挤满人的","ex":{"en":"The restaurant was packed.","cn":"餐馆里坐满了客人。"}},{"en":"containing a lot of a particular thing","cn":"有大量…的；…极多的","ex":{"en":"Our new brochure is packed full of inspirational ideas.","cn":"我们新的小册子中有许多颇具创意的点子。"}},{"en":"pressed closely together","cn":"紧密压在一起的","ex":{"en":"The birds' nests are lined with tightly packed leaves.","cn":"鸟巢有一层压得密密实实的树叶。"}},{"en":"having put everything you need into cases, boxes, etc. before you go somewhere","cn":"收拾好行李","g":"[not before noun]","lab":"informal","ex":{"en":"I'm all packed and ready to go.","cn":"我已打点好行装，准备出发了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常拥挤的","en":"A place that is packed is very crowded.","ex":{"en":"From 3.30 until 7pm, the shop is packed","cn":"从下午3点30分到7点，那家商店非常拥挤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满…的；富含…的","en":"Something that is packed with things contains a very large number of them.","ex":{"en":"The Encyclopedia is packed with clear illustrations and over 250 recipes","cn":"那本百科全书有很多清晰的插图和250多个食谱。"}}]},"examples":[{"en":"The birds' nests are lined with tightly packed leaves.","cn":"鸟巢有一层压得密密实实的树叶。"},{"en":"I'm all packed and ready to go.","cn":"我已打点好行装，准备出发了。"}]},"patronage":{"media":{"uk":"media/uk/patronage__gb_1.mp3","us":"media/us/patronage__us_1.mp3"},"oxford":{"phon":"ˈpætrənɪdʒ","pos":"noun","senses":[{"en":"the support, especially financial, that is given to a person or an organization by a patron","cn":"资助；赞助","ex":{"en":"Patronage of the arts comes from businesses and private individuals.","cn":"对艺术的资助来自企业和个人。"}},{"en":"the system by which an important person gives help or a job to somebody in return for their support","cn":"（掌权者给予提挈以换取支持的）互惠互利","ex":{"en":"Recruits are selected on merit, not through political patronage.","cn":"新成员是择优而不是通过政治任命选出来的。"}},{"en":"the support that a person gives a shop, restaurant, etc. by spending money there","cn":"惠顾；光顾","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"资助；赞助","en":"Patronage is the support and money given by someone to a person or a group such as a charity.","ex":{"en":"...government patronage of the arts in Europe","cn":"欧洲政府对艺术的资助"}}]},"examples":[{"en":"Patronage of the arts comes from businesses and private individuals.","cn":"对艺术的资助来自企业和个人。"},{"en":"Thank you for your patronage.","cn":"感谢您的惠顾。"}]},"participating":{"oxford":{"phon":"pɑːˈtɪsɪpeɪt","pos":"verb","senses":[{"en":"( rather formal ) to take part in or become involved in an activity","cn":"参加；参与"}]}},"past":{"media":{"uk":"media/uk/past__gb_1.mp3","us":"media/us/past__us_1.mp3"},"oxford":{"phon":"pɑːst","pos":"adjective","senses":[{"en":"gone by in time","cn":"过去的；昔日的","ex":{"en":"in past years/centuries","cn":"在过去的几年／几个世纪中"}},{"en":"gone by recently; just ended","cn":"刚过去的；刚结束的","g":"[only before noun]","ex":{"en":"in the past year/month/week","cn":"在过去一年；在上个月；在上星期"}},{"en":"belonging to an earlier time","cn":"从前的；以往的","g":"[only before noun]","ex":{"en":"From past experience I'd say he'd probably forgotten the time.","cn":"根据过去的经验，我想他可能把时间忘了。"}},{"en":"connected with the form of a verb used to express actions in the past","cn":"过去时的；过去式的","g":"[only before noun]","lab":"grammar","ex":{"en":"the past tense","cn":"过去时"}},{"en":"the time that has gone by; things that happened in an earlier time","cn":"过去；昔日；过去的事情","g":"[singular]","ex":{"en":"I used to go there often in the past.","cn":"过去我常去那里。"},"pos":"noun"},{"en":"a person’s past life or career; the history of a place, country, group, etc.","cn":"（某人、某地、某国等的）过去，历史","g":"[countable]","ex":{"en":"We don't know anything about his past.","cn":"我们对他的过去一无所知。"},"pos":"noun"},{"en":"the form of a verb used to describe actions in the past","cn":"过去时；过去式","g":"[singular]","lab":"grammar","ex":{"en":"The past of ‘shine’ is ‘shone’.","cn":"shine 的过去式是 shone。"},"pos":"noun"},{"en":"later than something","cn":"晚于；在…之后","lab":"North American English also","ex":{"en":"half past two","cn":"两点半"},"pos":"preposition"},{"en":"on or to the other side of somebody/something","cn":"在另一边；到另一侧","ex":{"en":"We live in the house just past the church.","cn":"我们就住在挨着教堂那边的房子里。"},"pos":"preposition"},{"en":"above or further than a particular point or stage","cn":"多于；超过","ex":{"en":"Unemployment is now past the 3 million mark.","cn":"失业人数现在已超过了 300 万大关。"},"pos":"preposition"},{"en":"from one side of something to the other","cn":"从一侧到另一侧；经过","ex":{"en":"She smiled at me as she walked past.","cn":"她走过时对我微笑。"},"pos":"adverb"},{"en":"used to describe time passing","cn":"（时间）过去，逝去","ex":{"en":"A week went past and nothing had changed.","cn":"一个星期过去了，情况毫无变化。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"过去；往昔","en":"The past is the time before the present, and the things that have happened.","ex":{"en":"In the past, about a third of the babies born to women with diabetes were lost","cn":"过去，患有糖尿病的女性生下的孩子中约有1/3夭折了。"}},{"pos":"N-COUNT 可数名词","cn":"经历；过去之事","en":"Your past consists of all the things that you have done or that have happened to you.","ex":{"en":"...revelations about his past.","cn":"曝光他的过去"}},{"pos":"ADJ 形容词","cn":"过去的；以前的","en":"Past events and things happened or existed before the present time.","ex":{"en":"I knew from past experience that alternative therapies could help","cn":"根据过去的经验，我知道替代疗法可能有用。"}},{"pos":"ADJ 形容词","cn":"刚过去的","en":"You use past to talk about a period of time that has just finished. For example, if you talk about the past five years, you mean the period of five years that has just finished.","ex":{"en":"Most shops have remained closed for the past three days.","cn":"过去3天大多数商店一直都没有营业。"}},{"pos":"ADJ 形容词","cn":"过去了的；结束了的","en":"If a situation is past, it has ended and no longer exists.","ex":{"en":"Many economists believe the worst of the economic downturn is past.","cn":"很多经济学家认为经济衰退最糟糕的时期已经过去了。"}},{"pos":"ADJ 形容词","cn":"（动词）过去时的","en":"In grammar, the past tenses of a verb are the ones used to talk about things that happened at some time before the present. The simple past tense uses the past form of a verb, which for regular verbs ends in '-ed', as in 'They walked back to the car'."},{"pos":"PREP 介词","cn":"（钟点）过（…分）","en":"You use past when you are stating a time which is thirty minutes or less after a particular hour. For example, if it is twenty past six, it is twenty minutes after six o'clock.","ex":{"en":"It's ten past eleven","cn":"现在是11点过10分。"}},{"pos":"PREP 介词","cn":"在…之后；晚于","en":"If it is past a particular time, it is later than that time.","ex":{"en":"It was past midnight","cn":"午夜已过。"}},{"pos":"PREP 介词","cn":"经过","en":"If you go past someone or something, you go near them and keep moving, so that they are then behind you.","ex":{"en":"I dashed past him and out of the door","cn":"我从他身边跑过，夺门而出。"}},{"pos":"PREP 介词","cn":"越过","en":"If you look or point past a person or thing, you look or point at something behind them.","ex":{"en":"She stared past Christine at the bed.","cn":"她的目光越过克里斯蒂娜盯着床。"}},{"pos":"PREP 介词","cn":"在…的另一侧","en":"If something is past a place, it is on the other side of it.","ex":{"en":"Go north on I-15 to the exit just past Barstow","cn":"沿着15号州际公路一直向北，一过巴斯托就从出口驶出。"}},{"pos":"PREP 介词","cn":"超过，超出（某一点或阶段）","en":"If someone or something is past a particular point or stage, they are no longer at that point or stage.","ex":{"en":"He was well past retirement age","cn":"他早过了退休年龄。"}},{"pos":"PREP 介词","cn":"再也无法","en":"If you are past doing something, you are no longer able to do it. For example, if you are past caring, you do not care about something any more because so many bad things have happened to you.","ex":{"en":"She was past caring about anything by then and just wanted the pain to end","cn":"那时，她已经什么都不在乎了，只盼着疼痛能够止住。"}},{"pos":"PHRASE 短语","cn":"（某人做某事）并不令人意外","en":"If you say that you would not put it past someone to do something bad, you mean that you would not be surprised if they did it because you think their character is bad.","ex":{"en":"You know what she's like. I wouldn't put it past her to call the police and say I stole them.","cn":"你知道她是个什么样的人。要是她打电话报警说我偷了它们，一点儿也不奇怪。"}}]},"examples":[{"en":"Let's forget about who was more to blame — it's all past history.","cn":"咱们且忘掉更该责怪谁吧，那都是陈年旧账了。"},{"en":"In some sports you're past it by the age of 25.","cn":"在某些运动中，人过 25 岁就难有作为了。"}]},"passive":{"media":{"uk":"media/uk/passive__gb_1.mp3","us":"media/us/passive__us_1.mp3"},"oxford":{"phon":"ˈpæsɪv","pos":"adjective","senses":[{"en":"accepting what happens or what people do without trying to change anything or oppose them","cn":"消极的；被动的","ex":{"en":"He played a passive role in the relationship.","cn":"他在他们的关系中处于被动地位。"}},{"en":"connected with the form of a verb used when the subject is affected by the action of the verb, for example He was bitten by a dog.","cn":"（动词形式）被动语态的","lab":"grammar"},{"en":"the form of a verb used when the subject is affected by the action of the verb","cn":"动词被动形式；被动语态","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"被动的；顺从的；听之任之的","en":"If you describe someone as passive, you mean that they do not take action but instead let things happen to them.","ex":{"en":"His passive attitude made things easier for me","cn":"他顺从的态度让我做起事来要轻松些。"}},{"pos":"ADJ 形容词","cn":"消极的","en":"A passive activity involves watching, looking at, or listening to things rather than doing things.","ex":{"en":"They want less passive ways of filling their time.","cn":"他们想找些更为积极的方式来打发时间。"}},{"pos":"ADJ 形容词","cn":"（抵抗）非暴力的","en":"Passive resistance involves showing opposition to the people in power in your country by not co-operating with them and protesting in non-violent ways.","ex":{"en":"They made it clear that they would only exercise passive resistance in the event of a military takeover.","cn":"他们声明一旦发生军事接管，他们只会采取非暴力抵抗。"}},{"pos":"N-SING 单数名词","cn":"被动态；被动式","en":"In grammar, the passive or the passive voice is formed using 'be' and the past participle of a verb. The subject of a passive clause does not perform the action expressed by the verb but is affected by it. For example, in 'He's been murdered', the verb is in the passive."}]},"examples":[{"en":"He played a passive role in the relationship.","cn":"他在他们的关系中处于被动地位。"},{"en":"a passive observer of events","cn":"列席观察员"}]},"packages":{"oxford":{"phon":"ˈpækɪdʒ","pos":"noun","senses":[{"en":"( NAmE ) a box, bag, etc. in which things are wrapped or packed; the contents of a box etc.","cn":"包；盒；袋；包装好的东西"},{"en":"a set of items or ideas that must be bought or accepted together （","cn":"必须整体接收的）一套东西，一套建议；一揽子交易"}]}},"parade":{"media":{"uk":"media/uk/parade__gb_1.mp3","us":"media/us/parade__us_1.mp3"},"oxford":{"phon":"pəˈreɪd","pos":"noun","senses":[{"en":"a public celebration of a special day or event, usually with bands in the streets and decorated vehicles","cn":"游行","g":"[countable]","sc":"public celebration","ex":{"en":"the Lord Mayor’s parade","cn":"欢迎新市长大游行"}},{"en":"a formal occasion when soldiers march or stand in lines so that they can be inspected (= looked at and approved) by their officers or other important people","cn":"检阅；阅兵","g":"[countable, uncountable]","lab":"figurative","sc":"of soldiers","ex":{"en":"a military parade","cn":"军事检阅"}},{"en":"a series of things or people","cn":"一系列（人或事）","g":"[countable]","sc":"series","ex":{"en":"Each generation passes through a similar parade of events.","cn":"每一代人都要经历一系列类似的事。"}},{"en":"a street with a row of small shops","cn":"有一排小商店的街道","g":"[countable]","lab":"especially British English","sc":"row of shops","ex":{"en":"a shopping parade","cn":"购物街"}},{"en":"an obvious display of something, particularly in order to impress other people","cn":"夸示；炫耀","g":"[countable, usually singular]","lab":"often disapproving","sc":"wealth/knowledge","ex":{"en":"Social media is a constant parade of wealth, happiness, success and vanity.","cn":"社交媒体是财富、幸福、成功和虚荣的不断展示。"}},{"en":"to walk somewhere in a formal group of people, in order to celebrate or protest about something","cn":"游行；游行庆祝；游行示威","g":"[intransitive]","sc":"walk to celebrate/protest","ex":{"en":"The victorious team will parade through the city tomorrow morning.","cn":"明天上午获胜队将在城内举行庆祝游行。"},"pos":"verb"},{"en":"to walk around in a way that makes other people notice you","cn":"招摇过市；大摇大摆","g":"[intransitive]","sc":"show in public","ex":{"en":"People were parading up and down showing off their finest clothes.","cn":"人们走来走去，炫耀着他们最漂亮的服装。"},"pos":"verb"},{"en":"to show somebody/something in public so that people can see them/it","cn":"展览；展示","g":"[transitive]","lab":"figurative","sc":"show in public","ex":{"en":"The trophy was paraded around the stadium.","cn":"奖杯被环绕着体育场进行展示。"},"pos":"verb"},{"en":"to come together, or to bring soldiers together, in order to march (= walk formally) in front of other people","cn":"（使）列队行进，接受检阅","g":"[intransitive, transitive]","sc":"of soldiers","ex":{"en":"The crowds applauded as the guards paraded past.","cn":"卫队列队走过时，人群鼓掌欢迎。"},"pos":"verb"},{"en":"to pretend to be, or to make somebody/something seem to be, good or important when they are not","cn":"（使）冒充，伪装，打扮成","g":"[intransitive, transitive]","sc":"pretend","ex":{"en":"myth parading as fact","cn":"外表看似真实的神话"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（庆祝重大日子或事件的）游行行列","en":"A parade is a procession of people or vehicles moving through a public place in order to celebrate an important day or event.","ex":{"en":"A military parade marched slowly and solemnly down Pennsylvania Avenue.","cn":"阅兵队列沿宾夕法尼亚大道缓慢而庄严地行进。"}},{"pos":"VERB 动词","cn":"游行；成群结队地行走","en":"When people parade somewhere, they walk together in a formal group or a line, usually with other people watching them.","ex":{"en":"More than four thousand soldiers, sailors and airmen paraded down the Champs Elysee","cn":"逾4,000名陆、海、空三军将士在香榭丽舍大街游行。"}},{"pos":"N-VAR 可变名词","cn":"阅兵式；阅兵典礼","en":"Parade is a formal occasion when soldiers stand in lines to be seen by an officer or important person, or march in a group.","ex":{"en":"He had them on parade at six o'clock in the morning","cn":"他让他们早晨6点列队接受检阅。"}},{"pos":"VERB 动词","cn":"游行展示（旗帜或雕像）","en":"If flags or statues are paraded, they are carried in a procession.","ex":{"en":"Banners were paraded from church to church on feast days.","cn":"宗教节日期间，人们打着横幅在教堂间游行。"}},{"pos":"VERB 动词","cn":"将（囚犯）游街；将（囚犯）示众","en":"If prisoners are paraded through the streets of a town or on television, they are shown to the public, usually in order to make the people who are holding them seem more powerful or important.","ex":{"en":"Five leading fighter pilots have been captured and paraded before the media.","cn":"有5名一流的战斗机飞行员被俘，并被在媒体上曝光。"}},{"pos":"VERB 动词","cn":"拿（某人）炫耀","en":"If you say that someone parades a person, you mean that they show that person to others only in order to gain some advantage for themselves.","ex":{"en":"Children are paraded on television alongside the party leaders to win votes.","cn":"为了拉选票，孩子们被拉去和政党领袖们一起出现在电视上。"}},{"pos":"VERB 动词","cn":"炫耀；展示","en":"If people parade something, they show it in public so that it can be admired.","ex":{"en":"Valentino is keen to see celebrities parading his clothes at big occasions.","cn":"瓦伦蒂诺喜欢看名人在重大场合展示他设计的服装。"}},{"pos":"VERB 动词","cn":"招摇而行","en":"If someone parades, they walk about somewhere in order to be seen and admired.","ex":{"en":"I love to put on a bathing suit and parade on the beach","cn":"我喜欢穿着泳衣在海滩上招摇而行。"}},{"pos":"VERB 动词","cn":"炫耀，展示（情感或品质）","en":"If someone parades a real or pretended feeling or quality, they draw attention to themselves by displaying it.","ex":{"en":"They parade their virtuous beliefs and hide their vices","cn":"他们大秀美德并掩盖自己的罪恶。"}},{"pos":"V-ERG 及物/不及物动词","cn":"吹嘘；夸耀","en":"If you say that something parades as or is paraded as a good or important thing, you mean that some people say that it is good or important but you think it probably is not.","ex":{"en":"The Chancellor will be able to parade his cut in interest rates as a small victory","cn":"财政大臣就能把他的减息举措当作一场小胜来夸耀了。"}},{"pos":"N-COUNT 可数名词","cn":"（多得似乎没有尽头的）一系列","en":"If you talk about a parade of people or things, you mean that there is a series of them that seems never to end.","ex":{"en":"When I ask Nick about his childhood, he remembers a parade of babysitters.","cn":"我问到尼克的童年生活时，他记起了一个又一个保姆。"}},{"pos":"N-COUNT 可数名词","cn":"（常指远离大街的）一小排店铺","en":"A parade is a short row of shops, usually set back from the main street."},{"pos":"N-IN-NAMES 名称名词","cn":"（用于街道名称中）商业街","en":"Parade is used as part of the name of a street.","ex":{"en":"...Queens Hotel, Clarence Parade, Southsea.","cn":"南海克拉伦斯商业街皇后酒店"}}]},"examples":[{"en":"People were parading up and down showing off their finest clothes.","cn":"人们走来走去，炫耀着他们最漂亮的服装。"},{"en":"The colonel paraded his men before the Queen.","cn":"上校指挥士兵列队行进，接受女王的检阅。"}]},"palms":{"oxford":{"phon":"pɑːm","pos":"noun","senses":[{"en":"the inner surface of the hand between the wrist and the fingers","cn":"手掌；手心"},{"en":"a straight tree with a mass of long leaves at the top, growing in tropical countries. There are several types of palm tree, some of which produce fruit.","cn":"棕榈树"}]},"media":{"img":["media/pic/hand_body_comp.jpg","media/thumb/hand.jpg"],"uk":"media/uk/palm__gb_1.mp3","us":"media/us/palm__us_1.mp3"}},"palais":{"media":{"uk":"media/uk/palais__gb_1.mp3","us":"media/us/palais__us_1.mp3"},"oxford":{"phon":"ˈpæleɪ","pos":"noun","senses":[{"en":"(in the past) a large public building used for dancing; a dance hall","cn":"（旧时的）舞场，舞厅"}]}},"paraffin":{"oxford":{"phon":"ˈpærəfɪn","pos":"noun","senses":[{"en":"a type of oil obtained from petroleum and used as a fuel for heat and light","cn":"煤油","ex":{"en":"a paraffin lamp/stove","cn":"煤油灯/炉"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"煤油","en":"Paraffin is a strong-smelling liquid which is used as a fuel in heaters, lamps, and engines.","ex":{"en":"...a paraffin lamp.","cn":"煤油灯"}},{"pos":"N-UNCOUNT 不可数名词","cn":"石蜡","en":"Paraffin wax, or in American English paraffin, is a white wax obtained from petrol or coal. It is used to make candles and in beauty treatments."}]},"media":{"uk":"media/uk/paraffin__gb_1.mp3","us":"media/us/paraffin__us_1.mp3"},"examples":[{"en":"a paraffin heater/lamp/stove","cn":"煤油取暖器/灯/炉"}]},"painter":{"media":{"uk":"media/uk/painter__gb_1.mp3","us":"media/us/painter__us_1.mp3","img":["media/ldoce/img/canvas.jpg"]},"oxford":{"phon":"ˈpeɪntə(r)","pos":"noun","senses":[{"en":"a person whose job is painting buildings, walls, etc.","cn":"油漆匠","ex":{"en":"He works as a painter and decorator.","cn":"他的职业是油漆匠和装潢匠。"}},{"en":"an artist who paints pictures","cn":"画家","ex":{"en":"a famous painter","cn":"著名画家"}},{"en":"a rope fastened to the front of a boat, used for tying it to a post, ship, etc.","cn":"（系船的）缆绳"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"画家","en":"A painter is an artist who paints pictures."},{"pos":"N-COUNT 可数名词","cn":"油漆工","en":"A painter is someone who paints walls, doors, and some other parts of buildings as their job."}]},"examples":[{"en":"He works as a painter and decorator.","cn":"他的职业是油漆匠和装潢师傅。"},{"en":"a portrait/landscape painter","cn":"肖像/风景画家"}]},"partially":{"media":{"uk":"media/uk/partially__gb_1.mp3","us":"media/us/partially__us_1.mp3"},"oxford":{"phon":"ˈpɑːʃəli","pos":"adverb","senses":[{"en":"partly; not completely","cn":"部分地；不完全地","ex":{"en":"The road was partially blocked by a fallen tree.","cn":"倒下的一棵树挡住了部分道路。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"部分地；在某种程度上；有点儿","en":"If something happens or exists partially, it happens or exists to some extent, but not completely.","ex":{"en":"Lisa is deaf in one ear and partially blind.","cn":"莉萨一只耳朵失聪，而且部分失明。"}}]},"examples":[{"en":"The road was partially blocked by a fallen tree.","cn":"倒下的一棵树挡住了部分道路。"},{"en":"a society for the blind and partially sighted (= people who can see very little).","cn":"一个盲人及弱视者协会"}]},"pants":{"oxford":{"phon":"pænts","pos":"noun","senses":[{"en":"underpants or knickers","cn":"内裤；短裤","lab":"British English","ex":{"en":"a pair of pants","cn":"一件内裤"}},{"en":"trousers","cn":"裤子","lab":"especially North American English","ex":{"en":"a new pair of pants","cn":"一条新裤子"}},{"en":"something you think is of poor quality","cn":"次品；劣质品","lab":"British English, slang，，","ex":{"en":"Their new album is absolute pants!","cn":"他们的新专辑简直是垃圾！"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"内裤","en":"Pants are a piece of underwear which have two holes to put your legs through and elastic around the top to hold them up round your waist or hips.","ex":{"en":"I put on my bra and pants.","cn":"我戴上乳罩，穿上内裤。"}},{"pos":"N-PLURAL 复数名词","cn":"裤子","en":"Pants are a piece of clothing that covers the lower part of your body and each leg.","ex":{"en":"He wore brown corduroy pants and a white cotton shirt.","cn":"他身着棕色灯芯绒裤子和白色棉衬衫。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"劣质品","en":"If you say that something is pants, you mean that it is very poor in quality.","ex":{"en":"The place is pants, yet so popular.","cn":"那个地方很糟糕，却很受欢迎。"}},{"pos":"PHRASE 短语","cn":"使…（烦）得要死；把…（吓）得要命","en":"If someone bores, charms, or scares the pants off you, for example, they bore, charm, or scare you a lot.","ex":{"en":"You'll bore the pants off your grandchildren","cn":"你会把孙辈们烦透的。"}},{"pos":"PHRASE 短语","cn":"凭感觉；凭直觉","en":"If you fly by the seat of your pants or do something by the seat of your pants, you use your instincts to tell you what to do in a new or difficult situation rather than following a plan or relying on equipment."},{"pos":"","cn":"","en":"to be caught with one's pants down→see: ; to wear the pants→see: ;"}]},"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/trousers.jpg"],"uk":"media/uk/pants__gb_1.mp3","us":"media/us/pants__us_1.mp3"},"examples":[{"en":"Their new CD is absolute pants!","cn":"他们的新光盘绝对是次货！"},{"en":"Do we have to watch this pants programme?","cn":"我们非要看这种烂节目吗？"}]},"paragraph":{"media":{"uk":"media/uk/paragraph__gb_1.mp3","us":"media/us/paragraph__us_1.mp3"},"oxford":{"phon":"ˈpærəɡrɑːf","pos":"noun","senses":[{"en":"a section of a piece of writing, usually consisting of several sentences dealing with a single subject. The first sentence of a paragraph starts on a new line.","cn":"段；段落","ex":{"en":"an opening/introductory paragraph","cn":"开头的／导引的一段"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（文章的）段，段落，节","en":"A paragraph is a section of a piece of writing. A paragraph always begins on a new line and contains at least one sentence.","ex":{"en":"The length of a paragraph depends on the information it conveys","cn":"段落的长度取决于它所传达的信息。"}}]},"examples":[{"en":"Write a paragraph on each of the topics given below.","cn":"就下面所列主题各写一个段落。"},{"en":"See paragraph 15 of the handbook.","cn":"参见手册第 15 段。"}]},"paperwork":{"oxford":{"phon":"ˈpeɪpəwɜːk","pos":"noun","senses":[{"en":"the written work that is part of a job, such as filling in forms or writing letters and reports","cn":"文书工作","ex":{"en":"We're trying to cut down on the amount of paperwork involved.","cn":"我们正在努力降低相关的文书工作量。"}},{"en":"all the documents that you need for something, such as a court case or buying a house","cn":"（诉讼案件、购置房产等所需的）全部文件，全部资料","ex":{"en":"How quickly can you prepare the paperwork?","cn":"你要多久才能把全部文件备好？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"文书工作","en":"Paperwork is the routine part of a job which involves writing or dealing with letters, reports, and records.","ex":{"en":"At every stage in the production there will be paperwork — forms to fill in, permissions to obtain, letters to write.","cn":"在生产的每个阶段都有文书工作——填表格，报批，写信。"}}]},"media":{"uk":"media/uk/paperwork__gb_1.mp3","us":"media/us/paperwork__us_1.mp3"},"examples":[{"en":"We're trying to cut down on the amount of paperwork involved.","cn":"我们正在努力降低有关此事的文书工作量。"},{"en":"How quickly can you prepare the paperwork?","cn":"你要多久才能把全部文件备好？"}]},"parking":{"media":{"uk":"media/uk/parking__gb_1.mp3","us":"media/us/parking__us_1.mp3"},"oxford":{"phon":"ˈpɑːkɪŋ","pos":"noun","senses":[{"en":"the act of stopping a vehicle at a place and leaving it there for a period of time","cn":"停车；泊车","lab":"informal","ex":{"en":"There is no parking here between 9 a.m. and 6 p.m.","cn":"上午 9 时至下午 6 时此处禁止停车。"}},{"en":"a space or an area for leaving vehicles","cn":"停车场；停车位","ex":{"en":"The hotel is centrally situated with ample free parking.","cn":"旅馆坐落在市中心，有充裕的免费停车位。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"停车；泊车","en":"Parking is the action of moving a vehicle into a place in a car park or by the side of the road where it can be left.","ex":{"en":"In many towns parking is allowed only on one side of the street","cn":"很多小镇只允许将车停在街道的一侧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"停车位","en":"Parking is space for parking a vehicle in.","ex":{"en":"Cars allowed, but parking is limited.","cn":"车辆准许进入，但是车位有限。"}}]},"examples":[{"en":"There is no parking here between 9 a.m. and 6 p.m.","cn":"上午 9 时至下午 6 时此处禁止停车。"},{"en":"The hotel is centrally situated with ample free parking.","cn":"旅馆坐落在市中心，有充裕的免费停车位。"}]},"parliament":{"media":{"uk":"media/uk/parliament__gb_1.mp3","us":"media/us/parliament__us_1.mp3"},"oxford":{"phon":"ˈpɑːləmənt","pos":"noun","senses":[{"en":"the group of people who are elected to make and change the laws of a country","cn":"议会；国会","g":"[countable]","lab":"British English","ex":{"en":"The German parliament is called the ‘Bundestag’.","cn":"德国的议会称为 Bundestag。"}},{"en":"the parliament of some countries, including the United Kingdom. In the UK, Parliament consists of the House of Commons and the House of Lords","cn":"议会；英国议会（包括下议院和上议院）","g":"[uncountable]","ex":{"en":"a Member of Parliament","cn":"议会议员"}},{"en":"a particular period during which a parliament is working; Parliament as it exists between one general election and the next","cn":"一届议会的会期；（两次大选之间的）一届议会","g":"[countable, uncountable]","ex":{"en":"We are now into the second half of the parliament.","cn":"我们现已进入了本届议会的后半任期。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-PROPER 可数名词；专有名词","cn":"议会；国会","en":"The parliament of some countries, for example Britain, is the group of people who make or change its laws, and decide what policies the country should follow. →see usage note at:","ex":{"en":"Parliament today approved the policy, but it has not yet become law.","cn":"议会于今天批准了这项政策，但尚未成为法律。"}},{"pos":"N-COUNT 可数名词","cn":"一届议会（会期）","en":"A particular parliament is a particular period of time in which a parliament is doing its work, between two elections or between two periods of holiday.","ex":{"en":"The legislation is expected to be passed in the next parliament.","cn":"预计这项法案将在下一届议会中通过。"}}]},"examples":[{"en":"The German parliament is called the ‘Bundestag’.","cn":"德国的议会称为 Bundestag。"},{"en":"We are now into the second half of the parliament.","cn":"我们现已进入了本届议会的后半任期。"}]},"passably":{"media":{"uk":"media/uk/passably__gb_1.mp3","us":"media/us/passably__us_1.mp3"},"oxford":{"phon":"ˈpɑːsəbli","pos":"adverb","senses":[{"en":"in a way that is acceptable or good enough","cn":"过得去；尚可；还可以","ex":{"en":"He speaks passably good French.","cn":"他法语讲得还可以。"}}]},"examples":[{"en":"He speaks passably good French.","cn":"他法语讲得还可以。"},{"en":"There were one or two passably funny jokes but it was mostly dull.","cn":"有一两个笑话还算滑稽﹐不过大多数挺无趣的。"}]},"painful":{"media":{"uk":"media/uk/painful__gb_1.mp3","us":"media/us/painful__us_1.mp3"},"oxford":{"phon":"ˈpeɪnfl","pos":"adjective","senses":[{"en":"causing you pain","cn":"令人疼痛的","ex":{"en":"Is your back still painful?","cn":"你的背还疼吗？"}},{"en":"causing you to feel upset or embarrassed","cn":"令人痛苦（或难过、难堪）的","ex":{"en":"Seeing her again brought back painful memories.","cn":"再次见到她唤起了令人痛苦的回忆。"}},{"en":"unpleasant or difficult to do","cn":"不愉快的；困难的；艰难的","ex":{"en":"Applying for jobs can be a long and painful process.","cn":"求职会是一个漫长而又艰难的历程。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"疼痛的","en":"If a part of your body is painful, it hurts because it is injured or because there is something wrong with it.","ex":{"en":"Her glands were swollen and painful","cn":"她腺体肿痛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（病、伤、手术等）令人疼痛的，引起疼痛的","en":"If something such as an illness, injury, or operation is painful, it causes you a lot of physical pain.","ex":{"en":"...a painful back injury","cn":"疼痛的背伤"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情形、记忆或经历）痛苦的，难受的，恼人的","en":"Situations, memories, or experiences that are painful are difficult and unpleasant to deal with, and often make you feel sad and upset.","ex":{"en":"Remarks like that brought back painful memories","cn":"那样的话勾起了痛苦的回忆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表演或采访）令人难堪的","en":"If a performance or interview is painful, it is so bad that it makes you feel embarrassed for the people taking part in it.","ex":{"en":"The interview was painful to watch.","cn":"观看那次访谈让人难堪。"}}]},"examples":[{"en":"Their feet were sore after hours of walking.","cn":"他们走了几小时的路，把脚都走疼了。"},{"en":"Applying for jobs can be a long and painful process.","cn":"求职可以是漫长而又艰难的过程。"}]},"park":{"media":{"uk":"media/uk/park__gb_1.mp3","us":"media/us/park__us_1.mp3"},"oxford":{"phon":"pɑːk","pos":"noun","senses":[{"en":"an area of public land in a town or a city where people go to walk, play and relax","cn":"公园","g":"[countable]","ex":{"en":"Hyde Park","cn":"海德公园"}},{"en":"an area of land used for a particular purpose","cn":"专用区；园区","g":"[countable]","ex":{"en":"a business/science park","cn":"商业／科学园区"}},{"en":"(in the UK) an area of land, usually with fields and trees, attached to a large country house","cn":"（英国）庄园，庭院","g":"[countable]","ex":{"en":"The cottage is set within the park of a country house.","cn":"那间小屋位于一栋乡间别墅的庄园里。"}},{"en":"a piece of land for playing sports, especially baseball","cn":"运动场；（尤指）棒球场","g":"[countable]","lab":"North American English","ex":{"en":"With a mighty swing he hit the ball right out of the park.","cn":"他用力一挥把球打出了球场。"}},{"en":"a football (soccer) or rugby field","cn":"足球场；橄榄球场","g":"[singular]","lab":"British English","ex":{"en":"the fastest man on the park","cn":"足球场上速度最快的人"}},{"en":"the position of the gears in a car with automatic transmission (= a system that changes the gears by itself so the driver does not have to) in which they are locked so that the engine cannot send any power to the wheels","cn":"（汽车排挡的）停车挡","g":"[uncountable]","ex":{"en":"She put the car in park, pulled out the key and got out.","cn":"她挂上停车挡，拔出钥匙，下了车。"}},{"en":"to leave a vehicle that you are driving in a particular place for a period of time","cn":"停（车）；泊（车）","g":"[intransitive, transitive]","ex":{"en":"He parked and went inside.","cn":"他停好车走了进去。"},"pos":"verb"},{"en":"to leave something in a convenient place until you need it","cn":"暂时放置；存放","g":"[transitive]","lab":"informal","ex":{"en":"Just park your bags in the hall until your room is ready.","cn":"你的房间收拾好之前，请先把行李放在大厅。"},"pos":"verb"},{"en":"to sit or stand in a particular place for a period of time","cn":"（在某处）坐下（或站着）","g":"[transitive]","lab":"informal","ex":{"en":"She parked herself on the edge of the bed.","cn":"她坐在床沿上。"},"pos":"verb"},{"en":"to decide to leave an idea or issue to be dealt with or considered at a later meeting","cn":"把…搁置，推迟（在以后的会议上讨论或处理）","g":"[transitive]","lab":"business, informal，，","ex":{"en":"Let's park that until our next meeting.","cn":"咱们把这留到下次开会时再处理吧。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公园","en":"A park is a public area of land with grass and trees, usually in a town, where people go in order to relax and enjoy themselves.","ex":{"en":"...Regent's Park","cn":"摄政公园"}},{"pos":"VERB 动词","cn":"停放（车辆）；泊（车）","en":"When you park a vehicle or park somewhere, you drive the vehicle into a position where it can stay for a period of time, and leave it there.","ex":{"en":"Greenfield turned into the next side street and parked","cn":"格林菲尔德转进下一个小巷，停好车。"}},{"pos":"N-COUNT 可数名词","cn":"（作为特定活动场地的）…园，…区","en":"You can refer to a place where a particular activity is carried out as a park .","ex":{"en":"...a science and technology park.","cn":"科技园区"}},{"pos":"N-VAR 可变名词","cn":"庄园；庭院；园林","en":"A private area of grass and trees around a large country house is referred to as a park .","ex":{"en":"...a 19th century manor house in six acres of park and woodland.","cn":"位于6英亩园林和树林中的19世纪庄园宅第"}},{"pos":"N-SING 单数名词","cn":"足球场；橄榄球场","en":"Some people refer to a football or rugby field as the park .","ex":{"en":"Chris was also the best player on the park.","cn":"克里斯同时也是场上的最佳球员。"}},{"pos":"N-COUNT; also N-IN-NAMES 可数名词；名称名词","cn":"棒球场（亦用于某些棒球场名称中）","en":"A park is a park or stadium where baseball is played. Park is also used in the names of some parks.","ex":{"en":"...a spot where professional baseball has been played in one park or another since 1896","cn":"自1896年以来其中多个棒球场举办过职业棒球赛的地方"}}]},"examples":[{"en":"( informal, figurative ) Just park your bags in the hall until your room is ready.","cn":"你的房间收拾好之前，请先把行李放在大厅。"},{"en":"Let's park that until our next meeting.","cn":"咱们把这留到下次开会时再处理吧。"}]},"papa":{"media":{"uk":"media/uk/papa__gb_1.mp3","us":"media/us/papa__us_1.mp3"},"oxford":{"phon":"pəˈpɑː","pos":"noun","senses":[{"en":"used to talk about or to address your father","cn":"爸爸"}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"爸爸","en":"Some people refer to or address their father as papa .","ex":{"en":"He was so much older than me, older even than my papa.","cn":"他比我大很多，甚至比我爸爸还大。"}}]},"examples":[{"en":"Good morning, Papa!","cn":"早上好﹐爸爸！"}]},"pastoral":{"media":{"uk":"media/uk/pastoral__gb_1.mp3","us":"media/us/pastoral__us_1.mp3"},"oxford":{"phon":"ˈpɑːstərəl","pos":"adjective","senses":[{"en":"relating to the work of a priest or teacher in giving help and advice on personal matters, not just those connected with religion or education","cn":"牧灵的，牧师的，教牧的（有关圣职人员及教师对个人幸福的关顾）","ex":{"en":"pastoral care","cn":"牧师对教友的关怀"}},{"en":"showing country life or the countryside, especially in a romantic way","cn":"田园的；乡村生活的；村野风情的","ex":{"en":"a pastoral scene/poem/symphony","cn":"田园风光／诗／交响乐"}},{"en":"relating to the farming of animals","cn":"畜牧的","ex":{"en":"agricultural and pastoral practices","cn":"农牧业活动"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"牧师的；牧灵的；教牧的","en":"The pastoral duties of a priest or other religious leader involve looking after the people he or she has responsibility for, especially by helping them with their personal problems.","ex":{"en":"...the pastoral care of the sick","cn":"牧师对病人的关怀"}},{"pos":"ADJ 形容词","cn":"（教师对学生）生活辅导的","en":"If a school offers pastoral care, it is concerned with the personal needs and problems of its pupils, not just with their schoolwork.","ex":{"en":"A few schools now offer counselling sessions; all have some system of pastoral care.","cn":"一些学校现在开设咨询课；所有学校都有某种教导关怀体制。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"田园式的","en":"A pastoral place, atmosphere, or idea is characteristic of peaceful country life and scenery.","ex":{"en":"...the pastoral beauty of a park.","cn":"公园里的田园式美景"}},{"pos":"ADJ 形容词","cn":"畜牧的；放牧的","en":"A pastoral way of life is one in which people keep animals such as cows and sheep that feed off the land.","ex":{"en":"...the Israelites, who were a pastoral people.","cn":"曾经是游牧民族的以色列人"}}]},"examples":[{"en":"a pastoral scene/poem/symphony","cn":"田园风光/诗/交响乐"},{"en":"pastoral care","cn":"牧师对教友的关怀"}]},"paradox":{"media":{"uk":"media/uk/paradox__gb_1.mp3","us":"media/us/paradox__us_1.mp3"},"oxford":{"phon":"ˈpærədɒks","pos":"noun","senses":[{"en":"a person, thing or situation that has two opposite features and therefore seems strange","cn":"矛盾的人（或事物、情况）","g":"[countable]","ex":{"en":"He was a paradox—a loner who loved to chat to strangers.","cn":"他真是个矛盾人物，生性孤僻却又喜欢和陌生人闲聊。"}},{"en":"a statement containing two opposite ideas that make it seem impossible or unlikely, although it is probably true; the use of this in writing","cn":"似非而是的隽语；悖论；悖论修辞","g":"[countable, uncountable]","ex":{"en":"‘More haste, less speed’ is a well-known paradox.","cn":"“欲速则不达”是人们熟知的似非而是的隽语。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自相矛盾；有矛盾特点的情况","en":"You describe a situation as a paradox when it involves two or more facts or qualities which seem to contradict each other.","ex":{"en":"The paradox is that the region's most dynamic economies have the most primitive financial systems","cn":"矛盾之处在于这个地区最有活力的经济体却有着最落后的金融体系。"}},{"pos":"N-VAR 可变名词","cn":"悖论；自相矛盾的说法；似矛盾而（可能）正确的说法","en":"A paradox is a statement in which it seems that if one part of it is true, the other part of it cannot be true.","ex":{"en":"The story contains many levels of paradox","cn":"这个故事存在多重悖论。"}}]},"examples":[{"en":"It is a curious paradox that professional comedians often have unhappy personal lives.","cn":"这真是个奇怪的矛盾现象：职业喜剧演员的私人生活往往并不快乐。"},{"en":"It is paradoxical that some of the poorest people live in some of the richest areas of the country.","cn":"某些最贫穷的人却住在这个国家一些最富有的地区，这似乎很矛盾。"}]},"panorama":{"media":{"uk":"media/uk/panorama__gb_1.mp3","us":"media/us/panorama__us_1.mp3"},"oxford":{"phon":"ˌpænəˈrɑːmə","pos":"noun","senses":[{"en":"a view of a wide area of land","cn":"全景","ex":{"en":"There is a superb panorama of the mountains from the hotel.","cn":"从旅馆可饱览峰峦叠嶂的雄伟景观。"}},{"en":"a description, study or set of pictures that presents all the different aspects or stages of a particular subject, event, etc.","cn":"（某专题或事件的）全面叙述，综合研究；全景画卷","ex":{"en":"a panorama of rural life since the Middle Ages","cn":"中世纪以来乡村生活的全景"}},{"en":"a British television documentary programme (= one that presents facts about real life). It has been broadcast regularly by the BBC since 1953. It usually examines social or political issues that are in the news.","cn":"全景图：英国电视纪录片节目（代表真实生活的事实的节目）。自1953年以来，它已由英国广播公司（BBC）定期播放。它通常检查新闻中的社会或政治问题。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"全景；远景","en":"A panorama is a view in which you can see a long way over a wide area of land, usually because you are on high ground.","ex":{"en":"Horton looked out over a panorama of fertile valleys and gentle hills.","cn":"霍顿向外望去，肥沃的谷地和平缓的丘陵尽收眼底。"}},{"pos":"N-COUNT 可数名词","cn":"概述；概论","en":"A panorama is a broad view of a state of affairs or of a constantly changing series of events.","ex":{"en":"...a gripping panorama of medieval history.","cn":"引人入胜的中世纪史概论"}}]},"examples":[{"en":"There is a superb panorama of the mountains from the hotel.","cn":"从旅馆可饱览峰峦叠嶂的雄伟景观。"},{"en":"a panoramic view over the valley","cn":"山谷的全景"}]},"paradigm":{"media":{"uk":"media/uk/paradigm__gb_1.mp3","us":"media/us/paradigm__us_1.mp3"},"oxford":{"phon":"ˈpærədaɪm","pos":"noun","senses":[{"en":"a typical example or pattern of something","cn":"范式；范例；典范；样式","lab":"specialist or formal","ex":{"en":"a paradigm for students to copy","cn":"供学生效法的榜样"}},{"en":"a set of all the different forms of a word","cn":"词形变化表","lab":"grammar","ex":{"en":"verb paradigms","cn":"动词词形变化表"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"样板；范式","en":"A paradigm is a model for something which explains it or shows how it can be produced.","ex":{"en":"...a new paradigm of production.","cn":"新的生产范式"}},{"pos":"N-COUNT 可数名词","cn":"典范；范例","en":"A paradigm is a clear and typical example of something.","ex":{"en":"He had become the paradigm of the successful man.","cn":"他已经成为成功人士的典范。"}}]},"examples":[{"en":"The war was a paradigm of the destructive side of human nature.","cn":"那场战争尽显人性中具有破坏性的一面。"},{"en":"a paradigm for students to copy","cn":"供学生效法的榜样"}]},"par":{"oxford":{"phon":"pɑː(r)","pos":"noun","senses":[{"en":"the number of shots a good player should need to complete a course or to hit the ball into a particular hole","cn":"标准杆","ex":{"en":"a par five hole","cn":"标准杆为五杆的球洞"}},{"en":"the value that a share in a company had originally","cn":"（股票的）面值，票面价值","lab":"business","ex":{"en":"to be redeemed at par","cn":"以面值兑换"}},{"en":"(in writing) paragraph","cn":"（书写形式）段","ex":{"en":"See par. 3.","cn":"参见第 3 段。"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"与…同样；与…相似","en":"If you say that two people or things are on a par with each other, you mean that they are equally good or bad, or equally important.","ex":{"en":"Parts of Glasgow are on a par with the worst areas of London and Liverpool for burglaries.","cn":"格拉斯哥部分地区的入室盗窃案与伦敦、利物浦最乱的地区一样猖狂。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（高尔夫球的）标准杆数","en":"In golf, par is the number of strokes that a good player should take to get the ball into a hole or into all the holes on a particular golf course.","ex":{"en":"He was five under par after the first round.","cn":"第一轮过后，他低于标准杆5杆。"}},{"pos":"PHRASE 短语","cn":"不符合标准的；不如预期的","en":"If you say that someone or something is below par or under par, you are disappointed in them because they are below the standard you expected.","ex":{"en":"Duffy's primitive guitar playing is well below par","cn":"达菲粗糙的吉他演奏技巧远不够水平。"}},{"pos":"PHRASE 短语","cn":"达到标准的；合格的","en":"If you say that someone or something is not up to par, you are disappointed in them because they are below the standard you expected.","ex":{"en":"His performance was not up to par","cn":"他的表演不合格。"}},{"pos":"PHRASE 短语","cn":"不在状态；感觉不如平常好","en":"If you feel below par or under par, you feel tired and unable to perform as well as you normally do."},{"pos":"PHRASE 短语","cn":"（不快之事）不出所料，在意料之中","en":"If you say that something that happens is par for the course, you mean that you are not pleased with it but it is what you expected to happen.","ex":{"en":"He said long hours are par for the course.","cn":"他说时间之久是意料之中的。"}}]},"media":{"uk":"media/uk/par__gb_1.mp3","us":"media/us/par__us_1.mp3"},"examples":[{"en":"Starting early and working long hours is par for the course in this job.","cn":"开工早以及工时长是这份工作的常态。"},{"en":"Teaching in some subjects has been well below par.","cn":"一些科目的教学一直远达不到标准。"}]},"palace":{"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/palace.jpg"],"uk":"media/uk/palace__gb_1.mp3","us":"media/us/palace__us_1.mp3"},"oxford":{"phon":"ˈpæləs","pos":"noun","senses":[{"en":"the official home of a king, queen, president, etc.","cn":"王宫；宫殿；总统府","g":"[countable]","ex":{"en":"Buckingham Palace","cn":"白金汉宫"}},{"en":"a way of referring to the people who live or work in a palace, especially the British royal family and their advisers","cn":"（尤指英国的）王室，王室幕僚","g":"[singular]","ex":{"en":"The Palace last night refused to comment on the reports.","cn":"昨晚王室拒绝对报道作出评论。"}},{"en":"any large impressive house","cn":"豪华住宅；宫殿","g":"[countable]","ex":{"en":"The Old Town has a whole collection of churches, palaces and mosques.","cn":"旧城区汇集了许多教堂、大宅院和清真寺。"}},{"en":"a large public building, such as a hotel or cinema","cn":"大型公共建筑（如旅馆、影剧院等）","g":"[countable]","lab":"old-fashioned","ex":{"en":"the Strand Palace Hotel","cn":"斯特兰德宫酒店"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宫殿；王宫；皇宫","en":"A palace is a very large impressive house, especially one which is the official home of a king, queen, or president.","ex":{"en":"...Buckingham Palace","cn":"白金汉宫"}},{"pos":"N-SING 单数名词","cn":"王室","en":"When the members of a royal palace make an announcement through an official spokesperson, they can be referred to as the Palace .","ex":{"en":"The Palace will not comment on questions about the family's private life.","cn":"王室不会就有关皇家私生活的问题发表任何评论。"}},{"pos":"N-COUNT 可数名词","cn":"豪宅；宫殿般的建筑","en":"You can refer to any large splendid house or other building as a palace .","ex":{"en":"They'd bought a huge barn with some land and planned to turn it into a palace.","cn":"他们买了一个带有一片土地的大谷仓，计划将其改建为一座豪宅。"}}]},"examples":[{"en":"The Old Town has a whole collection of churches, palaces and mosques.","cn":"旧城区汇集了许多教堂、大宅院和清真寺。"},{"en":"The Palace last night refused to comment on the reports.","cn":"昨晚王室拒绝对报道作出评论。"}]},"partner":{"media":{"uk":"media/uk/partner__gb_1.mp3","us":"media/us/partner__us_1.mp3"},"oxford":{"phon":"ˈpɑːtnə(r)","pos":"noun","senses":[{"en":"a person that you are doing an activity with, such as dancing or playing a game","cn":"搭档；同伴；舞伴","ex":{"en":"a dance/tennis partner","cn":"舞伴；网球搭档"}},{"en":"the person that you are married to or having a sexual relationship with","cn":"配偶；性伴侣","lab":"especially North American English","ex":{"en":"Come to the New Year disco and bring your partner!","cn":"携伴来参加新年迪斯科舞会吧！"}},{"en":"one of the people who owns a business and shares the profits, etc.","cn":"合伙人","ex":{"en":"a partner in a law firm","cn":"律师事务所的合伙人"}},{"en":"a country or an organization that has an agreement with another country or organization","cn":"伙伴国；合作组织","ex":{"en":"a trading partner","cn":"贸易伙伴"}},{"en":"to be somebody’s partner in a dance, game, etc.","cn":"（在跳舞、比赛等中）结成伙伴，做搭档，配对","g":"[transitive]","ex":{"en":"Gerry offered to partner me at tennis.","cn":"格里提出和我搭档打网球。"},"pos":"verb"},{"en":"to be involved in a business project with another company","cn":"（与…）合伙，合作","ex":{"en":"Freshfoods usually partners with other companies to share risk.","cn":"生鲜食品公司通常与其他公司合作以分担风险。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"配偶；（性）伴侣","en":"Your partner is the person you are married to or are having a romantic or sexual relationship with.","ex":{"en":"Wanting other friends doesn't mean you don't love your partner.","cn":"想交其他朋友并不意味着你不爱你的伴侣。"}},{"pos":"N-COUNT 可数名词","cn":"同伴；搭档","en":"Your partner is the person you are doing something with, for example dancing with or playing with in a game against two other people.","ex":{"en":"...to dance with a partner","cn":"和舞伴跳舞"}},{"pos":"N-COUNT 可数名词","cn":"合伙人","en":"The partners in a firm or business are the people who share the ownership of it.","ex":{"en":"He's a partner in a Chicago law firm.","cn":"他是芝加哥一家律师事务所的合伙人。"}},{"pos":"N-COUNT 可数名词","cn":"盟友；伙伴","en":"The partner of a country or organization is another country or organization with which they work or do business.","ex":{"en":"Spain has been one of Cuba's major trading partners.","cn":"西班牙一直是古巴的主要贸易伙伴之一。"}},{"pos":"VERB 动词","cn":"（比赛或舞蹈中）做…的伙伴（或搭档），与…配对","en":"If you partner someone, you are their partner in a game or in a dance.","ex":{"en":"He had partnered the famous Russian ballerina","cn":"他已经和那位著名的俄罗斯芭蕾舞女演员做了搭档。"}}]},"examples":[{"en":"Come to the New Year disco and bring your partner!","cn":"携伴来参加新年迪斯科舞会吧！"},{"en":"Gerry offered to partner me at tennis.","cn":"格里提出和我搭档打网球。"}]},"pasta":{"oxford":{"phon":"ˈpæstə","pos":"noun","senses":[{"en":"an Italian food made from flour, water and sometimes eggs, formed into different shapes and usually served with a sauce. It is hard when dry and soft when cooked.","cn":"意大利面食","ex":{"en":"Toss the pasta with the hot sauce.","cn":"把意大利面和辣椒酱搅拌在一起。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"面食（如意大利面条、通心粉等）","en":"Pasta is a type of food made from a mixture of flour, eggs, and water that is formed into different shapes and then boiled. Spaghetti, macaroni, and noodles are types of pasta."}]},"media":{"uk":"media/uk/pasta__gb_1.mp3","us":"media/us/pasta__us_1.mp3","img":["media/ldoce/img/bowtie_pasta.jpg"]},"examples":[{"en":"I eat a lot of pasta.","cn":"我经常吃意大利面食。"}]},"pastry":{"media":{"uk":"media/uk/pastry__gb_1.mp3","us":"media/us/pastry__us_1.mp3","img":["media/ldoce/img/apple_pie.jpg"]},"oxford":{"phon":"ˈpeɪstri","pos":"noun","senses":[{"en":"a mixture of flour, fat and water or milk that is rolled out flat to be a base or cover for a pie, etc.","cn":"油酥面团；油酥面皮","g":"[uncountable]","ex":{"en":"Bake until the pastry is crisp and golden.","cn":"将油酥烘烤至金黄酥脆。"}},{"en":"a small cake made using pastry","cn":"油酥糕点","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"油酥面饼；油酥面皮","en":"Pastry is a food made from flour, fat, and water that is mixed together, rolled flat, and baked in the oven. It is used, for example, for making pies."},{"pos":"N-COUNT 可数名词","cn":"油酥点心；油酥糕饼","en":"A pastry is a small cake made with sweet pastry."}]},"examples":[{"en":"a Danish pastry","cn":"丹麦油酥糕饼"}]},"paper":{"media":{"uk":"media/uk/paper__gb_1.mp3","us":"media/us/paper__us_1.mp3"},"oxford":{"phon":"ˈpeɪpə(r)","pos":"noun","senses":[{"en":"the thin material that you write and draw on and that is also used for wrapping and packing things","cn":"纸；纸张","g":"[uncountable]","sc":"for writing/wrapping","ex":{"en":"a piece/sheet of paper","cn":"一片／一张纸"}},{"en":"a newspaper","cn":"报纸","g":"[countable]","sc":"newspaper","ex":{"en":"the daily/morning paper","cn":"日报；晨报"}},{"en":"pieces of paper with writing on them, such as letters, pieces of work or private documents","cn":"文件；文献","g":"[plural]","sc":"documents","ex":{"en":"His desk was covered with books and papers.","cn":"他的办公桌上全是书籍和文件。"}},{"en":"official documents that prove your identity, give you permission to do something, etc.","cn":"证明；证件","g":"[plural]","sc":"documents","ex":{"en":"identity papers","cn":"身份证件"}},{"en":"a set of exam questions on a particular subject; the answers that people write to the questions","cn":"试卷；试题；答卷","g":"[countable]","lab":"British English","sc":"exam","ex":{"en":"The geography paper was hard.","cn":"地理试题难极了。"}},{"en":"an academic article about a particular subject that is written by and for specialists","cn":"论文","g":"[countable]","sc":"article","ex":{"en":"a recent paper in the Journal of Medicine","cn":"最近刊在《医学学报》上的一篇论文"}},{"en":"a piece of written work done by a student","cn":"（学生的）研究报告，论文","g":"[countable]","lab":"North American English","sc":"article","ex":{"en":"Your grade will be based on four papers and a final exam.","cn":"你的成绩将根据四篇论文和期末考试决定。"}},{"en":"paper that you use to cover and decorate the walls of a room","cn":"壁纸","g":"[countable, uncountable]","sc":"on walls","ex":{"en":"The room was damp and the paper was peeling off.","cn":"屋子很潮湿，壁纸都一片片剥落了。"}},{"en":"to decorate the walls of a room by covering them with wallpaper","cn":"贴壁纸","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"纸","en":"Paper is a material that you write on or wrap things with. The pages of this book are made of paper.","ex":{"en":"He wrote his name down on a piece of paper for me","cn":"他把他的名字写在一张纸上交给我。"}},{"pos":"N-COUNT 可数名词","cn":"（一份）报纸","en":"A paper is a newspaper.","ex":{"en":"I might get a paper in the village","cn":"我或许能在村子里找到一份报纸。"}},{"pos":"N-COUNT 可数名词","cn":"（总称）报纸","en":"You can refer to newspapers in general as the paper or the papers .","ex":{"en":"You can't believe everything you read in the paper","cn":"报纸上看到的东西不能全信。"}},{"pos":"N-PLURAL 复数名词","cn":"材料；资料；文件","en":"Your papers are sheets of paper with writing or information on them, which you might keep in a safe place at home.","ex":{"en":"Her papers included unpublished articles and correspondence.","cn":"她的资料包括未发表的文章和信件。"}},{"pos":"N-PLURAL 复数名词","cn":"（证明身份的）证件","en":"Your papers are official documents, for example your passport or identity card, which prove who you are or which give you official permission to do something.","ex":{"en":"A young Moroccan stopped by police refused to show his papers","cn":"一位被警察拦下的摩洛哥青年拒绝出示他的证件。"}},{"pos":"N-COUNT 可数名词","cn":"论文","en":"A paper is a long, formal piece of writing about an academic subject.","ex":{"en":"He just published a paper in the journal Nature analyzing the fires.","cn":"他刚刚在《自然》杂志上发表了一篇分析火灾的论文。"}},{"pos":"N-COUNT 可数名词","cn":"学生论文","en":"A paper is an essay written by a student.","ex":{"en":"...the ten common errors that appear most frequently in student papers.","cn":"学生论文中最常见的10个错误"}},{"pos":"N-COUNT 可数名词","cn":"试卷；考卷","en":"A paper is a part of a written examination in which you answer a number of questions in a particular period of time.","ex":{"en":"We sat each paper in the Hall","cn":"我们每一场考试都是在大厅里考的。"}},{"pos":"N-COUNT 可数名词","cn":"（政府或委员会发表的关于重大问题的）文件，报告","en":"A paper prepared by a government or a committee is a report on a question they have been considering or a set of proposals for changes in the law.","ex":{"en":"...a new government paper on European policy.","cn":"有关欧洲政策的新政府文件"}},{"pos":"ADJ 形容词","cn":"书面的；账面的","en":"Paper agreements, qualifications, or profits are ones that are stated by official documents to exist, although they may not really be effective or useful.","ex":{"en":"They expressed deep mistrust of the paper promises","cn":"他们对书面承诺表现出极度的不信任。"}},{"pos":"VERB 动词","cn":"给…贴墙纸","en":"If you paper a wall, you put wallpaper on it.","ex":{"en":"We papered all four bedrooms","cn":"我们把4个卧室都贴了墙纸。"}},{"pos":"PHRASE 短语","cn":"以书面形式；在纸上","en":"If you put your thoughts down on paper, you write them down.","ex":{"en":"It is important to get something down on paper","cn":"把一些东西写在纸上很重要。"}},{"pos":"PHRASE 短语","cn":"在字面上；理论上","en":"If something seems to be the case on paper, it seems to be the case from what you read or hear about it, but it may not really be the case.","ex":{"en":"On paper, I am the healthiest man alive, yet I feel permanently unwell.","cn":"理论上，我是活着的最健康的人，但是我总感觉不舒服。"}},{"pos":"PHRASE 短语","cn":"毫无价值；一纸空文","en":"If you say that a promise, an agreement, or a guarantee is not worth the paper it's written on, you mean that although it has been written down and seems to be official, it is in fact worthless because what has been promised will not be done."},{"pos":"","cn":"","en":"相关词组：paper over"}]},"examples":[{"en":"Your grade will be based on four papers and a final exam.","cn":"你的成绩将根据四篇研究报告和期末考试决定。"},{"en":"Experience is more important for this job than paper qualifications (= that exist on paper, but may not have any real value).","cn":"就这项工作而言，经验比纸面上的资格重要。"}]},"pads":{"oxford":{"phon":"pæd","pos":"noun","senses":[{"en":"a thick piece of soft material that is used, for example, for absorbing liquid, cleaning or protecting sth （","cn":"吸收液体、保洁或保护用的）软垫，护垫，垫状物"},{"en":"a number of pieces of paper for writing or drawing on, that are fastened together at one edge","cn":"便笺本；拍纸簿"}]},"media":{"img":["media/ldoce/img/pads.jpg"]}},"paperless":{"media":{"uk":"media/uk/paperless__gb_1.mp3","us":"media/us/paperless__us_1.mp3"},"oxford":{"phon":"ˈpeɪpələs","pos":"adjective","senses":[{"en":"using computers, phones, etc. rather than paper to exchange information","cn":"无纸的；不用纸的","ex":{"en":"the paperless office","cn":"无纸办公室"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无纸化的；不用纸的","en":"Paperless is used to describe business or office work which is done by computer or telephone, rather than by writing things down.","ex":{"en":"Paperless trading can save time and money.","cn":"无纸贸易能够省时省钱。"}}]},"examples":[{"en":"a system of paperless business transactions","cn":"无纸商业交易系统"},{"en":"the paperless office","cn":"无纸办公室"}]},"path":{"media":{"uk":"media/uk/path__gb_1.mp3","us":"media/us/path__us_1.mp3"},"oxford":{"phon":"pɑːθ","pos":"noun","senses":[{"en":"a way or track that is built or is made by the action of people walking","cn":"小路；小径","ex":{"en":"a dirt/gravel/concrete path","cn":"土路；碎石路；混凝土路"}},{"en":"a plan of action or a way of achieving something","cn":"行动计划；成功的途径","ex":{"en":"Her sister followed a different career path.","cn":"她的姐姐走了一条不同的职业道路。"}},{"en":"a line along which somebody/something moves; the space in front of somebody/something as they move","cn":"路线；道路","g":"[usually singular]","ex":{"en":"Three men blocked her path.","cn":"三个男人挡住了她的去路。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小路；小径","en":"A path is a long strip of ground which people walk along to get from one place to another.","ex":{"en":"We followed the path along the clifftops","cn":"我们沿着悬崖顶上的小路走。"}},{"pos":"N-COUNT 可数名词","cn":"（前面的）道路，通道","en":"Your path is the space ahead of you as you move along.","ex":{"en":"A group of reporters blocked his path","cn":"一群记者堵住了他的去路。"}},{"pos":"N-COUNT 可数名词","cn":"路线；轨迹","en":"The path of something is the line which it moves along in a particular direction.","ex":{"en":"He stepped without looking into the path of a reversing car.","cn":"一辆汽车正在倒车，他看都没看它倒向哪里就一脚迈了出去。"}},{"pos":"N-COUNT 可数名词","cn":"行动路线；途径","en":"A path that you take is a particular course of action or way of achieving something.","ex":{"en":"The opposition appear to have chosen the path of cooperation rather than confrontation","cn":"反对派似乎已经选择了合作而不是对抗的路线。"}},{"pos":"N-COUNT 可数名词","cn":"前进道路","en":"You can say that something is in your path or blocking your path to mean that it is preventing you from doing or achieving what you want.","ex":{"en":"The Church of England put a serious obstacle in the path of women who want to become priests.","cn":"英国国教在妇女成为牧师的道路上设置了重大障碍。"}},{"pos":"PHRASE 短语","cn":"偶遇","en":"If you cross someone's path or if your paths cross, you meet them by chance.","ex":{"en":"It was highly unlikely that their paths would cross again","cn":"他们再次偶遇的可能性非常小。"}}]},"examples":[{"en":"The avalanche forced its way down the mountain, crushing everything in its path.","cn":"雪崩冲下山来，摧毁了沿途的一切。"},{"en":"He threw himself into the path of an oncoming vehicle.","cn":"他冲入迎面有汽车驶来的路中。"}]},"pans":{"oxford":{"phon":"pæn","pos":"noun","senses":[{"en":"a container, usually made of metal, with a handle or handles, used for cooking food in","cn":"平锅；平底锅"},{"en":"the amount contained in a pan","cn":"一锅的量"}]}},"parallel":{"media":{"uk":"media/uk/parallel__gb_1.mp3","us":"media/us/parallel__us_1.mp3"},"oxford":{"phon":"ˈpærəlel","pos":"adjective","senses":[{"en":"two or more lines that are parallel to each other are the same distance apart at every point","cn":"平行（的）","ex":{"en":"parallel lines","cn":"平行线"}},{"en":"very similar or taking place at the same time","cn":"极相似的；同时发生的；相应的；对应的","ex":{"en":"parallel trends","cn":"并行发展的趋势"}},{"en":"involving several computer operations at the same time","cn":"并行的","lab":"computing","ex":{"en":"parallel processing","cn":"并行处理"}},{"en":"two or more lines that run parallel to each other are the same distance apart at every point","cn":"两条或多条彼此平行的线在每一点上的距离相同","ex":{"en":"The road and the canal run parallel to each other.","cn":"道路与运河平行。"},"pos":"adverb"},{"en":"in a way that is very similar or takes place at the same time","cn":"以非常相似或同时发生的方式","ex":{"en":"The team's findings run parallel to those of other researchers.","cn":"该团队的发现与其他研究人员的发现一致。"},"pos":"adverb"},{"en":"a person, a situation, an event, etc. that is very similar to another, especially one in a different place or time","cn":"（尤指不同地点或时间的）极其相似的人（或情况、事件等）","g":"[countable, uncountable]","ex":{"en":"These ideas have parallels in Freud's thought too.","cn":"这些观念与弗洛伊德思想中的某些观点也非常相似。"},"pos":"noun"},{"en":"similar features","cn":"相似特征；相似特点","g":"[countable, usually plural]","ex":{"en":"There are interesting parallels between the 1960s and the late 1990s.","cn":"20 世纪 60 年代和 90 年代后期有些颇有意思的相似之处。"},"pos":"noun"},{"en":"an imaginary line around the earth that is always the same distance from the equator; this line on a map","cn":"（地球或地图的）纬线，纬（度）圈","g":"[countable]","ex":{"en":"the 49th parallel","cn":"49 度纬线"},"pos":"noun"},{"en":"to be similar to something; to happen at the same time as something","cn":"与…相似；与…同时发生","ex":{"en":"Their legal system parallels our own.","cn":"他们的法律制度与我们的相似。"},"pos":"verb"},{"en":"to be as good as something","cn":"与…媲美；比得上","ex":{"en":"a level of achievement that has never been paralleled","cn":"绝无仅有的最高成就"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（存在或发生在不同地点或时间的）相似之物，类似物","en":"If something has a parallel, it is similar to something else, but exists or happens in a different place or at a different time. If it has no parallel or is without parallel, it is not similar to anything else.","ex":{"en":"Readers familiar with English history will find a vague parallel to the suppression of the monasteries","cn":"熟悉英国历史的读者会发现这与镇压修道院略有相似之处。"}},{"pos":"N-COUNT 可数名词","cn":"（两者间的）近似之处，相似之处","en":"If there are parallels between two things, they are similar in some ways.","ex":{"en":"Detailed study of folk music from a variety of countries reveals many close parallels","cn":"仔细研究各国民间音乐后发现了许多非常相似之处。"}},{"pos":"VERB 动词","cn":"与…同时发生；与…相似","en":"If one thing parallels another, they happen at the same time or are similar, and often seem to be connected.","ex":{"en":"Often there are emotional reasons paralleling the financial ones","cn":"往往情感方面的原因和经济方面原因同时存在。"}},{"pos":"ADJ 形容词","cn":"同时发生的；相类似的","en":"Parallel events or situations happen at the same time as one another, or are similar to one another.","ex":{"en":"...parallel talks between the two countries' Foreign Ministers","cn":"两国外交部长同时进行的会谈"}},{"pos":"ADJ 形容词","cn":"平行的；并列的","en":"If two lines, two objects, or two lines of movement are parallel, they are the same distance apart along their whole length.","ex":{"en":"...seventy-two ships, drawn up in two parallel lines","cn":"平行排成两队的72艘船"}},{"pos":"N-COUNT 可数名词","cn":"（标于地图上的）纬线，纬圈","en":"A parallel is an imaginary line round the earth that is parallel to the equator. Parallels are shown on maps.","ex":{"en":"...the area south of the 38th parallel.","cn":"38度纬线以南地区"}},{"pos":"PHRASE 短语","cn":"与…同时","en":"Something that occurs in parallel with something else occurs at the same time as it.","ex":{"en":"Davies has managed to pursue his diverse interests in parallel with his fast-moving career","cn":"戴维斯在事业突飞猛进的同时并未放弃自己广泛的兴趣爱好。"}}]},"examples":[{"en":"There are interesting parallels between the 1960s and the late 1990s. * 20","cn":"世纪 60 年代和 90 年代后期有些颇有意思的相似之处。"},{"en":"It is possible to draw a parallel between (= find similar features in) their experience and ours.","cn":"在他们的经历和我们的经历之间找到相似点是可能的。"}]},"pa":{"oxford":{"phon":"pɑː","pos":"noun","senses":[{"en":"father","cn":"爹；爸爸","ex":{"en":"I used to know your pa.","cn":"我过去跟你爸爸很熟。"}},{"en":"public address system","cn":"广播系统","ex":{"en":"Announcements were made over the PA.","cn":"通告是从广播系统播出的。"}},{"en":"a person who works as a secretary or an assistant for one person (the abbreviation for ‘personal assistant’)","cn":"私人助理，私人秘书（全写为 personal assistant）","lab":"especially British English","ex":{"en":"the PA to the Managing Director","cn":"董事总经理的私人助理"}},{"en":"Press Association","cn":"帕（斯卡）（标准压强单位）"},{"en":"pascal","cn":"帕（斯卡）（标准压强单位）","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 personal assistant","en":"A PA is the same as a personal assistant ."},{"pos":"N-COUNT 可数名词","cn":"有线广播系统；扩音系统","en":"If you refer to the PA or the PA system in a place, you are referring to the public address system.","ex":{"en":"A voice came booming over the PA","cn":"从有线广播系统中传出一个瓮声瓮气的声音。"}}]},"media":{"uk":"media/uk/pa__gb_1.mp3","us":"media/us/pa__us_1.mp3"},"examples":[{"en":"Announcements were made over the PA.","cn":"通告是从广播系统播出的。"},{"en":"She's the Managing Director's PA.","cn":"她是总经理的私人助理。"}]},"pagoda":{"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/pagoda.jpg"],"uk":"media/uk/pagoda__gb_1.mp3","us":"media/us/pagoda__us_1.mp3"},"oxford":{"phon":"pəˈɡəʊdə","pos":"noun","senses":[{"en":"a temple (= religious building) in South or East Asia in the form of a tall tower with several levels, each of which has its own roof that extends beyond the walls","cn":"（南亚或东亚的）佛塔"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指佛教中的）塔，宝塔","en":"A pagoda is a tall building which is used for religious purposes, especially by Buddhists, in China, Japan, and South-East Asia. Pagodas are usually very highly decorated."}]}},"pass":{"media":{"uk":"media/uk/pass__gb_1.mp3","us":"media/us/pass__us_1.mp3"},"oxford":{"phon":"pɑːs","pos":"verb","senses":[{"en":"to achieve the required standard in an exam, a test, etc.","cn":"及格；合格","g":"[intransitive, transitive]","sc":"test/exam","ex":{"en":"I'm not really expecting to pass first time.","cn":"我真不指望第一次就能合格。"}},{"en":"to test somebody and decide that they are good enough, according to an agreed standard","cn":"准予通过；承认合格","g":"[transitive]","sc":"test/exam","ex":{"en":"The examiners passed all the candidates.","cn":"主考人评定考生全部及格。"}},{"en":"to move past or to the other side of somebody/something","cn":"通过；走过","g":"[intransitive, transitive]","lab":"especially North American English","sc":"move","ex":{"en":"Several people were passing but nobody offered to help.","cn":"有几个人路过，却没有人主动伸出援手。"}},{"en":"to go or move in the direction mentioned","cn":"沿某方向前进；向某方向移动","g":"[intransitive]","sc":"move","ex":{"en":"The procession passed slowly along the street.","cn":"队伍沿街缓缓行进。"}},{"en":"to make something move in the direction or into the position mentioned","cn":"使沿（某方向）移动；使达到（某位置）","g":"[transitive]","sc":"move","ex":{"en":"He passed the rope around the post three times to secure it.","cn":"他把绳索在柱子上绕了三匝缠紧。"}},{"en":"to give something to somebody by putting it into their hands or in a place where they can easily reach it","cn":"给；递；传递","g":"[transitive]","sc":"give","ex":{"en":"Pass the salt, please.","cn":"请把盐递过来。"}},{"en":"to give somebody information or a message","cn":"传递信息；传送情报","g":"[transitive]","sc":"give","ex":{"en":"His wife had been passing information to the police.","cn":"他的妻子一直在向警方传递信息。"}},{"en":"to kick, hit or throw the ball to a player of your own side","cn":"传球","g":"[transitive, intransitive]","sc":"ball","ex":{"en":"He passed the ball to Sterling.","cn":"他把球传给斯特林。"}},{"en":"when time passes, it goes by","cn":"推移；逝去","g":"[intransitive]","sc":"time","ex":{"en":"Almost fifty years have passed since that day.","cn":"从那天起，已经过去了将近五十年。"}},{"en":"to spend time, especially when you are bored or waiting for something","cn":"消磨；度过；打发","g":"[transitive]","sc":"time","ex":{"en":"We sang songs to pass the time.","cn":"我们借唱歌消磨时间。"}},{"en":"to come to an end; to be over","cn":"结束；完结","g":"[intransitive]","sc":"end","ex":{"en":"They waited for the storm to pass.","cn":"他们等待暴风雨过去。"}},{"en":"to change from one state or condition to another","cn":"转变；变化；过渡","g":"[intransitive]","sc":"change","ex":{"en":"She had passed from childhood to early womanhood.","cn":"她已由童年进入了少女期。"}},{"en":"to be given to another person after first belonging to somebody else, especially after the first person has died","cn":"转移给，遗留给（继承人等）","g":"[intransitive]","sc":"after death","ex":{"en":"On his death, the title passed to his eldest son.","cn":"他死后，封号传给长子。"}},{"en":"to become greater than a particular total","cn":"大于；超过","g":"[transitive]","sc":"become greater","ex":{"en":"Unemployment has now passed the three million mark.","cn":"失业人数现已突破三百万大关。"}},{"en":"to accept a proposal, law, etc. by voting; to be accepted in this way","cn":"表决通过（动议、法律等）；（动议、法律等）经表决通过","g":"[transitive, intransitive]","lab":"especially North American English","sc":"law/proposal","ex":{"en":"to pass a bill/law/resolution","cn":"通过一项法案／法律／决议"}},{"en":"to be allowed","cn":"得到允许","g":"[intransitive]","sc":"happen","ex":{"en":"I don't like it, but I'll let it pass (= will not object).","cn":"我不喜欢，但我也不会反对。"}},{"en":"to happen; to be said or done","cn":"发生；说出（或做出）","g":"[intransitive]","sc":"happen","ex":{"en":"They'll never be friends again after all that has passed between them.","cn":"经过了这么多事情，他们已经友谊难再了。"}},{"en":"to say that you do not know the answer to a question, especially during a quiz","cn":"不知道，过（尤在回答竞赛问题时所用）","g":"[intransitive]","sc":"not know","ex":{"en":"‘What's the capital of Peru?’ ‘I'll have to pass on that one.’","cn":"“秘鲁的首都是哪里？”“过。”"}},{"en":"to say that you do not want something that is offered to you","cn":"不要；免掉","g":"[intransitive]","sc":"not want","ex":{"en":"Thanks. I'm going to pass on dessert, if you don't mind.","cn":"谢谢，您若不介意，我就免了饭后甜点吧。"}},{"en":"to say or state something, especially officially","cn":"宣布；声明","g":"[transitive]","sc":"say/state something","ex":{"en":"The court waited in silence for the judge to pass sentence.","cn":"全体出庭人员默默等待法官宣判。"}},{"en":"to go beyond the limits of what you can believe, understand, etc.","cn":"超出…的限度","g":"[transitive]","lab":"formal","sc":"belief/understanding","ex":{"en":"It passes belief (= is impossible to believe) that she could do such a thing.","cn":"很难相信她会做出这等事来。"}},{"en":"to refuse to play a card or make a bid when it is your turn","cn":"不出牌；不叫牌；过","g":"[intransitive]","sc":"in card games"},{"en":"to send something out from the body as or with waste matter","cn":"排泄；排出","g":"[transitive]","sc":"from the body","ex":{"en":"If you're passing blood you ought to see a doctor.","cn":"如果便中带血，你就应该找大夫看看。"}},{"en":"an official document or ticket that shows that you have the right to enter or leave a place, to travel on a bus or train, etc.","cn":"通行证；车票；乘车证","sc":"official document","ex":{"en":"a boarding pass (= for a plane)","cn":"登机牌"},"pos":"noun"},{"en":"a successful result in an exam or test","cn":"及格；合格；通过","lab":"especially British English","sc":"in exam","ex":{"en":"She got a pass in French.","cn":"她法语考试及格了。"},"pos":"noun"},{"en":"(in some sports) an act of hitting or throwing the ball to another player in your team","cn":"（某些运动中）传球","sc":"of ball","ex":{"en":"a long pass to Turner","cn":"给特纳的一个长传"},"pos":"noun"},{"en":"a road or way over or through mountains","cn":"关口；关隘；山路","sc":"through mountains","ex":{"en":"a mountain pass","cn":"山口"},"pos":"noun"},{"en":"an act of going or moving past or over something","cn":"越过；飞跃","sc":"moving past/over","ex":{"en":"The helicopter made several passes over the village before landing.","cn":"直升机在村落上空盘旋数次才降落。"},"pos":"noun"},{"en":"a stage in a process, especially one that involves separating things from a larger group","cn":"阶段；步骤","sc":"stage in process","ex":{"en":"In the first pass all the addresses are loaded into the database.","cn":"第一步，所有地址均输入数据库。"},"pos":"noun"},{"en":"a choice or suggestion that is rejected or dismissed","cn":"被拒绝或驳回的选择或建议","g":"[usually singular]","lab":"North American English, informal，，","sc":"something that is rejected","ex":{"en":"If you don't like spicy food, you may want to give that dish a pass.","cn":"如果你不喜欢辛辣的食物，你可能不想吃这道菜。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"经过；通过","en":"To pass someone or something means to go past them without stopping.","ex":{"en":"As she passed the library door, the telephone began to ring","cn":"她经过图书室门口时，电话响了。"}},{"pos":"","cn":"（沿特定方向）行进，穿过，穿越","en":"When someone or something passes in a particular direction, they move in that direction.","ex":{"en":"He passed through the doorway into Ward B","cn":"他穿过门口进入B病房。"}},{"pos":"","cn":"（道路、管道等）延伸，伸展","en":"If something such as a road or pipe passes along a particular route, it goes along that route.","ex":{"en":"After going over the Col de Vars, the route passes through St-Paul-sur-Ubaye","cn":"这条道越过瓦尔山口之后，穿过于拜河畔圣保罗。"}},{"pos":"","cn":"使穿过；使通过；使越过","en":"If you pass something through, over, or round something else, you move or push it through, over, or round that thing.","ex":{"en":"She passed the needle through the rough cloth, back and forth","cn":"她一针一针地缝那块粗布。"}},{"pos":"","cn":"递；传递","en":"If you pass something to someone, you take it in your hand and give it to them.","ex":{"en":"Ken passed the books to Sergeant Parrott","cn":"肯把那些书递给帕罗特警官。"}},{"pos":"","cn":"转移；移交","en":"If something passes or is passed from one person to another, the second person then has it instead of the first.","ex":{"en":"His mother's small estate had passed to him after her death","cn":"他母亲死后留给他一小笔遗产。"}},{"pos":"","cn":"告诉，告知，传递（信息）","en":"If you pass information to someone, you give it to them because it concerns them.","ex":{"en":"Officials failed to pass vital information to their superiors","cn":"官员们没有将重要信息汇报给他们的上司。"}},{"pos":"","cn":"传（球）","en":"If you pass the ball to someone in your team in a game such as football, basketball, hockey, or rugby, you kick, hit, or throw it to them.","ex":{"en":"Your partner should then pass the ball back to you","cn":"然后你的搭档应该将球回传给你。"}},{"pos":"","cn":"（时间）消逝，过去","en":"When a period of time passes, it happens and finishes.","ex":{"en":"He couldn't imagine why he had let so much time pass without contacting her","cn":"他想不通自己为什么过了那么长时间还没有和她联系。"}},{"pos":"","cn":"度过（时间）","en":"If you pass a period of time in a particular way, you spend it in that way.","ex":{"en":"The children passed the time playing in the streets","cn":"那些孩子在街上玩耍打发时间。"}},{"pos":"","cn":"经历；遭受","en":"If you pass through a stage of development or a period of time, you experience it.","ex":{"en":"The country was passing through a grave crisis","cn":"那个国家正在经历一场严重危机。"}},{"pos":"","cn":"超过；超越","en":"If an amount passes a particular total or level, it becomes greater than that total or level.","ex":{"en":"They became the first company in their field to pass the £2 billion turn-over mark.","cn":"他们成为自己所在领域中首家营业额超过20亿英镑的公司。"}},{"pos":"","cn":"通过（测试）","en":"If someone or something passes a test, they are considered to be of an acceptable standard.","ex":{"en":"Kevin has just passed his driving test","cn":"凯文刚刚通过驾照考试。"}},{"pos":"","cn":"（考试的）通过，及格","en":"A pass in an examination, test, or course is a successful result in it.","ex":{"en":"An A-level pass in Biology is preferred for all courses","cn":"不管读什么课程，生物学高级证书考试最好都要及格。"}},{"pos":"","cn":"宣布…合格；核准；批准","en":"If someone in authority passes a person or thing, they declare that they are of an acceptable standard or have reached an acceptable standard.","ex":{"en":"Several popular beaches were found unfit for bathing although the government passed them last year","cn":"有几家火爆的海滨浴场被查出不适于游泳，但是去年政府却宣布他们合格。"}},{"pos":"","cn":"通过，批准（法律或议案）","en":"When people in authority pass a new law or a proposal, they formally agree to it or approve it.","ex":{"en":"The Estonian parliament has passed a resolution declaring the republic fully independent","cn":"爱沙尼亚议会已经通过了宣布共和国完全独立的决议。"}},{"pos":"","cn":"宣布（判决）","en":"When a judge passes sentence on someone, he or she says what their punishment will be.","ex":{"en":"Passing sentence, the judge said it all had the appearance of a con trick","cn":"宣布判决时，法官称其完全符合诈骗案的要素。"}},{"pos":"","cn":"发（言）；陈述（意见）","en":"If you pass comment or pass a comment, you say something.","ex":{"en":"I don't really know so I could not pass comment on that","cn":"我不了解实情，所以我不能就此发表意见。"}},{"pos":"","cn":"被说出；被做出","en":"If something passes without comment, or passes unnoticed, nobody comments on it, reacts to it, or notices it.","ex":{"en":"This practice embarrassed Luther, but he let it pass without comment","cn":"这种做法让卢瑟难堪，但是他未置一词。"}},{"pos":"","cn":"被认作；被当作","en":"If someone or something passes for or passes as something that they are not, they are accepted as that thing or mistaken for that thing.","ex":{"en":"Children's toy guns now look so realistic that they can often pass for the real thing","cn":"现在的儿童玩具枪看起来过于逼真，以至常常被误认作真枪。"}},{"pos":"","cn":"推后","en":"If someone makes you an offer or asks you a question and you say that you will pass on it, you mean that you do not want to accept or answer it now.","ex":{"en":"I think I'll pass on the hiking next time","cn":"我想远足的事下次再说吧。"}},{"pos":"","cn":"排泄","en":"If someone passes water or passes urine, they urinate.","ex":{"en":"A sensitive bladder can make you feel the need to pass water frequently.","cn":"敏感性膀胱让你有尿频感。"}},{"pos":"","cn":"通行证；入场证；乘车证","en":"A pass is a document that allows you to do something.","ex":{"en":"I got myself a pass into the barracks","cn":"我弄到了进兵营的通行证。"}},{"pos":"","cn":"关口；山口","en":"A pass is a narrow path or route between mountains.","ex":{"en":"The monastery is in a remote mountain pass.","cn":"那个修道院在一个偏远的山口中。"}},{"pos":"","cn":"勾引；挑逗","en":"If someone makes a pass at you, they try to begin a romantic or sexual relationship with you.","ex":{"en":"Nancy wasn't sure if Dirk was making a pass at her.","cn":"南希不确定德克是不是在勾引她。"}},{"pos":"","cn":"","en":"to pass the buck→see: ; to pass judgment→see: ; to pass the time of day→see: ;"},{"pos":"","cn":"","en":"相关词组：pass around pass away pass by pass off pass off as pass on pass out pass over pass round pass up"}]},"examples":[{"en":"Much of the discount is pocketed by retailers instead of being passed on to customers.","cn":"折扣的大部分进了零售商的腰包，而顾客没有得到实惠。"},{"en":"The bill was passed by 360 votes to 280.","cn":"这个法案以 360 票对 280 票获得通过。"}]},"patrol":{"media":{"uk":"media/uk/patrol__gb_1.mp3","us":"media/us/patrol__us_1.mp3"},"oxford":{"phon":"pəˈtrəʊl","pos":"noun","senses":[{"en":"the act of going to different parts of a building, an area, etc. to make sure that there is no trouble or crime","cn":"巡逻；巡查","g":"[countable, uncountable]","ex":{"en":"Security guards make regular patrols at night.","cn":"保安人员在夜里定时巡逻。"}},{"en":"a group of soldiers, vehicles, etc. that patrol an area","cn":"巡逻队；巡逻车队","g":"[countable]","ex":{"en":"a naval/police patrol","cn":"海军／警察巡逻队"}},{"en":"a group of about six Boy Scouts or Girl Guides / Girl Scouts that forms part of a larger group","cn":"（约六人的）童子军小队","g":"[countable]"},{"en":"to go around an area or a building at regular times to check that it is safe and that there is no trouble","cn":"巡逻；巡查","ex":{"en":"Troops patrolled the border day and night.","cn":"军队日夜在边境地区巡逻。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"巡逻；巡查","en":"When soldiers, police, or guards patrol an area or building, they move around it in order to make sure that there is no trouble there.","ex":{"en":"Prison officers continued to patrol the grounds within the jail.","cn":"狱警继续巡视监狱。"}},{"pos":"PHRASE 短语","cn":"巡逻","en":"Soldiers, police, or guards who are on patrol are patrolling an area.","ex":{"en":"The army is now on patrol in Srinagar and a curfew has been imposed","cn":"军队目前在斯利那加巡逻，且已实行了宵禁。"}},{"pos":"N-COUNT 可数名词","cn":"巡逻队；巡逻车队","en":"A patrol is a group of soldiers or vehicles that are patrolling an area.","ex":{"en":"Guerrillas attacked a patrol with hand grenades.","cn":"游击队用手榴弹袭击了巡逻队。"}}]},"examples":[{"en":"Gangs of youths patrol the streets at night.","cn":"夜里成帮结伙的年轻人在街上闲逛。"},{"en":"Troops patrolled the border day and night.","cn":"军队日夜在边境地区巡逻。"}]},"painfully":{"media":{"uk":"media/uk/painfully__gb_1.mp3","us":"media/us/painfully__us_1.mp3"},"oxford":{"phon":"ˈpeɪnfəli","pos":"adverb","senses":[{"en":"extremely, and in a way that makes you feel annoyed, upset, etc.","cn":"非常地；令人痛苦地；令人烦恼地","ex":{"en":"Their son was painfully shy.","cn":"他们的儿子非常害羞。"}},{"en":"in a way that causes you physical or emotional pain","cn":"使人疼痛地；令人苦恼地","ex":{"en":"He banged his knee painfully against the desk.","cn":"他的膝盖撞到桌子上，疼得很。"}},{"en":"with a lot of effort and difficulty","cn":"吃力地；艰难地","ex":{"en":"painfully acquired experience","cn":"艰难获得的经验"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（用于强调讨厌的性质或情形）非常，极其","en":"You use painfully to emphasize a quality or situation that is undesirable.","ex":{"en":"Things are moving painfully slowly.","cn":"事情进展奇慢无比。"}}]},"examples":[{"en":"He was painfully aware of his lack of experience.","cn":"他痛苦地意识到自己缺乏经验。"},{"en":"He banged his knee painfully against the desk.","cn":"他的膝盖撞到桌子上，疼得很。"}]},"parentage":{"oxford":{"phon":"ˈpeərəntɪdʒ","pos":"noun","senses":[{"en":"the origin of a person’s parents and who they are","cn":"出身；世系；家世","ex":{"en":"a young American of German parentage","cn":"一个年轻的德裔美国人"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"出身；家世；世系","en":"Your parentage is the identity and origins of your parents. For example, if you are of Greek parentage, your parents are Greek.","ex":{"en":"She's a Londoner of mixed parentage (English and Jamaican)","cn":"她是个混血（英国和牙买加）伦敦人。"}}]},"media":{"uk":"media/uk/parentage__gb_1.mp3","us":"media/us/parentage__us_1.mp3"},"examples":[{"en":"a young American of German parentage","cn":"一个年轻的德裔美国人"},{"en":"Nothing is known about her parentage and background.","cn":"她的家世和来历不明。"}]},"participation":{"media":{"uk":"media/uk/participation__gb_1.mp3","us":"media/us/participation__us_1.mp3"},"oxford":{"phon":"pɑːˌtɪsɪˈpeɪʃn","pos":"noun","senses":[{"en":"the act of taking part in an activity or event","cn":"参加；参与","ex":{"en":"a show with lots of audience participation","cn":"观众热烈参与的演出"}}]},"examples":[{"en":"A back injury prevented active participation in any sports for a while.","cn":"背伤曾一度妨碍积极参加任何体育运动。"},{"en":"a show with lots of audience participation","cn":"观众热烈参与的演出"}]},"paralinguistic":{"oxford":{"phon":"ˌpærəlɪŋˈɡwɪstɪk","pos":"adjective","senses":[{"en":"relating to communication through ways other than words, for example tone of voice, expressions on your face and actions","cn":"副语言的，辅助语言的，伴随语言的（通过声调、表情、行动等交流）"}]},"media":{"uk":"media/uk/paralinguistic__gb_1.mp3","us":"media/us/paralinguistic__us_1.mp3"}},"parlour":{"media":{"uk":"media/uk/parlour__gb_1.mp3","us":"media/us/parlour__us_1.mp3"},"oxford":{"phon":"ˈpɑːlə(r)","pos":"noun","senses":[{"en":"a room in a private house for sitting in, entertaining visitors, etc.","cn":"（私人住房的）起居室，客厅","lab":"old-fashioned"},{"en":"a shop that provides particular goods or services","cn":"（专营某种商品或业务的）商店，店铺","lab":"especially North American English","ex":{"en":"a beauty/an ice-cream parlour","cn":"美容院；冰激凌店"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"客厅；起居室","en":"A parlour is a room in a house for sitting in."},{"pos":"N-COUNT 可数名词","cn":"（提供服务而不销售货物的）店铺（用于店名中）","en":"Parlour is used in the names of some types of shops which provide a service, rather than selling things.","ex":{"en":"...a funeral parlour.","cn":"殡仪馆"}}]},"examples":[{"en":"a beauty/an ice-cream parlour","cn":"美容院；冰淇淋店"}]},"panoramic":{"media":{"uk":"media/uk/panoramic__gb_1.mp3","us":"media/us/panoramic__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全景的；远景的","en":"If you have a panoramic view, you can see a long way over a wide area.","ex":{"en":"The terrain's high points provide a panoramic view of Los Angeles.","cn":"在这个地区的制高点能够看到洛杉矶的全景。"}}]},"examples":[{"en":"a panoramic view over the valley","cn":"山谷的全景"},{"en":"The tower offers a panorama of the city.","cn":""}],"oxford":{"phon":"ˌpænəˈræmɪk","pos":"adjective","senses":[{"en":"with a view of a wide area of land","cn":"全景","ex":{"en":"a panoramic view over the valley","cn":"山谷的全景"}},{"en":"presenting all the different aspects or stages of a particular subject, event, etc.","cn":"（某专题或事件的）全面叙述，综合研究；全景画卷","ex":{"en":"The book offers a panoramic vision of American culture and politics.","cn":"这本书提供了美国文化和政治的全景视野。"}}]}},"pattern":{"media":{"uk":"media/uk/pattern__gb_1.mp3","us":"media/us/pattern__us_1.mp3"},"oxford":{"phon":"ˈpætn","pos":"noun","senses":[{"en":"the regular way in which something happens or is done","cn":"模式；方式","ex":{"en":"changing patterns of urban life","cn":"变化中的城市生活模式"}},{"en":"an excellent example to copy","cn":"范例；典范；榜样；样板","g":"[usually singular]","ex":{"en":"This system sets the pattern for others to follow.","cn":"这个系统堪为他人仿效的典范。"}},{"en":"a regular arrangement of lines, shapes, colours, etc. for example as a design on material, carpets, etc.","cn":"图案；花样；式样","ex":{"en":"a pattern of diamonds and squares","cn":"菱形和正方形构成的图案"}},{"en":"a design, set of instructions or shape to cut around that you use in order to make something","cn":"模型；底样；纸样","ex":{"en":"a knitting pattern","cn":"编织图样"}},{"en":"a small piece of material, paper, etc. that helps you choose the design of something","cn":"样品；样本","ex":{"en":"wallpaper patterns","cn":"壁纸样品"}},{"en":"to form a regular arrangement of lines or shapes on something","cn":"构成图案（或花样）","ex":{"en":"Frost patterned the window.","cn":"霜在窗子上形成了图案。"},"pos":"verb"},{"en":"to cause a particular type of behaviour to develop","cn":"使形成，促成（某行为模式）","lab":"specialist","ex":{"en":"Adult behaviour is often patterned by childhood experiences.","cn":"成年人的行为模式往往受童年经历影响。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模式；方式","en":"A pattern is the repeated or regular way in which something happens or is done.","ex":{"en":"All three attacks followed the same pattern","cn":"3次袭击模式相同。"}},{"pos":"N-COUNT 可数名词","cn":"图案；花样","en":"A pattern is an arrangement of lines or shapes, especially a design in which the same shape is repeated at regular intervals over a surface.","ex":{"en":"...a golden robe embroidered with red and purple thread stitched into a pattern of flames.","cn":"用红线和紫线绣着火焰图案的金色礼袍"}},{"pos":"N-COUNT 可数名词","cn":"模型；样板","en":"A pattern is a diagram or shape that you can use as a guide when you are making something such as a model or a piece of clothing.","ex":{"en":"...cutting out a pattern for trousers","cn":"裁出裤子的样板"}}]},"examples":[{"en":"Adult behaviour is often patterned by childhood experiences.","cn":"成年人的行为模式往往是童年经历造成的。"},{"en":"She bought a dress pattern and some material.","cn":"她买了一幅衣服纸样和一些衣料。"}]},"paid":{"media":{"uk":"media/uk/paid__gb_1.mp3","us":"media/us/paid__us_1.mp3"},"oxford":{"phon":"peɪd","pos":"adjective","senses":[{"en":"for which people receive money","cn":"有偿的；付费的","g":"[usually before noun]","ex":{"en":"Neither of them is currently in paid employment.","cn":"他们俩目前都没有挣钱的差事。"}},{"en":"receiving money for doing work","cn":"有报酬的；有薪金的","g":"[usually before noun]","ex":{"en":"Men still outnumber women in the paid workforce.","cn":"在上班挣钱的人口中，男性仍然多于女性。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Paid is the past tense and past participle of pay ."},{"pos":"ADJ 形容词","cn":"有报酬的；领取薪金的","en":"Paid workers, or people who do paid work, receive money for the work that they do.","ex":{"en":"Apart from a small team of paid staff, the organisation consists of unpaid volunteers.","cn":"除了一小组受薪员工外，这个组织里都是不领报酬的志愿者。"}},{"pos":"ADJ 形容词","cn":"（休假）带薪的","en":"If you are given paid holiday, you get your wages or salary even though you are not at work.","ex":{"en":"...10 days' paid holiday for house hunting","cn":"用于找房子的10天带薪假期"}},{"pos":"ADJ 形容词","cn":"报酬…的；薪水…的","en":"If you are well paid, you receive a lot of money for the work that you do. If you are badly paid, you do not receive much money.","ex":{"en":"...a well-paid accountant","cn":"高收入的会计师"}},{"pos":"PHRASE 短语","cn":"彻底终结；使化为泡影","en":"If an unexpected event puts paid to someone's hopes, chances, or plans, it completely ends or destroys them.","ex":{"en":"...a series of airforce strikes that put paid to the General's hopes of fighting on","cn":"一连串空中打击粉碎了那位将军继续战斗的希望"}}]},"examples":[{"en":"Men still outnumber women in the paid workforce.","cn":"在上班挣钱的人口中，男性仍然多于女性。"},{"en":"Neither of them is currently in paid employment.","cn":"他们俩目前都没有挣钱的差事。"}]},"pantomime":{"media":{"uk":"media/uk/pantomime__gb_1.mp3","us":"media/us/pantomime__us_1.mp3"},"oxford":{"phon":"ˈpæntəmaɪm","pos":"noun","senses":[{"en":"(in the UK) a type of play with music, dancing and jokes, that is based on a fairy tale and is usually performed at Christmas","cn":"（英国多在圣诞节期间上演的）童话剧","g":"[countable, uncountable]","lab":"also British English, informal，，","ex":{"en":"We took the children to a pantomime.","cn":"我们带孩子们去看童话剧。"}},{"en":"the use of movement and the expression of your face to communicate something or to tell a story","cn":"哑剧；默剧","g":"[uncountable, countable, usually singular]","ex":{"en":"a magical tale told through pantomime and song","cn":"通过哑剧和歌曲讲述的神奇故事"}},{"en":"a silly and confused situation","cn":"滑稽可笑的场面","g":"[countable, usually singular]","lab":"British English","ex":{"en":"The company’s board meetings had become a pantomime and no decisions were ever made.","cn":"该公司的董事会会议成了一场闹剧，从未做出任何决定。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"圣诞童话剧","en":"A pantomime is a funny musical play for children. Pantomimes are usually based on fairy stories and are performed at Christmas."},{"pos":"N-UNCOUNT 不可数名词","cn":"圣诞童话剧演出","en":"Pantomime is the form of entertainment which involves producing a pantomime.","ex":{"en":"What she does very well is pantomime","cn":"她擅长圣诞童话剧演出。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"哑剧","en":"Pantomime is acting something out without speaking.","ex":{"en":"Chaplin feared that the art of pantomime was under threat.","cn":"卓别林担心哑剧艺术面临威胁。"}},{"pos":"N-SING 单数名词","cn":"闹剧；（行为的）滑稽愚蠢","en":"If you say that a situation or a person's behaviour is a pantomime, you mean that it is silly or exaggerated and that there is something false about it.","ex":{"en":"They were made welcome with the usual pantomime of exaggerated smiles and gestures","cn":"他们受到了一如往常的欢迎，夸张的笑容和姿态如同一场闹剧。"}}]}},"pair":{"media":{"uk":"media/uk/pair__gb_1.mp3","us":"media/us/pair__us_1.mp3","img":["media/ldoce/img/pair_boots.jpg"]},"oxford":{"phon":"peə(r)","pos":"noun","senses":[{"en":"two things of the same type, especially when they are used or worn together","cn":"一双；一对","g":"[countable]","sc":"two things the same","ex":{"en":"a pair of shoes/boots","cn":"一双鞋子／靴子"}},{"en":"an object consisting of two parts that are joined together","cn":"由两个相连接部分组成的物体","g":"[countable]","lab":"North American English","sc":"two parts joined","ex":{"en":"a pair of trousers/pants/jeans","cn":"一条长裤／裤子／牛仔裤"}},{"en":"two people who are doing something together or who have a particular relationship","cn":"两个共事（或有特殊关系）的人；俩；对","g":"[countable + singular or plural verb]","lab":"informal","sc":"two people","ex":{"en":"Get pairs of students to act out the dialogue in front of the class.","cn":"叫学生两人一组在课堂上演出这个对话。"}},{"en":"two animals or birds of the same type that are producing young together","cn":"一对鸟（或兽）","g":"[countable + singular or plural verb]","sc":"two animals/birds","ex":{"en":"a breeding pair","cn":"用于繁殖的一对"}},{"en":"two horses working together to pull a carriage","cn":"一起拉车的两匹马","g":"[countable]","sc":"two horses","ex":{"en":"a carriage and pair","cn":"双驾马车"}},{"en":"to put people or things into groups of two","cn":"使成对；配对","g":"[transitive, usually passive]","sc":"make groups of two","ex":{"en":"Each blind student was paired with a sighted student.","cn":"每个盲人学员都与一个视力正常的同学配对。"},"pos":"verb"},{"en":"to come together in order to produce young","cn":"配对（以繁殖）；交配","g":"[intransitive]","lab":"specialist","sc":"of animals/birds","ex":{"en":"Many of the species pair for life.","cn":"这一物种中许多是终生配对。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"双；对；副","en":"A pair of things are two things of the same size and shape that are used together or are both part of something, for example shoes, earrings, or parts of the body.","ex":{"en":"...a pair of socks.","cn":"一双袜子"}},{"pos":"N-COUNT 可数名词","cn":"套，条，把，副（由两个尺寸和形状相同的部分组成的物品，如裤子、剪刀）","en":"Some objects that have two main parts of the same size and shape are referred to as a pair, for example a pair of trousers or a pair of scissors .","ex":{"en":"...a pair of faded jeans.","cn":"一条褪色的牛仔裤"}},{"pos":"N-SING 单数名词","cn":"一对伴儿；一对夫妻；一对情侣","en":"You can refer to two people as a pair when they are standing or walking together or when they have some kind of relationship with each other.","ex":{"en":"A pair of teenage boys were smoking cigarettes","cn":"两个十来岁的男孩正在吸烟。"}},{"pos":"VERB 动词","cn":"使配对；使配成搭档","en":"If one thing is paired with another, it is put with it or considered with it.","ex":{"en":"The trainees will then be paired with experienced managers.","cn":"实习生随后将会与经验丰富的经理结成对子。"}},{"pos":"PHRASE 短语","cn":"可靠的好帮手；可以委托的人","en":"If you say that someone is or has a safe pair of hands, you mean that they are reliable and will not make any serious mistakes.","ex":{"en":"He has now held five cabinet posts and remains a safe pair of hands.","cn":"他现在担任5个内阁职位，仍是一个靠得住的人。"}},{"pos":"","cn":"","en":"相关词组：pair off pair up"}]},"examples":[{"en":"Each blind student was paired with a sighted student.","cn":"每个盲人学员都与一个视力正常的同学配对。"},{"en":"a pair of glasses/binoculars/scissors, etc.","cn":"一副眼镜、一架双筒望远镜、一把剪刀等"}]},"palm":{"media":{"img":["media/pic/hand_body_comp.jpg","media/thumb/hand.jpg"],"uk":"media/uk/palm__gb_1.mp3","us":"media/us/palm__us_1.mp3"},"oxford":{"phon":"pɑːm","pos":"noun","senses":[{"en":"a straight tree with a mass of long leaves at the top, growing in tropical countries. There are several types of palm tree, some of which produce fruit.","cn":"棕榈树","ex":{"en":"a date palm","cn":"枣椰树"}},{"en":"the inner surface of the hand between the wrist and the fingers","cn":"手掌；手心","ex":{"en":"He held the bird gently in the palm of his hand.","cn":"他把小鸟轻轻地托在掌心。"}},{"en":"to hide a coin, card, etc. in your hand, especially when performing a trick","cn":"把…藏在手中（尤指玩戏法）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"棕榈树","en":"A palm or a palm tree is a tree that grows in hot countries. It has long leaves growing at the top, and no branches."},{"pos":"N-COUNT 可数名词","cn":"手掌","en":"The palm of your hand is the inside part.","ex":{"en":"Dornberg slapped the table with the palm of his hand","cn":"多恩伯格用手拍着桌子。"}},{"pos":"PHRASE 短语","cn":"在…的手心里；在…的完全掌控中","en":"If you have someone or something in the palm of your hand, you have control over them.","ex":{"en":"Johnson thought he had the board of directors in the palm of his hand","cn":"约翰逊以为自己完全掌控了董事会。"}},{"pos":"","cn":"","en":"相关词组：palm off palm off with"}]},"examples":[{"en":"They were trying to palm the table off as a genuine antique.","cn":"他们在设法把那张普通桌子当真正的古董推销出去。"},{"en":"She's always palming the worst jobs off on her assistant.","cn":"她总是哄骗她的助手做最苦的差事。"}]},"paras":{"media":{"uk":"media/uk/para__gb_1.mp3","us":"media/us/para__us_1.mp3"}},"patron":{"media":{"uk":"media/uk/patron__gb_1.mp3","us":"media/us/patron__us_1.mp3"},"oxford":{"phon":"ˈpeɪtrən","pos":"noun","senses":[{"en":"a person who gives money and support to artists and writers","cn":"（艺术家、作家的）赞助人，资助者","ex":{"en":"Frederick the Great was the patron of many artists.","cn":"腓特烈大帝是许多艺术家的赞助人。"}},{"en":"a famous person who supports an organization such as a charity and whose name is used in the advertisements, etc. for the organization","cn":"名义赞助人（支持慈善组织等的名人，名字常用于有关的广告宣传中）","ex":{"en":"the official patron of the college","cn":"学院的官方赞助人"}},{"en":"a person who uses a particular shop, restaurant, etc.","cn":"老主顾；顾客；常客","lab":"formal","ex":{"en":"Patrons are requested not to smoke.","cn":"请顾客不要吸烟。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（艺术家、作家和音乐家等的）赞助人，资助人","en":"A patron is a person who supports and gives money to artists, writers, or musicians.","ex":{"en":"Catherine the Great was a patron of the arts and sciences.","cn":"叶卡捷琳娜大帝资助发展艺术和科学。"}},{"pos":"N-COUNT 可数名词","cn":"（允许慈善机构、团体和活动等使用自己的名字作宣传的）代言人，名义赞助人","en":"The patron of a charity, group, or campaign is an important person who allows his or her name to be used for publicity.","ex":{"en":"Fiona and Alastair have become patrons of the National Missing Person's Helpline.","cn":"菲奥娜和阿拉斯泰尔已经成为国家失踪人口服务热线的代言人。"}},{"pos":"N-COUNT 可数名词","cn":"（酒吧、旅馆等的）主顾，顾客","en":"The patrons of a place such as a pub, bar, or hotel are its customers.","ex":{"en":"He spent the night at the Savoy: like so many of its patrons, he could not resist the exclusively English cooking.","cn":"他在萨沃伊酒店过了夜：和许多顾客一样，他无法抗拒精美的英式菜肴。"}}]},"examples":[{"en":"Frederick the Great was the patron of many artists.","cn":"腓特烈大帝是许多艺术家的赞助人。"},{"en":"Patrons are requested not to smoke.","cn":"请顾客不要吸烟。"}]},"part-time":{"oxford":{"phon":"ˌpɑːt ˈtaɪm","pos":"adjective, adverb","senses":[{"en":"for part of the day or week in which people work","cn":"部分时间的；兼职（的）","ex":{"en":"She's looking for a part-time job.","cn":"她在寻找兼职工作。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非全日制的；兼职的","en":"If someone is a part-time worker or has a part-time job, they work for only part of each day or week.","ex":{"en":"Many businesses are cutting back by employing lower-paid part-time workers","cn":"很多企业通过雇用薪金低廉的兼职工人来减少开支。"}}]},"media":{"uk":"media/uk/part_time_1_gb_1.mp3","us":"media/us/part_time_1_us_1.mp3"},"examples":[{"en":"Liz works part-time from 10 till 2.","cn":"利兹的兼职时间是 10 点到 2 点。"},{"en":"She's looking for a part-time job.","cn":"她在寻找兼职工作。"}]},"particularly":{"media":{"uk":"media/uk/particularly__gb_1.mp3","us":"media/us/particularly__us_1.mp3"},"oxford":{"phon":"pəˈtɪkjələli","pos":"adverb","senses":[{"en":"especially; more than usual or more than others","cn":"特别；尤其","ex":{"en":"particularly useful/important/interesting","cn":"特别有用／重要／有趣"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"特别；尤其","en":"You use particularly to indicate that what you are saying applies especially to one thing or situation.","ex":{"en":"Keep your office space looking good, particularly your desk","cn":"保持办公环境的整洁，尤其是你的桌子。"}},{"pos":"ADV 副词","cn":"格外；异乎寻常地","en":"Particularly means more than usual or more than other things.","ex":{"en":"Progress has been particularly disap-pointing","cn":"进展情况格外令人失望。"}}]},"examples":[{"en":"‘Did you enjoy it?’ ‘No, not particularly (= not very much). ’ “","cn":"你玩得开心吗？” “不很开心。”"},{"en":"Traffic is bad, particularly in the city centre.","cn":"交通状况很差，尤其是在市中心。"}]},"pay":{"media":{"uk":"media/uk/pay__gb_1.mp3","us":"media/us/pay__us_1.mp3"},"oxford":{"phon":"peɪ","pos":"verb","senses":[{"en":"to give somebody money for work, goods, services, etc.","cn":"付费；付酬","g":"[intransitive, transitive]","ex":{"en":"Who's paying?","cn":"谁付钱？"}},{"en":"to give somebody money that you owe them","cn":"交纳；偿还","g":"[transitive]","ex":{"en":"to pay a fee/bill/fine/debt","cn":"支付费用／账单／罚款；偿还债务"}},{"en":"to give or provide a particular amount of money for the work that somebody does","cn":"支付薪资","g":"[intransitive, transitive]","ex":{"en":"Software firms generally pay well (= pay high salaries).","cn":"软件公司的工资通常很高。"}},{"en":"used with some nouns to show that you are giving or doing the thing mentioned","cn":"（与某些名词连用，表示给予某些东西或做某事）","g":"[transitive]","ex":{"en":"Most of the students weren't paying attention.","cn":"大多数学生没有注意。"}},{"en":"to produce a profit; to result in some advantage for somebody","cn":"赢利；有利","g":"[intransitive, transitive]","ex":{"en":"It's hard to make farming pay.","cn":"种庄稼获利很不容易。"}},{"en":"to suffer or be punished for your beliefs or actions","cn":"付代价；遭受惩罚","g":"[intransitive]","ex":{"en":"You'll pay for that remark!","cn":"你会为你的话付出代价的！"}},{"en":"the money that somebody gets for doing regular work","cn":"工资；薪水","lab":"British English","ex":{"en":"Her job is hard work, but the pay is good.","cn":"她工作虽辛苦，但薪水不低。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"付；支付；偿还","en":"When you pay an amount of money to someone, you give it to them because you are buying something from them or because you owe it to them. When you pay something such as a bill or a debt, you pay the amount that you owe.","ex":{"en":"Accommodation is free — all you pay for is breakfast and dinner","cn":"住宿免费——你只需付早餐和正餐的钱。"}},{"pos":"VERB 动词","cn":"给…付工资；给…付酬","en":"When you are paid, you get your wages or salary from your employer.","ex":{"en":"The lawyer was paid a huge salary","cn":"那位律师薪酬很高。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工资；薪水","en":"Your pay is the money that you get from your employer as wages or salary. →see usage note at:","ex":{"en":"...their complaints about their pay and conditions.","cn":"他们对薪水和工作条件的不满"}},{"pos":"VERB 动词","cn":"（为获得帮助或服务）付钱给","en":"If you are paid to do something, someone gives you some money so that you will help them or perform some service for them.","ex":{"en":"Students were paid substantial sums of money to do nothing all day but lie in bed","cn":"学生们得到了一大笔钱，而所要做的就是整天躺在床上什么也不做。"}},{"pos":"VERB 动词","cn":"（政府或机构通过提高价格、税率等使某人）为…买单","en":"If a government or organization makes someone pay for something, it makes them responsible for providing the money for it, for example by increasing prices or taxes.","ex":{"en":"...a legally binding international treaty that establishes who must pay for environmental damage","cn":"规定谁该为环境破坏买单的有法律约束力的国际条约"}},{"pos":"VERB 动词","cn":"（工作、交易或投资）有…报酬，产生…利润","en":"If a job, deal, or investment pays a particular amount, it brings you that amount of money.","ex":{"en":"We're stuck in jobs that don't pay very well","cn":"我们深陷在工资低廉的工作中。"}},{"pos":"VERB 动词","cn":"（工作、交易或投资）有收益，盈利","en":"If a job, deal, or investment pays, it brings you a profit or earns you some money.","ex":{"en":"There are some agencies now specialising in helping older people to find jobs which pay","cn":"现在有些机构专门帮助年龄较大的人找有报酬的工作。"}},{"pos":"VERB 动词","cn":"存（钱）；储蓄","en":"When you pay money into a bank account, you put the money in the account.","ex":{"en":"He paid £20 into his savings account","cn":"他往自己的储蓄账户上存了20英镑。"}},{"pos":"VERB 动词","cn":"有利；有好处；值得","en":"If a course of action pays, it results in some advantage or benefit for you.","ex":{"en":"It pays to invest in protective clothing","cn":"在防护服上投资是值得的。"}},{"pos":"VERB 动词","cn":"付出代价；受到惩罚","en":"If you pay for something that you do or have, you suffer as a result of it.","ex":{"en":"Britain was to pay dearly for its lack of resolve","cn":"英国将为缺乏决心付出惨痛的代价。"}},{"pos":"VERB 动词","cn":"（与某些名词连用，表示施予某物或做某事）进行（访问）/给予（注意）","en":"You use pay with some nouns, for example in the expressions pay a visit and pay attention, to indicate that something is given or done.","ex":{"en":"Do pay us a visit next time you're in Birmingham","cn":"下次你来伯明翰一定要来看看我们。"}},{"pos":"ADJ 形容词","cn":"（电视节目）付费的，收费的","en":"Pay television consists of programmes and channels which are not part of a public broadcasting system, and for which people have to pay.","ex":{"en":"The company has set up joint-venture pay-TV channels in Belgium, Spain, and Germany.","cn":"该公司已在比利时、西班牙和德国设立了合资付费电视频道。"}},{"pos":"PHRASE 短语","cn":"赚回成本","en":"If something that you buy or invest in pays for itself after a period of time, the money you gain from it, or save because you have it, is greater than the amount you originally spent or invested.","ex":{"en":"...investments in energy efficiency that would pay for themselves within five years.","cn":"将在5年内收回成本的能效投资"}},{"pos":"PHRASE 短语","cn":"受雇于；被…收买","en":"If you say that someone is in the pay of a certain person or group, you disapprove of the fact that they are being paid by and are working for that person or group, often secretly or illegally.","ex":{"en":"He was murdered at a presidential rally by gunmen in the pay of drug traffickers.","cn":"他在一场总统竞选集会上被毒品贩子雇用的枪手谋杀了。"}},{"pos":"PHRASE 短语","cn":"自食其力；养活自己","en":"If you pay your way, you have or earn enough money to pay for what you need, without needing other people to give or lend you money.","ex":{"en":"I went to college anyway, as a part-time student, paying my own way","cn":"总之我上了大学，半工半读，自食其力。"}},{"pos":"","cn":"","en":"→see: ; →see: ; to pay through the nose→see: ; he who pays the piper calls the tune→see: ;"},{"pos":"","cn":"","en":"相关词组：pay back pay off pay out pay up"}]},"examples":[{"en":"He looked terrible this morning. I think he's paying the penalty for all those late nights.","cn":"他今天上午脸色很不好，我想这是他一直熬夜造成的。"},{"en":"I paid good money for this jacket, and now look at it — it's ruined!","cn":"这件夹克是我花大价钱买的。瞧瞧，全给毁了！"}]},"pause":{"media":{"img":["media/pic/pause.png"],"uk":"media/uk/pause__gb_1.mp3","us":"media/us/pause__us_1.mp3"},"oxford":{"phon":"pɔːz","pos":"verb","senses":[{"en":"to stop talking or doing something for a short time before continuing","cn":"暂停；停顿","g":"[intransitive]","ex":{"en":"Anita paused for a moment, then said: ‘All right’.","cn":"安尼塔略停了一会儿，然后说：“好吧”。"}},{"en":"to stop a video, etc. for a short time using the pause button","cn":"（按暂停键）暂停播放","g":"[transitive]","ex":{"en":"She paused the movie to go and answer the door.","cn":"她把电影暂停了去应门。"}},{"en":"a period of time during which somebody stops talking or stops what they are doing","cn":"停顿；停顿的时间","g":"[countable]","ex":{"en":"There was a long pause before she answered.","cn":"她停了好一会儿才回答。"},"pos":"noun"},{"en":"a sign (͒) over a note or a rest to show that it should be longer than usual","cn":"延长记号","g":"[countable]","lab":"especially British English","pos":"noun"},{"en":"a control that allows you to stop a video, etc. for a short time","cn":"暂停键","g":"[uncountable]","ex":{"en":"Press pause to stop the film.","cn":"按暂停键停止播放电影。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"停顿；暂停","en":"If you pause while you are doing something, you stop for a short period and then continue.","ex":{"en":"'It's rather embarrassing,' he began, and paused","cn":"“非常令人难堪，”他开口道，然后停顿了一下。"}},{"pos":"N-COUNT 可数名词","cn":"停顿；暂停","en":"A pause is a short period when you stop doing something before continuing.","ex":{"en":"After a pause Alex said sharply: 'I'm sorry if I've upset you'","cn":"歇了一会儿后，亚历克斯毫不客气地说：“要是让你心烦了，那我很抱歉。”"}},{"pos":"PHRASE 短语","cn":"使认真考虑；使犹豫","en":"If something gives you pause for thought, it makes you think carefully about something, especially in a different way than you have thought about it before.","ex":{"en":"An opposition spokesman said he hoped the agreement would give them pause for thought about the futility of violence.","cn":"反对派发言人说他希望协议能够让他们仔细想想暴力行为毫无意义。"}}]},"examples":[{"en":"Anita paused for a moment, then said: ‘All right’.","cn":"安尼塔略停了一会儿，然后说：“好吧”。"},{"en":"Pausing only to pull on a sweater, he ran out of the house.","cn":"他只停下来穿了件毛衣就冲出了屋外。"}]},"passenger":{"media":{"uk":"media/uk/passenger__gb_1.mp3","us":"media/us/passenger__us_1.mp3"},"oxford":{"phon":"ˈpæsɪndʒə(r)","pos":"noun","senses":[{"en":"a person who is travelling in a car, bus, train, plane or ship and who is not driving it or working on it","cn":"乘客；旅客","ex":{"en":"airline/cruise/rail/bus passengers","cn":"航空公司／邮轮／铁路／公共汽车乘客"}},{"en":"a member of a group or team who does not do as much work as the others","cn":"白吃饭的人；闲散人员","lab":"informal, disapproving, especially British English，，，，","ex":{"en":"The firm cannot afford to carry passengers.","cn":"公司养不起白吃饭的人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乘客；旅客","en":"A passenger in a vehicle such as a bus, boat, or plane is a person who is travelling in it, but who is not driving it or working on it. →see usage note at:","ex":{"en":"Mr Fullemann was a passenger in the car when it crashed.","cn":"出车祸时，福勒曼先生正在那辆车上。"}},{"pos":"ADJ 形容词","cn":"乘客的；旅客的","en":"Passenger is used to describe something that is designed for passengers, rather than for drivers or goods.","ex":{"en":"I sat in the passenger seat.","cn":"我坐在乘客座位上。"}}]},"examples":[{"en":"The firm cannot afford to carry passengers.","cn":"公司养不起白吃饭的人。"},{"en":"a passenger train (= carrying passengers, not goods)","cn":"客运列车"}]},"pasture":{"media":{"uk":"media/uk/pasture__gb_1.mp3","us":"media/us/pasture__us_1.mp3"},"oxford":{"phon":"ˈpɑːstʃə(r)","pos":"noun","senses":[{"en":"land covered with grass that is suitable for feeding animals on","cn":"牧场；牧草地","g":"[uncountable, countable]","ex":{"en":"an area of permanent/rough/rich pasture","cn":"一片永久的／高低不平的／富饶的牧场"}},{"en":"the circumstances of your life, work, etc.","cn":"生活状况；工作条件；个人发展的机遇","g":"[plural]","lab":"British English","ex":{"en":"I felt we were off to greener pastures (= a better way of life).","cn":"我觉得我们在迈向更好的生活。"}},{"en":"to put animals in a field to feed on grass","cn":"放牧","ex":{"en":"The villagers relied on the commons for pasturing their sheep.","cn":"村民们依靠公地放牧羊群。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"牧场；牧草地","en":"Pasture is land with grass growing on it for farm animals to eat.","ex":{"en":"The cows are out now, grazing in the pasture.","cn":"牛现在已经放出去了，正在牧场上吃草。"}},{"pos":"PHRASE 短语","cn":"更好的地方（或工作、条件）；更好的前程","en":"If someone leaves for greener pastures, or in British English pastures new, they leave their job, their home, or the situation they are in for something they think will be much better.","ex":{"en":"Michael decided he wanted to move on to pastures new for financial reasons.","cn":"出于经济原因，迈克尔决意去寻找更好的前程。"}},{"pos":"PHRASE 短语","cn":"放牧","en":"If you put animals out to pasture, you move them out into the fields so they can eat the grass."},{"pos":"PHRASE 短语","cn":"让…退休；使赋闲","en":"If you say that someone is being put out to pasture, you mean they are no longer being employed because they are considered to be too old or no longer useful.","ex":{"en":"I'm retiring next month. They're putting me out to pasture.","cn":"我下个月退休。他们要我养老去了。"}}]},"examples":[{"en":"I felt we were off to greener pastures (= a better way of life).","cn":"我觉得我们在迈向更好的生活。"},{"en":"( BrE ) She decided it was time to move on to pastures new (= a new job, place to live, etc.).","cn":"她认定换个新工作的时候到了。"}]},"parsley":{"oxford":{"phon":"ˈpɑːsli","pos":"noun","senses":[{"en":"a plant with curly green leaves that are used in cooking as a herb and to decorate food","cn":"欧芹；荷兰芹","ex":{"en":"fish with parsley sauce","cn":"欧芹沙司鱼"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"欧芹；荷兰芹","en":"Parsley is a small plant with curly leaves that are used for flavouring or decorating savoury food.","ex":{"en":"...parsley sauce.","cn":"欧芹酱"}}]},"media":{"img":["media/pic/herbs_comp.jpg","media/thumb/parsley.jpg"],"uk":"media/uk/parsley__gb_1.mp3","us":"media/us/parsley__us_1.mp3"},"examples":[{"en":"fish with parsley sauce","cn":"欧芹沙司煮鱼"}]},"participle":{"oxford":{"phon":"pɑːˈtɪsɪpl","pos":"noun","senses":[{"en":"(in English) a word formed from a verb, ending in -ing (= the present participle) or -ed, -en, etc. (= the past participle)","cn":"分词（现在分词或过去分词）","ex":{"en":"The past participle of ‘buy’ is ‘bought’.","cn":"“buy”的过去分词是“bought”。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（语法中的）分词（包括过去分词和现在分词）","en":"In grammar, a participle is a form of a verb that can be used in compound tenses of the verb. There are two participles in English: the past participle, which usually ends in '-ed', and the present participle, which ends in '-ing'."}]},"media":{"uk":"media/uk/participle__gb_1.mp3","us":"media/us/participle__us_1.mp3"}},"pat":{"media":{"uk":"media/uk/pat__gb_1.mp3","us":"media/us/pat__us_1.mp3"},"oxford":{"phon":"pæt","pos":"verb","senses":[{"en":"to touch somebody/something gently several times with your hand flat, especially to show kind feelings","cn":"（喜爱地）轻拍","ex":{"en":"She patted the dog on the head.","cn":"她轻轻地拍着狗的头。"}},{"en":"a gentle friendly touch with your open hand or with a flat object","cn":"（友善的）轻拍，拍打","g":"[usually singular]","ex":{"en":"a pat on the head","cn":"轻轻拍一下头"},"pos":"noun"},{"en":"a small, soft, flat piece of butter","cn":"一小块黄油","ex":{"en":"baked potatoes with a pat of butter and a sprinkle of paprika","cn":"烤土豆加一点黄油和辣椒粉"},"pos":"noun"},{"en":"too quick, easy or simple; not seeming natural or realistic","cn":"过于简易的；不自然的；油滑的","ex":{"en":"The ending of the novel is a little too pat to be convincing.","cn":"小说的结尾有点过于简单，不能令人信服。"},"pos":"adjective"},{"en":"a first name for boys or girls, short for Patrick or Patricia","cn":"帕特（男子或女子名，Patrick 或 Patricia 缩写）","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"轻拍；轻敲","en":"If you pat something or someone, you tap them lightly, usually with your hand held flat.","ex":{"en":"'Don't you worry about any of this,' she said patting me on the knee","cn":"“这个你什么都不用担心，”她轻拍着我的膝盖说。"}},{"pos":"N-COUNT 可数名词","cn":"（黄油等的）小块","en":"A pat of butter or something else that is soft is a small lump of it."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"敷衍的；过于简单的","en":"If you say that an answer or explanation is pat, you disapprove of it because it is too simple and sounds as if it has been prepared in advance.","ex":{"en":"There's no pat answer to that","cn":"那个问题不是随随便便就能回答的。"}},{"pos":"PHRASE 短语","cn":"赞许；表扬","en":"If you give someone a pat on the back or if you pat them on the back, you show them that you think they have done well and deserve to be praised.","ex":{"en":"The players deserve a pat on the back","cn":"球员们值得表扬。"}},{"pos":"PHRASE 短语","cn":"了如指掌；完全掌握","en":"If you have an answer or explanation down pat or off pat, you have prepared and learned it so you are ready to say it at any time.","ex":{"en":"I have my story down pat","cn":"我对自己想好的说法已烂熟于心。"}},{"pos":"PHRASE 短语","cn":"固执己见","en":"If you stand pat, you refuse to change your mind about something.","ex":{"en":"On the other side, the men stood pat and were unyielding","cn":"在另一方面，那些人固执己见，不肯让步。"}}]},"examples":[{"en":"The ending of the novel is a little too pat to be convincing.","cn":"小说的结尾有点过于简单，不能令人信服。"},{"en":"He deserves a pat on the back for all his hard work.","cn":"他工作兢兢业业，值得嘉许。"}]},"passion":{"media":{"uk":"media/uk/passion__gb_1.mp3","us":"media/us/passion__us_1.mp3"},"oxford":{"phon":"ˈpæʃn","pos":"noun","senses":[{"en":"a very strong feeling of love, hate, anger, enthusiasm, etc.","cn":"强烈情感；激情","g":"[uncountable, countable]","ex":{"en":"I admire the passion and commitment shown by the players.","cn":"我敬佩球员们表现出的热情和敬业精神。"}},{"en":"a very strong feeling of liking something; a hobby, an activity, etc. that you like very much","cn":"酷爱；热衷的爱好（或活动等）","g":"[countable]","ex":{"en":"Music is his true passion.","cn":"音乐是他的真爱。"}},{"en":"a very strong feeling of sexual love","cn":"强烈的爱（尤指两性间的）","g":"[uncountable]","ex":{"en":"His passion for her made him blind to everything else.","cn":"他迷恋她，达到了不顾一切的地步。"}},{"en":"a state of being very angry","cn":"盛怒；激愤","g":"[singular]","lab":"formal","ex":{"en":"She flies into a passion if anyone even mentions his name.","cn":"哪怕是有人提到他的名字，她也会勃然大怒。"}},{"en":"the suffering and death of Jesus Christ","cn":"耶稣的受难","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"强烈的情欲；热恋","en":"Passion is strong sexual feelings towards someone.","ex":{"en":"...my passion for a dark-haired, slender boy named James.","cn":"我对一个名叫詹姆斯的黑头发高挑个儿男孩的热恋"}},{"pos":"N-UNCOUNT 不可数名词","cn":"热情；激情；强烈的感情","en":"Passion is a very strong feeling about something or a strong belief in something.","ex":{"en":"He spoke with great passion.","cn":"他发表了热情洋溢的讲话。"}},{"pos":"N-COUNT 可数名词","cn":"强烈爱好；酷爱","en":"If you have a passion for something, you have a very strong interest in it and like it very much.","ex":{"en":"She had a passion for gardening","cn":"她酷爱园艺。"}}]},"examples":[{"en":"She flies into a passion if anyone even mentions his name.","cn":"哪怕是有人提到他的名字，她也会勃然大怒。"},{"en":"She argued her case with considerable passion.","cn":"她相当激动地为自己的主张提出论据。"}]},"pan":{"oxford":{"phon":"pæn","pos":"combining form","senses":[{"en":"including all of something; connected with the whole of something","cn":"包含一切的；全部的；泛","ex":{"en":"pan-African","cn":"泛非洲的"}},{"en":"a container, usually made of metal, with a handle or handles, used for cooking food in","cn":"平锅；平底锅","ex":{"en":"pots and pans","cn":"锅碗瓢盆"},"pos":"noun"},{"en":"the amount contained in a pan","cn":"一锅的量","ex":{"en":"a pan of boiling water","cn":"一锅开水"},"pos":"noun"},{"en":"a metal container used for cooking food in","cn":"（烘煮食物用的）烤盘，烤模","lab":"North American English","ex":{"en":"a cake pan","cn":"蛋糕烤盘"},"pos":"noun"},{"en":"either of the dishes on a pair of scales that you put things into in order to weigh them","cn":"（天平的）秤盘","pos":"noun"},{"en":"the bowl of a toilet","cn":"马桶","lab":"British English","pos":"noun"},{"en":"to severely criticize something such as a play or a film","cn":"严厉批评，抨击（戏剧、电影等）","g":"[transitive, usually passive]","lab":"informal","ex":{"en":"The television series was panned by critics and viewers alike.","cn":"这部电视连续剧受到评论家和观众的一致恶评。"},"pos":"verb"},{"en":"if a television or video camera pans somewhere, or a person pans or pans a camera, the camera moves in a particular direction, to follow an object or to film a wide area","cn":"（移动摄像机）追拍，摇摄","g":"[intransitive, transitive]","ex":{"en":"The camera panned back to the audience.","cn":"摄像机摇回拍摄观众。"},"pos":"verb"},{"en":"to wash soil or small stones in a pan to find gold or other valuable minerals","cn":"（用淘选盘）淘洗；淘（金）","g":"[intransitive, transitive]","ex":{"en":"panning for gold","cn":"淘金"},"pos":"verb"},{"en":"a betel leaf, usually folded into a shape with three sides and filled with spices (= types of powder or seed that come from plants and have a strong taste and smell) for eating","cn":"蒌叶，蒟酱叶包槟榔，包叶槟榔 （通常折成粽子状食用）","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"平底锅","en":"A pan is a round metal container with a long handle, which is used for cooking things in, usually on top of a cooker or stove.","ex":{"en":"Heat the butter and oil in a large pan.","cn":"把黄油和食用油放到大平底锅里加热。"}},{"pos":"N-COUNT 可数名词","cn":"烤盘","en":"A pan is a shallow metal container used for baking foods."},{"pos":"VERB 动词","cn":"抨击，严厉批评（影片、书籍等）","en":"If something such as a film or a book is panned by journalists, they say it is very bad.","ex":{"en":"His first high-budget movie, called 'Brain Donors', was panned by the critics.","cn":"他的第一部高成本制作电影《撞板三舞男》遭到恶评。"}},{"pos":"V-ERG 及物/不及物动词","cn":"移动拍摄；摇摄","en":"If you pan a film or television camera or if it pans somewhere, it moves slowly round so that a wide area is filmed.","ex":{"en":"The camera panned along the line of players","cn":"摄像机沿着那排选手移动拍摄。"}},{"pos":"VERB 动词","cn":"用淘选盘淘（金）","en":"If someone pans for gold, they use a shallow metal container to try to find small pieces of gold from a river.","ex":{"en":"People came westward in the 1800s to pan for gold","cn":"在19世纪，人们前往西部淘金。"}},{"pos":"","cn":"","en":"相关词组：pan out"}]},"media":{"uk":"media/uk/pan__1_gb_1.mp3","us":"media/us/pan__us_1.mp3","img":["media/ldoce/img/saucepan.jpg"]},"examples":[{"en":"He panned the camera along the row of faces.","cn":"他移动摄像机顺着这一排面孔拍摄。"},{"en":"I'm happy with the way things have panned out.","cn":"我对事情的结果感到很满意。"}]},"parents":{"oxford":{"phon":"ˈpeərənt","pos":"noun","senses":[{"en":"a person's father or mother","cn":"父亲；母亲"},{"en":"an animal or a plant which produces other animals or plants （","cn":"动、植物的）亲本，亲代，父本，母本"}]}},"pace":{"media":{"uk":"media/uk/pace__gb_1.mp3","us":"media/us/pace__us_1.mp3"},"oxford":{"phon":"peɪs","pos":"","senses":[{"en":"Police and Criminal Evidence Act","cn":"警察和刑事证据法"},{"en":"the speed at which somebody/something walks, runs or moves","cn":"（移动的）速度；步速","g":"[singular, uncountable]","ex":{"en":"to set off at a steady/gentle/leisurely pace","cn":"以稳定的／徐缓的／悠闲的步子出发"},"pos":"noun"},{"en":"the speed at which something happens","cn":"发生的速度；步伐；节奏","g":"[singular, uncountable]","ex":{"en":"It is difficult to keep up with the rapid pace of change.","cn":"跟上快速的变化是很困难的。"},"pos":"noun"},{"en":"an act of stepping once when walking or running; the distance travelled when doing this","cn":"（走或跑时）迈出的一步，一步的距离；步幅","g":"[countable]","ex":{"en":"She took two paces forward.","cn":"她向前走了两步。"},"pos":"noun"},{"en":"the fact of something happening, changing, etc. quickly","cn":"迅速出现（或变化等）；快节奏","g":"[uncountable]","ex":{"en":"He gave up his job in advertising because he couldn't stand the pace.","cn":"他辞去了广告业的工作，因为他承受不了那种快节奏。"},"pos":"noun"},{"en":"to walk up and down in a small area many times, especially because you are feeling nervous or angry","cn":"来回踱步；走来走去","g":"[intransitive, transitive]","ex":{"en":"She paced up and down outside the room.","cn":"她在屋子外面来回走着。"},"pos":"verb"},{"en":"to set the speed at which something happens or develops","cn":"确定速度；调整节奏","g":"[transitive]","ex":{"en":"He paced his game skilfully.","cn":"他巧妙地控制着自己的比赛节奏。"},"pos":"verb"},{"en":"to find the right speed or rhythm for your work or an activity so that you have enough energy to do what you have to do","cn":"调整自己的工作（或活动）节奏","g":"[transitive]","ex":{"en":"He'll have to learn to pace himself in this job.","cn":"他必须学会使自己适应这项工作的节奏。"},"pos":"verb"},{"en":"used before a person’s name to politely disagree with what they have said","cn":"（用于人名前，委婉提出不同意见）请…原谅","ex":{"en":"The evidence suggests, pace Professor Jones, that… (= Professor Jones has a different opinion).","cn":"请琼斯教授原谅，证据表明…"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"速度；节奏","en":"The pace of something is the speed at which it happens or is done.","ex":{"en":"Many people were not satisfied with the pace of change.","cn":"很多人对变革的步伐不满意。"}},{"pos":"N-SING 单数名词","cn":"步速","en":"Your pace is the speed at which you walk.","ex":{"en":"He moved at a brisk pace down the rue St Antoine","cn":"他沿着圣安托万街轻快地走去。"}},{"pos":"N-COUNT 可数名词","cn":"步幅","en":"A pace is the distance that you move when you take one step.","ex":{"en":"He'd only gone a few paces before he stopped again","cn":"他只走了几步远就又停了下来。"}},{"pos":"VERB 动词","cn":"（由于焦虑或不耐烦而）在…踱步","en":"If you pace a small area, you keep walking up and down it, because you are anxious or impatient.","ex":{"en":"As they waited, Kravis paced the room nervously","cn":"他们等的时候，克拉维斯在屋里不安地踱来踱去。"}},{"pos":"VERB 动词","cn":"放稳步调","en":"If you pace yourself when doing something, you do it at a steady rate.","ex":{"en":"It was a tough race and I had to pace myself.","cn":"这是场艰苦的比赛，我不得不控制好节奏。"}},{"pos":"PHRASE 短语","cn":"与…步调一致","en":"If something keeps pace with something else that is changing, it changes quickly in response to it.","ex":{"en":"Farmers are angry because the rise fails to keep pace with inflation.","cn":"农民们很气愤，因为提价赶不上通货膨胀。"}},{"pos":"PHRASE 短语","cn":"与…齐头并进（或并驾齐驱）","en":"If you keep pace with someone who is walking or running, you succeed in going as fast as them, so that you remain close to them.","ex":{"en":"With four laps to go, he kept pace with the leaders","cn":"还剩4圈的时候，他紧紧咬住领先者。"}},{"pos":"PHRASE 短语","cn":"以适合自己的节奏","en":"If you do something at your own pace , you do it at a speed that is comfortable for you.","ex":{"en":"The computer will give students the opportunity to learn at their own pace","cn":"计算机让学生们有机会按照自己的节奏学习。"}},{"pos":"PHRASE 短语","cn":"考查…的能力/ 展现…的才能","en":"If you put someone through their paces or make them go through their paces, you get them to show you how well they can do something.","ex":{"en":"The British coach is putting the boxers through their paces","cn":"英国教练正在检验拳手们的能力。"}},{"pos":"","cn":"","en":"at a snail's pace→see: ;"},{"pos":"","cn":"","en":"相关词组：pace out"}]},"examples":[{"en":"He gave up his job in advertising because he couldn't stand the pace.","cn":"他辞去了广告业的工作，因为他承受不了那种快节奏。"},{"en":"Congestion frequently reduces traffic to walking pace.","cn":"交通阻塞经常把车流的速度降低得如步行一般缓慢。"}]},"payout":{"media":{"uk":"media/uk/payout__gb_1.mp3","us":"media/us/payout__us_1.mp3"},"oxford":{"phon":"ˈpeɪaʊt","pos":"noun","senses":[{"en":"a large amount of money that is given to somebody","cn":"付出的巨款","ex":{"en":"an insurance payout","cn":"巨额保险偿付"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"支付款；（尤指）大笔付款，大额支出","en":"A payout is a sum of money, especially a large one, that is paid to someone, for example by an insurance company or as a prize.","ex":{"en":"And there's time to win more, with a £10,000 payout still to play for over the next few days.","cn":"还有时间多赢些，后面几天还有一笔1万英镑的奖金。"}}]},"examples":[{"en":"an insurance payout","cn":"巨额保险偿付"},{"en":"a lottery payout","cn":"彩票大额奖金"}]},"patient":{"media":{"uk":"media/uk/patient__gb_1.mp3","us":"media/us/patient__us_1.mp3"},"oxford":{"phon":"ˈpeɪʃnt","pos":"noun","senses":[{"en":"a person who is receiving medical treatment, especially in a hospital","cn":"接受治疗者，病人（尤指医院里的）","ex":{"en":"cancer/AIDS/heart patients","cn":"癌症／艾滋病／心脏病患者"}},{"en":"a person who receives treatment from a particular doctor, dentist, etc.","cn":"（某个医生或牙医等的）病人","ex":{"en":"He's one of Dr Shaw's patients.","cn":"他是肖医生的病人之一。"}},{"en":"the person or thing that is affected by the action of the verb. In the sentence ‘I started the car’, the patient is car.","cn":"受动者","lab":"grammar"},{"en":"able to wait for a long time or accept annoying behaviour or difficulties without becoming angry","cn":"有耐心的；能忍耐的","ex":{"en":"You'll just have to be patient and wait till I'm finished.","cn":"你只能耐心点儿，等我把事情做完。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"患者；病人","en":"A patient is a person who is receiving medical treatment from a doctor or hospital. A patient is also someone who is registered with a particular doctor. →see usage note at:","ex":{"en":"The earlier the treatment is given, the better the patient's chances","cn":"病人越早接受治疗，康复的可能性就越大。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能忍耐的；有耐心的","en":"If you are patient, you stay calm and do not get annoyed, for example when something takes a long time, or when someone is not doing what you want them to do.","ex":{"en":"Please be patient — your cheque will arrive","cn":"请耐心点——你的支票会来的。"}}]},"examples":[{"en":"You'll just have to be patient and wait till I'm finished.","cn":"你只能耐心点，等我把事情做完。"},{"en":"She sat patiently waiting for her turn.","cn":"她耐心地坐着等候轮到自己。"}]},"pale":{"media":{"uk":"media/uk/pale__gb_1.mp3","us":"media/us/pale__us_1.mp3"},"oxford":{"phon":"peɪl","pos":"adjective","senses":[{"en":"having skin that is very light in colour; having skin that has less colour than usual because of illness, a strong emotion, etc.","cn":"灰白的；苍白的","ex":{"en":"a pale complexion","cn":"惨白的面容"}},{"en":"light in colour; containing a lot of white","cn":"浅色的；淡色的","ex":{"en":"pale blue eyes","cn":"淡蓝色的眼睛"}},{"en":"not strong or bright","cn":"暗淡的；微弱的","ex":{"en":"the cold pale light of dawn","cn":"破晓时分的鱼白寒光"}},{"en":"to become paler than usual","cn":"变得比平常白；变苍白","ex":{"en":"She (= her face) paled visibly at the sight of the police car.","cn":"她一看见警车，脸色就刷地变白了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"浅色的；灰白的","en":"If something is pale, it is very light in colour or almost white.","ex":{"en":"Migrating birds filled the pale sky","cn":"灰白的天空中满是迁徙的飞鸟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（脸色）苍白的","en":"If someone looks pale, their face looks a lighter colour than usual, usually because they are ill, frightened, or shocked.","ex":{"en":"She looked pale and tired","cn":"她看起来脸色苍白憔悴。"}},{"pos":"VERB 动词","cn":"显得逊色；相形失色","en":"If one thing pales in comparison with another, it is made to seem much less important, serious, or good by it.","ex":{"en":"When someone you love has a life-threatening illness, everything else pales in comparison.","cn":"你爱的人得了致命疾病时，其他一切事情都显得不那么重要了。"}},{"pos":"PHRASE 短语","cn":"（行为举止）出格的，越轨的","en":"If you think that someone's actions or behaviour are not acceptable, you can say that they are beyond the pale.","ex":{"en":"This sort of thing really is quite beyond the pale.","cn":"这种事情真是不可接受。"}}]},"examples":[{"en":"Last year's riots pale in comparison with this latest outburst of violence.","cn":"去年的骚乱与最近这次暴乱相比，可说是小巫见大巫。"},{"en":"She (= her face) paled visibly at the sight of the police car.","cn":"她一看见警车，脸色就刷地变白了。"}]},"parlors":{"oxford":{"phon":"ˈpɑːlə(r)","pos":"noun","senses":[{"en":"( old-fashioned ) a room in a private house for sitting in, entertaining visitors, etc. （","cn":"私人住房的）起居室，客厅"},{"en":"( in compounds","cn":"构成复合词 ) ( especially NAmE ) a shop/store that provides particular goods or services （专营某种商品或业务的）店铺"}]}},"pandemic":{"oxford":{"phon":"pænˈdemɪk","pos":"noun","senses":[{"en":"a disease that spreads over a whole country or the whole world","cn":"（全国或全球性）流行病；大流行病","ex":{"en":"the coronavirus pandemic","cn":"冠状病毒大流行"}},{"en":"that spreads over a whole country or the whole world","cn":"（全国或全球性）流行病；大流行病","ex":{"en":"a pandemic disease","cn":"大范围流行的疾病"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（疾病的）大流行，广泛传播","en":"A pandemic is an occurrence of a disease that affects many people over a very wide area.","ex":{"en":"They feared a new cholera pandemic","cn":"他们担心新一轮的霍乱大流行。"}}]},"media":{"uk":"media/uk/pandemic__gb_1.mp3","us":"media/us/pandemic__us_1.mp3"},"examples":[{"en":"a pandemic disease","cn":"大范围流行的疾病"},{"en":"the AIDS pandemic","cn":"艾滋病瘟疫"}]},"patriotism":{"oxford":{"phon":"ˈpætriətɪzəm","pos":"noun","senses":[{"en":"love of your country and the desire to defend it","cn":"爱国主义；爱国精神","ex":{"en":"a wave of patriotism","cn":"爱国主义浪潮"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"爱国主义；爱国精神","en":"Patriotism is love for your country and loyalty towards it.","ex":{"en":"He was a country boy who had joined the army out of a sense of patriotism and adventure","cn":"他是个乡下小伙儿，参军是出于爱国之心和冒险精神。"}}]},"media":{"uk":"media/uk/patriotism__gb_1.mp3","us":"media/us/patriotism__us_1.mp3"},"examples":[{"en":"I’m not very patriotic.","cn":""}]},"pains":{"media":{"uk":"media/uk/pains__gb_1.mp3","us":"media/us/pains__us_1.mp3"},"oxford":{"phon":"peɪnz","pos":"noun","senses":[{"en":"to put a lot of effort into doing sth correctly","cn":"下苦功；花大力气"},{"en":"( especially BrE ) ( often ironic ) as payment, reward or thanks for sth you have done","cn":"作为回报；作为答谢"}]},"examples":[{"en":"I told her what I thought and got a mouthful of abuse for my pains!","cn":"我跟她讲了我的感受，而得到的回报竟是破口大骂！"},{"en":"The couple went to great pains to keep their plans secret.","cn":"这对夫妇煞费苦心，对计划守口如瓶。"}]},"parties":{"oxford":{"phon":"ˈpɑːti","pos":"noun","senses":[{"en":"a political organization that you can vote for in elections and whose members have the same aims and ideas","cn":"政党；党派"},{"en":"( especially in compounds","cn":"尤用于构成复合词 ) a social occasion, often in a person's home, at which people eat, drink, talk, dance and enjoy themselves 聚会；"}]}},"passages":{"oxford":{"phon":"ˈpæsɪdʒ","pos":"noun","senses":[{"en":"a long narrow area with walls on either side that connects one room or place with another","cn":"通道；走廊"},{"en":"a tube in the body through which air, liquid, etc. passes （","cn":"体内通气、输液等的）管路，通道"}]}},"painters":{"oxford":{"phon":"ˈpeɪntə(r)","pos":"noun","senses":[{"en":"a person whose job is painting buildings, walls, etc.","cn":"油漆匠"},{"en":"an artist who paints pictures","cn":"画家"}]}},"paintings":{"oxford":{"phon":"ˈpeɪntɪŋ","pos":"noun","senses":[{"en":"a picture that has been painted","cn":"绘画；油画"},{"en":"the act or art of using paint to produce pictures","cn":"作画；绘画"}]}},"patches":{"oxford":{"phon":"pætʃ","pos":"noun","senses":[{"en":"a small area of sth, especially one which is different from the area around it","cn":"色斑；斑点；（与周围不同的）小块，小片"},{"en":"a small piece of material that is used to cover a hole in sth or to make a weak area stronger, or as decoration","cn":"补丁；补块"}]}},"passed":{"oxford":{"phon":"pɑːs","pos":"verb","senses":[{"en":"to move past or to the other side of sb/sth","cn":"通过；走过"},{"en":"to go or move in the direction mentioned","cn":"沿某方向前进；向某方向移动"}]}},"painted":{"oxford":{"phon":"peɪnt","pos":"noun","senses":[{"en":"a liquid that is put on surfaces to give them a particular colour; a layer of this liquid when it has dried on a surface","cn":"油漆；油漆涂层"},{"en":"tubes or blocks of paint used for painting pictures","cn":"绘画颜料"}]}},"pastoralists":{"oxford":{"phon":"ˈpɑːstərəlɪzəm","pos":"noun","senses":[{"en":"a way of keeping animals such as cattle , sheep, etc. that involves moving them from place to place to find water and food","cn":"游牧（牧者带着牲口逐水草而居）"}]}},"patterns":{"oxford":{"phon":"ˈpætn","pos":"noun","senses":[{"en":"the regular way in which sth happens or is done","cn":"模式；方式"},{"en":"an excellent example to copy","cn":"范例；典范；榜样；样板"}]}},"parts":{"oxford":{"phon":"pɑːt","pos":"noun","senses":[{"en":"some but not all of a thing","cn":"部分"},{"en":"a section, piece or feature of sth","cn":"片段；部分；一点"}]}},"parlor":{"oxford":{"phon":"ˈpɑːlə(r)","pos":"noun","senses":[{"en":"( old-fashioned ) a room in a private house for sitting in, entertaining visitors, etc. （","cn":"私人住房的）起居室，客厅"},{"en":"( in compounds","cn":"构成复合词 ) ( especially NAmE ) a shop/store that provides particular goods or services （专营某种商品或业务的）店铺"}]}},"paddocks":{"oxford":{"phon":"ˈpædək","pos":"noun","senses":[{"en":"a small field in which horses are kept （","cn":"牧马的）小围场"},{"en":"an area where horses or cars are taken before a race and shown to the public","cn":"检阅场"}]}},"papered":{"oxford":{"phon":"ˈpeɪpə(r)","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) the thin material that you write and draw on and that is also used for wrapping and packing things 纸；纸张"},{"en":"a newspaper","cn":"报纸"}]}},"paying":{"oxford":{"phon":"peɪ","pos":"verb","senses":[{"en":"to give sb money for work, goods, services, etc.","cn":"付费；付酬"},{"en":"to give sb money that you owe them","cn":"交纳；偿还"}]}},"parks":{"oxford":{"phon":"pɑːk","pos":"noun","senses":[{"en":"an area of public land in a town or a city where people go to walk, play and relax","cn":"公园"},{"en":"( in compounds","cn":"构成复合词 ) an area of land used for a particular purpose 专用区；园区"}]}},"parallels":{"oxford":{"phon":"ˈpærəlel","pos":"adjective","senses":[{"en":"two or more lines that are parallel to each other are the same distance apart at every point","cn":"平行的"},{"en":"very similar or taking place at the same time","cn":"极相似的；同时发生的；相应的；对应的"}]}},"passes":{"oxford":{"phon":"pɑːs","pos":"verb","senses":[{"en":"to move past or to the other side of sb/sth","cn":"通过；走过"},{"en":"to go or move in the direction mentioned","cn":"沿某方向前进；向某方向移动"}]}},"parked":{"oxford":{"phon":"pɑːk","pos":"noun","senses":[{"en":"an area of public land in a town or a city where people go to walk, play and relax","cn":"公园"},{"en":"( in compounds","cn":"构成复合词 ) an area of land used for a particular purpose 专用区；园区"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"停好车的","en":"If you are parked somewhere, you have parked your car there.","ex":{"en":"My sister was parked down the road","cn":"我妹妹把车停在马路那头。"}}]}},"packets":{"oxford":{"phon":"ˈpækɪt","pos":"noun","senses":[{"en":"( BrE ) a small paper or cardboard container in which goods are packed for selling （","cn":"商品的）小包装纸袋，小硬纸板盒"},{"en":"a small object wrapped in paper or put into a thick envelope so that it can be sent by mail, carried easily or given as a present （","cn":"邮政）小件包裹"}]}},"pairs":{"oxford":{"phon":"peə(r)","pos":"noun","senses":[{"en":"two things of the same type, especially when they are used or worn together","cn":"一双；一对"},{"en":"an object consisting of two parts that are joined together","cn":"分两个相连接部分的物体"}]}},"paths":{"oxford":{"phon":"pɑːθ","pos":"noun","senses":[{"en":"a way or track that is built or is made by the action of people walking","cn":"小路；小径"},{"en":"a line along which sb/sth moves; the space in front of sb/sth as they move","cn":"路线；道路"}]}},"parisian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"巴黎的","en":"Parisian means belonging or relating to Paris.","ex":{"en":"...a Parisian restaurant.","cn":"巴黎餐馆"}},{"pos":"N-COUNT 可数名词","cn":"巴黎人","en":"A Parisian is a person who comes from Paris."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41parisian.mp3","us":"media/ldoce/hwd/ame/f/ld42parisian.mp3"}},"passengers":{"oxford":{"phon":"ˈpæsɪndʒə(r)","pos":"noun","senses":[{"en":"a person who is travelling in a car, bus, train, plane or ship and who is not driving it or working on it","cn":"乘客；旅客"},{"en":"( informal, disapproving ) ( especially BrE ) a member of a group or team who does not do as much work as the others","cn":"白吃饭的人；闲散人员"}]}},"paused":{"oxford":{"phon":"pɔːz","pos":"verb","senses":[{"en":"to stop talking or doing sth for a short time before continuing","cn":"暂停；停顿"},{"en":"to stop a tape, CD, etc. for a short time using the pause button （","cn":"按暂停键）暂停放音，暂停放像"}]}},"partnerships":{"oxford":{"phon":"ˈpɑːtnəʃɪp","pos":"noun","senses":[{"en":"the state of being a partner in business","cn":"伙伴关系；合伙人身分"},{"en":"a relationship between two people, organizations, etc; the state of having this relationship","cn":"合作关系；合作"}]}},"pastures":{"oxford":{"phon":"ˈpɑːstʃə(r)","pos":"noun","senses":[{"en":"land covered with grass that is suitable for feeding animals on","cn":"牧场；牧草地"},{"en":"the circumstances of your life, work, etc.","cn":"生活状况；工作条件；个人发展的机遇"}]}},"parameters":{"oxford":{"phon":"pəˈræmɪtə(r)","pos":"noun","senses":[{"en":"something that decides or limits the way in which sth can be done","cn":"决定因素；规范；范围"}]}},"paragraphs":{"oxford":{"phon":"ˈpærəɡrɑːf","pos":"noun","senses":[{"en":"a section of a piece of writing, usually consisting of several sentences dealing with a single subject. The first sentence of a paragraph starts on a new line.","cn":"段；段落"}]}},"pampered":{"oxford":{"phon":"ˈpæmpə(r)","pos":"verb","senses":[{"en":"( sometimes disapproving ) to take care of sb very well and make them feel as comfortable as possible","cn":"细心照顾；精心护理；娇惯；纵容"}]}},"payoff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"优势；收益；收效；回报","en":"The payoff from an action is the advantage or benefit that you get from it.","ex":{"en":"If such materials became generally available to the optics industry the payoffs from such a breakthrough would be enormous","cn":"如果这些材料能够普遍用于光学产业，那么这一突破带来的收益将非常巨大。"}},{"pos":"N-COUNT 可数名词","cn":"（用于避免麻烦的）封口费，贿赂","en":"A payoff is a payment which is made to someone, often secretly or illegally, so that they will not cause trouble.","ex":{"en":"Soldiers in both countries supplement their incomes with payoffs from drugs exporters.","cn":"两国士兵都用毒品走私贩的贿赂来贴补收入。"}},{"pos":"N-COUNT 可数名词","cn":"解约金；遣散费","en":"A payoff is a large payment made to someone by their employer when the person has been forced to leave their job.","ex":{"en":"The ousted chairman received a £1.5 million payoff from the loss-making oil company.","cn":"被解职的主席从亏损的石油公司那里拿到了150万英镑的解约金。"}}]},"media":{"uk":"media/ldoce/hwd/bre/a/payoff0205.mp3","us":"media/ldoce/hwd/ame/b/payoff.mp3"},"examples":[{"en":"With electric cars there is a big environmental payoff.","cn":"使用电动汽车﹐环境会大有改善。"},{"en":"Union leaders allegedly received huge payoffs from the company’s bosses.","cn":"据说工会领导收受了那家公司老板的巨额贿赂。"}]},"pals":{"oxford":{"phon":"pæl","pos":"noun","senses":[{"en":"( informal, becoming old-fashioned ) a friend","cn":"朋友；伙伴；哥们儿"},{"en":"( informal ) used to address a man in an unfriendly way （","cn":"对男子的不友好的称呼）家伙，小子"}]}},"pages":{"oxford":{"phon":"peɪdʒ","pos":"noun","senses":[{"en":"one side or both sides of a sheet of paper in a book, magazine, etc. （","cn":"书刊或纸张的）页，面，张，版"},{"en":"a section of data or information that can be shown on a computer screen at any one time （","cn":"计算机的）页面，版面"}]}},"panted":{"oxford":{"phon":"pænt","pos":"verb","senses":[{"en":"to breathe quickly with short breaths, usually with your mouth open, because you have been doing some physical exercise, or because it is very hot","cn":"气喘；喘息"},{"en":"to want sth/sb very much","cn":"渴望"}]}},"pasted":{"oxford":{"phon":"peɪst","pos":"noun","senses":[{"en":"a soft wet mixture, usually made of a powder and a liquid","cn":"面团"},{"en":"( especially in compounds","cn":"尤用于构成复合词 ) a smooth mixture of crushed meat, fish, etc. that is spread on bread or used in cooking 肉（或鱼等）酱（作涂抹料或烹饪用）"}]}},"pats":{"oxford":{"phon":"pæt","pos":"verb","senses":[{"en":"to touch sb/sth gently several times with your hand flat, especially as a sign of affection （","cn":"喜爱地）轻拍"},{"en":"( informal ) to praise sb or yourself for doing sth well","cn":"表扬，称赞（某人或自己）"}]}},"papers":{"oxford":{"phon":"ˈpeɪpə(r)","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) the thin material that you write and draw on and that is also used for wrapping and packing things 纸；纸张"},{"en":"a newspaper","cn":"报纸"}]}},"pakistani":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"巴基斯坦的；巴基斯坦人的；巴基斯坦文化的","en":"Pakistani means belonging or relating to Pakistan, or to its people or culture.","ex":{"en":"...the Pakistani city of Hyderabad.","cn":"巴基斯坦城市海得拉巴"}},{"pos":"N-COUNT 可数名词","cn":"巴基斯坦人；巴基斯坦裔人","en":"A Pakistani is a Pakistani citizen, or a person of Pakistani origin."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld42pakistani.mp3","us":"media/ldoce/hwd/ame/b/laadpakistani.mp3"},"examples":[{"en":"a 20-year-old Pakistani","cn":"一个20岁的巴基斯坦人"}],"oxford":{"phon":"ˌpɑːkɪˈstɑːni","pos":"noun, adjective","senses":[{"en":"(a person) from Pakistan","cn":"巴基斯坦人；巴基斯坦的；巴基斯坦人的"}]}},"pant":{"collins":{"senses":[{"pos":"VERB 动词","cn":"喘气；喘息","en":"If you pant, you breathe quickly and loudly with your mouth open, because you have been doing something energetic.","ex":{"en":"She climbed rapidly until she was panting with the effort.","cn":"她爬得很快，结果累得气喘吁吁。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again","cn":""},{"en":"to breathe out slowly and make a noise that shows you are disappointed, tired, relieved etc","cn":""},{"en":"to breathe quickly and noisily through your mouth, because you have been using a lot of effort","cn":""}]},"collocations":{"phrases":["ADV. breathlessly | heavily, loudly | slightly","PREP. for He was panting for breath. | with She was panting with the effort of carrying the suitcase.","PHRASES puff and pant Mason puffed and panted up the stairs."]},"media":{"uk":"media/ldoce/hwd/bre/a/pant0205.mp3","us":"media/ldoce/hwd/ame/f/pant1.mp3"},"examples":[{"en":"He found her panting for breath at the top of the hill.","cn":"上到山顶他发现她上气不接下气。"},{"en":"The end of the novel leaves you panting for more.","cn":"小说的结尾让人感到意犹未尽。"}],"oxford":{"phon":"pænt","pos":"verb","senses":[{"en":"to breathe quickly with short breaths, usually with your mouth open, because you have been doing some physical exercise, or because it is very hot","cn":"气喘；喘息","ex":{"en":"She finished the race panting heavily.","cn":"她跑完比赛气喘吁吁的。"}},{"en":"one of a series of quick, short breaths, usually taken with your mouth open, because you have been doing some physical exercise, or because it is very hot","cn":"气喘；喘息","ex":{"en":"His breath came in short pants.","cn":"他气息急促。"},"pos":"noun"}]}},"pancake":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"薄烤饼；薄煎饼 flat as a pancake","en":"A pancake is a thin, flat, circular piece of cooked batter made from milk, flour, and eggs. Pancakes are often rolled up or folded and eaten hot with a sweet or savoury filling inside. In America, pancakes are usually eaten for breakfast, with butter and maple syrup. →see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat round cake made from flour, milk, and eggs, that has been cooked in a flat pan and is eaten hot","cn":"薄煎[烤﹐烙]饼"},{"en":"very thick make-up for your face, that is worn especially by actors 〔","cn":"尤为演员化妆用的〕粉底，粉饼"}]},"collocations":{"phrases":["ADJ. savoury","VERB + PANCAKE make | toss"]},"media":{"img":["media/ldoce/img/pancakes.jpg"],"uk":"media/ldoce/hwd/bre/c/brelasdepancake.mp3","us":"media/ldoce/hwd/ame/5/pancake.mp3"},"oxford":{"phon":"ˈpænkeɪk","pos":"noun","senses":[{"en":"a thin flat round cake made from a mixture of flour, eggs and milk that is fried on both sides, usually eaten hot for breakfast in the US, and in the UK either as a dessert with sugar, jam, etc. or as a main course with meat, cheese, etc.","cn":"烙饼；薄饼","g":"[countable]","ex":{"en":"pancakes with maple syrup","cn":"槭糖浆薄饼"}},{"en":"thick make-up for the face, used especially in the theatre","cn":"（尤指舞台化妆用的）粉饼","g":"[uncountable]"}]}},"panel":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（进行公开讨论或作决策的）专门小组","en":"A panel is a small group of people who are chosen to do something, for example to discuss something in public or to make a decision.","ex":{"en":"He assembled a panel of scholars to advise him","cn":"他组织了一个学者小组为他出谋划策。"}},{"pos":"N-COUNT 可数名词","cn":"（门等的）镶板，嵌板","en":"A panel is a flat rectangular piece of wood or other material that forms part of a larger object such as a door.","ex":{"en":"...the frosted glass panel set in the centre of the door.","cn":"门中间镶嵌的磨砂玻璃板"}},{"pos":"N-COUNT 可数名词","cn":"（机器、设备等的）仪表板，面板","en":"A control panel or instrument panel is a board or surface which contains switches and controls to operate a machine or piece of equipment.","ex":{"en":"The equipment was extremely sophisticated and was monitored from a central control-panel","cn":"这台设备极为复杂，由中央控制面板进行监控。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people who work together to do a job","cn":""},{"en":"the people who work together on a ship or plane","cn":""},{"en":"a small group of people in an organization who have been chosen to make official decisions","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n 4 n","senses":[{"en":"If you are participating in some kind of contest, it is not ethical to bribe the judges on the panel with brownies. On the other hand, don’t stick your tongue out at them either, since they’ll be determining the winner."}]},"collocations":{"phrases":["ADJ. distinguished a distinguished panel of academics | independent | international | advisory, interview, interviewing, judging, review, se","VERB + PANEL convene, select, set up | chair","PANEL + VERB be drawn from sb/sth a panel of scientists drawn from universities","PANEL + NOUN member | interview | discussion | game The comedian will chair a new TV panel game.","PREP. on a/the ~ The head of department serves on the advisory panel. | ~ on an independent panel on takeovers and mergers","PHRASES a member of a panel, a panel of experts/judges The winners were chosen by a panel of judges. 2 part of a door, wall, etc.","ADJ. ceiling, door, wall | sliding","VERB + PANEL fit, insert, put in | remove, take out 3 section of vehicle body"]},"media":{"uk":"media/ldoce/hwd/bre/5/panel0205.mp3","us":"media/ldoce/hwd/ame/d/panel1.mp3"},"examples":[{"en":"The trousers have double thickness knee panels for extra protection.","cn":"这条裤子上有双倍厚的护膝片以加强保护。"},{"en":"We have two politicians on tonight's panel.","cn":"今天晚上出席座谈会的有两位政界人士。"}],"oxford":{"phon":"ˈpænl","pos":"noun","senses":[{"en":"a square or rectangular piece of wood, glass or metal that forms part of a larger surface such as a door or wall","cn":"（门、墙等上面的）嵌板，镶板，方格板块","g":"[countable]","ex":{"en":"One of the glass panels in the front door was cracked.","cn":"前门的一块方玻璃破裂了。"}},{"en":"a flat board in a vehicle or on a machine where the controls and instruments are fixed","cn":"（汽车或其他机械的）控制板，仪表盘","g":"[countable]","ex":{"en":"an instrument/a display panel","cn":"仪表盘；显示面板"}},{"en":"a piece of metal that forms part of the outer frame of a vehicle","cn":"（车身的）金属板，钣金","g":"[countable]","ex":{"en":"A rear body panel needed replacing after the accident.","cn":"事故之后，车身的一块后车板需要更换。"}},{"en":"a piece of cloth that forms part of a piece of clothing","cn":"（衣服上的）镶条，嵌条，饰片","g":"[countable]","ex":{"en":"The trousers have double thickness knee panels for extra protection.","cn":"这条裤子上有双倍厚的护膝片以加强保护。"}},{"en":"a group of specialists who give their advice or opinion about something; a group of people who discuss topics of interest on television or radio","cn":"专家咨询组；（广播、电视上的）讨论小组","g":"[countable + singular or plural verb]","ex":{"en":"an advisory panel","cn":"顾问组"}},{"en":"to cover or decorate a surface with flat pieces of wood, glass, etc.","cn":"镶板（用木或玻璃板等镶嵌或装饰）","ex":{"en":"The walls were panelled in oak.","cn":"墙壁镶了橡木饰片。"},"pos":"verb"}]}},"pamphlet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小册子","en":"A pamphlet is a very thin book, with a paper cover, which gives information about something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very short book with paper covers that usually contains information on one particular subject","cn":""},{"en":"a thin book with paper covers that gives information on something you may want to buy or advertises something","cn":""},{"en":"a small book or piece of paper, often only one or two folded pages, that advertises something or gives information on a particular subject","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A pamphlet is a little booklet with a soft (usually paper) cover that briefly addresses a particular subject of interest."}]},"collocations":{"phrases":["ADJ. political","VERB + PAMPHLET print, produce, publish, write | circulate, distribute","PAMPHLET + VERB be entitled sth","PREP. in a/the ~ accusations that were made in the pamphlet"]},"media":{"uk":"media/ldoce/hwd/bre/e/pamphlet0205.mp3","us":"media/ldoce/hwd/ame/5/pamphlet.mp3"},"examples":[{"en":"a political pamphlet","cn":"政治宣传册"}],"oxford":{"phon":"ˈpæmflət","pos":"noun","senses":[{"en":"a very thin book with a paper cover, containing information about a particular subject","cn":"小册子；手册","ex":{"en":"The government provides a pamphlet for all immigrants, outlining their rights.","cn":"政府向所有移民派发了小册子，概括介绍了他们的各种权利。"}}]}},"passport":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"护照","en":"Your passport is an official document containing your name, photograph, and personal details, which you need to show when you enter or leave a country.","ex":{"en":"You should take your passport with you when changing money.","cn":"兑换货币时应该带着护照。"}},{"pos":"N-COUNT 可数名词","cn":"进身之阶；（获取成功或幸福的）途径，手段","en":"If you say that a thing is a passport to success or happiness, you mean that this thing makes success or happiness possible.","ex":{"en":"Victory would give him a passport to the riches he craves","cn":"胜利将使他有机会获得自己梦寐以求的财富。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small official document that you get from your government, that proves who you are, and which you need in order to leave your country and enter other countries","cn":"护照"},{"en":"something that makes it easy for you to achieve success, good health etc","cn":"获取成功/健康/爱情等的通行证"}]},"collocations":{"phrases":["ADJ. valid | false, forged | EU, Mexican, French, etc. | visitor's","VERB + PASSPORT apply for | renew | get, obtain | be in possession of, carry, have, hold, travel on The police think the smugglers are trave","PASSPORT + VERB be valid | expire","PASSPORT + NOUN number, photo, photograph | holder | Agency, Office | control We had to queue for ages at passport control.","PREP. ~ into (figurative) The gold medal is his passport into professional boxing. | ~ to (figurative) Good qualifications are a passport to","PHRASES a full British/French, etc. passport (= one showing that sb has all the rights of British/French, etc. citizenship)"]},"media":{"uk":"media/ldoce/hwd/bre/b/passport0205.mp3","us":"media/ldoce/hwd/ame/b/passport.mp3"},"examples":[{"en":"I was stopped as I went through passport control (= where passports are checked).","cn":"在经过护照查验卡时，我被叫住了。"},{"en":"The only passport to success is hard work.","cn":"获得成功的唯一途径就是艰苦奋斗。"}],"oxford":{"phon":"ˈpɑːspɔːt","pos":"noun","senses":[{"en":"an official document that identifies you as a citizen of a particular country, and that you may have to show when you enter or leave a country","cn":"护照","ex":{"en":"a valid passport","cn":"有效护照"}},{"en":"a thing that makes something possible or enables you to achieve something","cn":"途径；路子；手段","ex":{"en":"The only passport to success is hard work.","cn":"获得成功的唯一途径就是艰苦奋斗。"}}]}},"pained":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情等）痛苦的，忧虑的，恼火的","en":"If you have a pained expression or look, you look upset, worried, or slightly annoyed."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone’s expression, voice etc that shows they are worried, upset, or slightly annoyed","cn":"痛苦的表情/神色/声音等"}]},"collocations":{"phrases":["VERBS be, look, seem, sound","ADV. positively | slightly a slightly pained expression on his face"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdepained.mp3","us":"media/ldoce/hwd/ame/6/pained.mp3"},"examples":[{"en":"a pained expression/voice","cn":"痛苦的表情/声音"},{"en":"He sat stiffly, with a pained expression on his face .","cn":"他僵坐在那里﹐脸上带着痛苦的表情。"}],"oxford":{"phon":"peɪnd","pos":"adjective","senses":[{"en":"showing that somebody is feeling annoyed or upset","cn":"显出痛苦（或难过、苦恼）的","ex":{"en":"a pained expression/voice","cn":"痛苦的表情／声音"}}]}},"patterned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有图案装饰的；饰有花样的","en":"Something that is patterned is covered with a pattern or design.","ex":{"en":"...a plain carpet with a patterned border.","cn":"有饰边的纯色地毯"}},{"pos":"V-PASSIVE 被动动词","cn":"仿造；模仿","en":"If something new is patterned on something else that already exists, it is deliberately made so that it has similar features.","ex":{"en":"New York City announced a 10-point policy patterned on the federal bill of rights for taxpayers","cn":"纽约市模仿联邦纳税人权利法案公布了10点政策。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"decorated with a pattern","cn":"有图案装饰的"}]},"collocations":{"phrases":["VERBS be","ADV. heavily, highly, richly a highly patterned fabric | attractively, beautifully, prettily | boldly, brightly, brilliantly, strikingly | d","PREP. with patterned with flowers"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdepatterned.mp3","us":"media/ldoce/hwd/ame/c/laadpatterned.mp3"},"examples":[{"en":"cups patterned with yellow flowers","cn":"有黄花图案的杯子"},{"en":"patterned wallpaper","cn":"印有图案的壁纸"}],"oxford":{"phon":"ˈpætənd","pos":"adjective","senses":[{"en":"decorated with a pattern","cn":"有图案的；带花样的","ex":{"en":"patterned wallpaper","cn":"印有图案的壁纸"}}]}},"patter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"嗒嗒作响；嗒嗒地拍","en":"If something patters on a surface, it hits it quickly several times, making quiet, tapping sounds.","ex":{"en":"Rain pattered gently outside, dripping on to the roof from the pines.","cn":"外面，松树上的雨水滴落在屋顶上，嗒嗒作响。"}},{"pos":"N-SING 单数名词","cn":"急促的轻拍声；嗒嗒声","en":"A patter is a series of quick, quiet, tapping sounds.","ex":{"en":"...the patter of the driving rain on the roof.","cn":"暴雨打在屋顶上发出的啪嗒声"}},{"pos":"N-SING 单数名词","cn":"（通常以娱乐、推销或劝说为目的的）顺口溜，伶俐话，连珠炮似的叫卖语","en":"Someone's patter is a series of things that they say quickly and easily, usually in order to entertain people or to persuade them to buy or do something.","ex":{"en":"There's no doubt women found him charming. It must have been his patter because he's certainly not at all good-looking","cn":"女人们无疑会觉得他很迷人。这肯定是因为他的顺口溜，因为他长得一点儿都不好看。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the sound produced when something hard keeps hitting another hard surface","cn":""},{"en":"the sound produced when someone keeps hitting a surface, especially a door or window, with their hand or with a hard object","cn":""},{"en":"to make a quiet irregular sound, like the sound of rain falling or quick, light steps","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When something patters , it makes a light, rhythmic, tapping sound. On a rainy night, you might love lying in bed listening to the rain patter on the roof."}]},"collocations":{"phrases":["ADV. gently, lightly, softly | down The rain pattered down softly.","PREP. across Footsteps pattered across the floor. | against, along The child's feet pattered along the landing. | on Rain pattered lightly o"]},"media":{"uk":"media/ldoce/hwd/bre/d/patter_v0205.mp3","us":"media/ldoce/hwd/ame/0/patter1.mp3"},"examples":[{"en":"I heard her feet pattering along the corridor.","cn":"我听到她步履轻盈地在走廊上走过。"},{"en":"We can't wait to hear the patter of tiny feet.","cn":"我们恨不得早点有个小宝宝。"}],"oxford":{"phon":"ˈpætə(r)","pos":"noun","senses":[{"en":"the sound that is made by something repeatedly hitting a surface quickly and lightly","cn":"吧嗒吧嗒的响声；急速的轻拍声","g":"[singular]","ex":{"en":"the patter of rain on the roof","cn":"雨打屋顶的啪哒声"}},{"en":"fast continuous talk by somebody who is trying to sell you something or entertain you","cn":"（为推销或娱乐的）不间断说话","g":"[uncountable, singular]","ex":{"en":"sales patter","cn":"为了推销一口气说的话"}},{"en":"to make quick, light sounds as a surface is being hit several times","cn":"发出轻快的拍打声","g":"[intransitive]","ex":{"en":"Rain pattered against the window.","cn":"雨点啪哒啪哒地敲击着窗子。"},"pos":"verb"},{"en":"to walk with light steps in a particular direction","cn":"轻盈地走","g":"[intransitive]","ex":{"en":"I heard her feet pattering along the corridor.","cn":"我听到她步履轻盈地在走廊上走过。"},"pos":"verb"}]}},"parcel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"包裹；邮包","en":"A parcel is something wrapped in paper, usually so that it can be sent to someone by post.","ex":{"en":"...parcels of food and clothing","cn":"装着食品和衣物的包裹"}},{"pos":"N-COUNT 可数名词","cn":"地块","en":"A parcel of land is a piece of land.","ex":{"en":"These small parcels of land were purchased for the most part by local people.","cn":"这些小块土地大多数是当地人买下的。"}},{"pos":"N-COUNT 可数名词","cn":"一批；一群","en":"A parcel of things or people is a quantity of them.","ex":{"en":"The woman who became his wife would be acquiring not just a husband but a run-down house and a parcel of financial worries.","cn":"女人嫁给他,得到的不仅是一个丈夫，还会有一栋破烂的房子和一大堆经济问题。"}},{"pos":"PHRASE 短语","cn":"…的内容；…的必要部分","en":"If you say that something is part and parcel of something else, you are emphasizing that it is involved or included in it.","ex":{"en":"Payment was part and parcel of carrying on insurance business within the UK","cn":"赔付是在英国开展保险业务必不可少的一部分。"}},{"pos":"","cn":"","en":"相关词组：parcel out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object that has been wrapped in paper or put in a special envelope, especially so that it can be sent by post","cn":"包裹，邮包"},{"en":"an area of land that is part of a larger area which has been divided up 〔","cn":"土地的〕一块﹐一片〔指已被分割的较大块土地的一部分〕"},{"en":"a small quantity of food that has been wrapped up, usually in pastry","cn":"食品的馅料〔通常指油酥点心中的馅料〕"}]},"vocab":{"pos":"1 n v 2 n 3 n v 4 v","senses":[{"en":"A parcel is a part of something, or a division. It can also be a package or a collection of things wrapped together."}]},"collocations":{"phrases":["ADJ. bulky | neat | brown-paper | gift-wrapped, tissue-wrapped, etc. | clothing, food","VERB + PARCEL post, send | get, receive | make sth (up) into, pack (up), wrap, wrap sth (up) in The waiter had our left-over food made up in","PARCEL + NOUN bomb","PREP. in a/the ~ | ~ from, ~ to","PHRASES laden/loaded with parcels He came in laden with parcels for the children."]},"media":{"img":["media/ldoce/img/parcel.jpg"],"uk":"media/ldoce/hwd/bre/c/parcel_n0205.mp3","us":"media/ldoce/hwd/ame/2/parcel1.mp3"},"examples":[{"en":"50 five-acre parcels have already been sold.","cn":"五英亩一块的土地已经售出 50 块。"},{"en":"There's a parcel and some letters for you.","cn":"有你的一个包裹和几封信。"}],"oxford":{"phon":"ˈpɑːsl","pos":"noun","senses":[{"en":"something that is wrapped in paper or put into a thick envelope so that it can be sent by mail, carried easily or given as a present","cn":"包裹；小包","lab":"especially British English","ex":{"en":"There's a parcel and some letters for you.","cn":"有你的一个包裹和几封信。"}},{"en":"a piece of land","cn":"一块地；一片地","ex":{"en":"50 five-acre parcels have already been sold.","cn":"五英亩一块的土地已经售出 50 块。"}},{"en":"a small amount of food that is wrapped in something, usually pastry, before it is cooked","cn":"油酥包（通常以油酥皮包裹少许食物烹制）","lab":"especially British English","ex":{"en":"filo pastry parcels","cn":"千层油酥包"}},{"en":"to wrap something up and make it into a parcel","cn":"包；裹好；打包","ex":{"en":"She parcelled up the books to send.","cn":"她把要寄走的书包了起来。"},"pos":"verb"}]}},"paralysis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻痹；瘫痪","en":"Paralysis is the loss of the ability to move and feel in all or part of your body.","ex":{"en":"...paralysis of the leg.","cn":"腿部麻痹"}},{"pos":"N-UNCOUNT 不可数名词","cn":"瘫痪状态","en":"Paralysis is the state of being unable to act or function properly.","ex":{"en":"The paralysis of the leadership leaves the army without its supreme command.","cn":"领导层瘫痪导致军队没有最高指挥。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the loss of the ability to move all or part of your body or feel things in it","cn":"瘫痪﹔麻痹"},{"en":"a state of being unable to take action, make decisions, or operate normally","cn":"不知所措﹔〔行动﹑决策﹑运行等〕瘫痪﹐停顿"}]},"vocab":{"pos":"n","senses":[{"en":"Paralysis is the inability to move part of your body. It's actually fairly common for people to have short periods of paralysis while they sleep."}]},"collocations":{"phrases":["ADJ. complete | partial | instant The snake's venom induces instant paralysis. | permanent | infantile","VERB + PARALYSIS be struck with | suffer from | cause, induce","PARALYSIS + VERB spread He had been crippled by a rare type of paralysis spreading from his ankle. 2 being unable to work in the normal way","ADJ. complete Strike leaders claimed &lsquo;almost complete paralysis&rsquo; in the ports and mines. | emotional, political"]},"media":{"uk":"media/ldoce/hwd/bre/c/paralysis0205.mp3","us":"media/ldoce/hwd/ame/0/paralysis.mp3"},"examples":[{"en":"The strike caused total paralysis in the city.","cn":"罢工使这座城市完全瘫痪。"},{"en":"paralysis of both legs","cn":"双腿瘫痪"}],"oxford":{"phon":"pəˈræləsɪs","pos":"noun","senses":[{"en":"a loss of control of, and sometimes feeling in, part or most of the body, caused by disease or an injury to the nerves","cn":"麻痹；瘫痪","g":"[uncountable, countable]","ex":{"en":"paralysis of both legs","cn":"双腿瘫痪"}},{"en":"the condition of being unable to move, act, function, etc.","cn":"（活动、工作等）能力的完全丧失，瘫痪","g":"[uncountable]","ex":{"en":"The strike caused total paralysis in the city.","cn":"罢工使这座城市完全瘫痪。"}}]}},"paralyse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使麻痹；使瘫痪","en":"If someone is paralysed by an accident or an illness, they have no feeling in their body, or in part of their body, and are unable to move.","ex":{"en":"Her married sister had been paralysed in a road accident.","cn":"她已婚的妹妹在一起交通事故中瘫痪了。"}},{"pos":"VERB 动词","cn":"使失去活动能力；使无法正常运转；使瘫痪","en":"If a person, place, or organization is paralysed by something, they become unable to act or function properly.","ex":{"en":"For weeks now the government has been paralysed by indecision","cn":"到现在，政府因为无力决断已经陷入瘫痪达数周。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage part of your body, or someone else’s body","cn":""},{"en":"to hurt yourself quite severely, or to be hurt in an accident or fighting","cn":""},{"en":"to deliberately hurt someone using a weapon such as a knife or gun","cn":""}]},"collocations":{"phrases":["ADV. completely, totally | partially, partly He was partially paralysed by the fall. | almost, virtually","PHRASES be paralysed from the chest/neck/waist down, be paralysed with fear, leave sb paralysed The accident left her paralysed."]},"media":{"uk":"media/ldoce/hwd/bre/1/paralyse0205.mp3","us":"media/ldoce/hwd/ame/e/paralyze.mp3"},"examples":[{"en":"The accident left him paralysed from the waist down.","cn":"那场事故使他腰部以下都瘫痪了。"},{"en":"( figurative ) She stood there, paralysed with fear.","cn":"她站在那里，吓得呆若木鸡。"}],"oxford":{"phon":"ˈpærəlaɪz","pos":"verb","senses":[{"en":"to make somebody unable to feel or move all or part of their body","cn":"使瘫痪；使麻痹","lab":"figurative","ex":{"en":"The accident left him paralysed from the waist down.","cn":"那场事故使他腰部以下都瘫痪了。"}},{"en":"to prevent something from functioning normally","cn":"使不能正常工作","ex":{"en":"The airport is still paralysed by the strike.","cn":"机场仍因罢工而陷于瘫痪。"}}]}},"paradise":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"天堂；天国","en":"According to some religions, paradise is a wonderful place where people go after they die, if they have led good lives.","ex":{"en":"The Koran describes paradise as a place containing a garden of delight","cn":"《古兰经》将天国描述成一个乐园。"}},{"pos":"N-VAR 可变名词","cn":"乐园；福地；极美的地方","en":"You can refer to a place or situation that seems beautiful or perfect as paradise or a paradise .","ex":{"en":"...one of the world's great natural paradises","cn":"世界上最美的自然乐园之一"}},{"pos":"N-COUNT 可数名词","cn":"（特定人群的）天堂，胜地","en":"You can use paradise to say that a place is very attractive to a particular kind of person and has everything they need for a particular activity.","ex":{"en":"The Algarve is a golfer's paradise","cn":"阿尔加维是高尔夫球手的天堂。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place or situation that is extremely pleasant, beautiful, or enjoyable","cn":"极乐（世界）﹔至美﹐至福"},{"en":"a place that has everything you need for doing a particular activity 〔","cn":"所需物一应俱全的〕乐园﹐乐土"},{"en":"in some religions, a perfect place where people are believed to go after they die, if they have led good lives","cn":"天堂﹐天国"}]},"vocab":{"pos":"n","senses":[{"en":"In some religions, paradise is considered the ultimate destination, but in general, it's any place that is ideal and free from worry. Eden, Shangri-la, or even the corner nail salon — each might represent paradise to someone."}]},"collocations":{"phrases":["VERB + PARADISE go to They all expected to go to paradise.","PREP. in ~ an angel in paradise 2 perfect place","ADJ. perfect, unspoilt | beautiful | lost the lost paradise of childhood | children's, walker's, etc. | earthly, island, tropical","VERB + PARADISE create She worked on the garden until she had created her own little paradise. | find They moved to the country hoping to fi","PARADISE + NOUN island","PREP. in (a) ~ We found ourselves in a tropical paradise. | ~ for The airport is a paradise for pickpockets. | ~ of a paradise of golden bea","PHRASES a paradise on earth"]},"media":{"uk":"media/ldoce/hwd/bre/b/paradise0205.mp3","us":"media/ldoce/hwd/ame/1/paradise.mp3"},"examples":[{"en":"The ancient Egyptians saw paradise as an idealized version of their own lives.","cn":"古埃及人把天堂视为人生活的理想形式。"},{"en":"The area is a birdwatcher's paradise.","cn":"这一地区是鸟类观察者的乐园。"}],"oxford":{"phon":"ˈpærədaɪs","pos":"noun","senses":[{"en":"(in some religions) a perfect place where people are said to go when they die","cn":"（某些宗教所指的）天堂，天国","g":"[uncountable]","ex":{"en":"The ancient Egyptians saw paradise as an idealized version of their own lives.","cn":"古埃及人把天堂视为他们自身现实生活的理想形式。"}},{"en":"a place that is extremely beautiful and that seems perfect, like heaven","cn":"天堂，乐土，乐园（指美好的环境）","g":"[countable]","ex":{"en":"a tropical paradise","cn":"一处热带的人间乐土"}},{"en":"a perfect place for a particular activity or kind of person","cn":"（某类活动或某类人的）乐园，完美去处","g":"[countable]","ex":{"en":"The area is a birdwatcher's paradise.","cn":"这一地区是鸟类观察者的乐园。"}},{"en":"a state of perfect happiness","cn":"至福；极乐","g":"[uncountable]","ex":{"en":"Being alone is his idea of paradise.","cn":"他视独处为至乐之事。"}},{"en":"the garden of Eden, where Adam and Eve lived","cn":"伊甸园","g":"[uncountable]"}]}},"parting":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"离别；分手；分别","en":"Parting is the act of leaving a particular person or place. A parting is an occasion when this happens.","ex":{"en":"Parting from any one of you for even a short time is hard","cn":"离开你们中任何一个人哪怕只是一小段时间都舍不得。"}},{"pos":"ADJ 形容词","cn":"离别的；分手的","en":"Your parting words or actions are the things that you say or do as you are leaving a place or person.","ex":{"en":"Her parting words left him feeling empty and alone.","cn":"她分手时说的话让他感觉空虚孤独。"}},{"pos":"N-COUNT 可数名词","cn":"（头发的）分缝","en":"The parting in someone's hair is the line running from the front to the back of their head where their hair lies in different directions."},{"pos":"PHRASE 短语","cn":"分道扬镳","en":"When there is a parting of the ways, two or more people or groups of people stop working together or travelling together.","ex":{"en":"...a negotiated parting of the ways for the three Baltic republics.","cn":"这三个波罗的海共和国协议分道扬镳"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when two people leave each other","cn":"分离﹐分开﹐离别"},{"en":"the line on your head made by dividing your hair with a comb 〔","cn":"头发的〕分缝"},{"en":"the point at which two people or organizations decide to separate 〔","cn":"两个人或机构〕决定分手的时刻﹐决定分道扬镳的地步"}]},"collocations":{"phrases":["ADJ. final | sad","PARTING + NOUN gift | shot, words As her parting shot she told me never to phone her again.","PHRASES the moment of parting She was already dreading the moment of parting."]},"media":{"uk":"media/ldoce/hwd/bre/0/parting_n0205.mp3","us":"media/ldoce/hwd/ame/b/parting1.mp3"},"examples":[{"en":"His parting words were ‘I love you.’","cn":"他临别的话是“我爱你”。"},{"en":"We had a tearful parting at the airport.","cn":"我们在机场洒泪而别。"}],"oxford":{"phon":"ˈpɑːtɪŋ","pos":"noun","senses":[{"en":"the act or occasion of leaving a person or place","cn":"离别；分手；分别","g":"[uncountable, countable]","ex":{"en":"She was already dreading the moment of parting.","cn":"她已经在害怕离别时刻的到来。"}},{"en":"a line on a person’s head where the hair is divided with a comb","cn":"（头发的）分缝，发缝，分线","g":"[countable]","lab":"British English","ex":{"en":"a side/centre parting","cn":"偏分；中分"}},{"en":"the act or result of dividing something into parts","cn":"分开；分离；散开","g":"[uncountable, countable]","ex":{"en":"the parting of the clouds","cn":"云破天开"}},{"en":"said or done by somebody as they leave","cn":"离别时说的（或做的）","ex":{"en":"a parting kiss","cn":"临别之吻"},"pos":"adjective"}]}},"partial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"部分的；不完全的","en":"You use partial to refer to something that is not complete or whole.","ex":{"en":"He managed to reach a partial agreement with both republics.","cn":"他设法与两个共和国都达成了部分协议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喜欢的；偏爱的","en":"If you are partial to something, you like it.","ex":{"en":"He's partial to sporty women with blue eyes","cn":"他喜欢爱运动的蓝眼睛女子。"}},{"pos":"ADJ 形容词","cn":"偏袒的；偏心的","en":"Someone who is partial supports a particular person or thing, for example in a competition or dispute, instead of being completely fair.","ex":{"en":"I might be accused of being partial","cn":"可能会有人骂我偏心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"only containing or including part of what is necessary to be complete","cn":""},{"en":"if something is patchy , it does not include enough information, or important details are missing","cn":""},{"en":"not complete","cn":"部分的﹐不完全的"}]},"vocab":{"pos":"1 adj 2 adj 3 n 4 n","senses":[{"en":"If you describe something as partial , you're usually saying it's just part of the whole, or incomplete. Say someone asks how you started your band and you say, \"I bought a guitar.\" That would be a partial answer, at best."}]},"collocations":{"phrases":["VERBS be | remain","ADV. very | only | inevitably, necessarily The information we have is inevitably partial."]},"media":{"uk":"media/ldoce/hwd/bre/1/partial0205.mp3","us":"media/ldoce/hwd/ame/2/partial.mp3"},"examples":[{"en":"It was only a partial solution to the problem.","cn":"那只是部分地解决了这个问题。"},{"en":"I'm not partial to mushrooms.","cn":"我不太爱吃蘑菇。"}],"oxford":{"phon":"ˈpɑːʃl","pos":"adjective","senses":[{"en":"not complete or whole","cn":"部分的；不完全的","ex":{"en":"It was only a partial solution to the problem.","cn":"那只是部分地解决了这个问题。"}},{"en":"liking somebody/something very much","cn":"热爱；钟爱","g":"[not before noun]","lab":"old-fashioned","ex":{"en":"I'm not partial to mushrooms.","cn":"我不太爱吃蘑菇。"}},{"en":"showing or feeling too much support for one person, team, idea, etc., in a way that is unfair","cn":"偏颇；偏袒","g":"[not usually before noun]","lab":"disapproving","ex":{"en":"The resulting assessment is necessarily partial and subjective.","cn":"评估结果难免会有偏颇和带有主观性。"}}]}},"packaging":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"包装物","en":"Packaging is the container or covering that something is sold in.","ex":{"en":"It is selling very well, in part because the packaging is so attractive.","cn":"这个卖得非常好，部分原因是包装非常吸引人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the container or material that a product is sold in","cn":"包装盒[瓶﹐袋]；包装材料"},{"en":"the process of wrapping something for sale","cn":"包装（工作）"},{"en":"a way of making something seem attractive and interesting to people","cn":"包装﹐美化"}]},"collocations":{"phrases":["ADJ. fancy, glossy CDs would be far cheaper to produce without the glossy packaging. | discarded, waste | non-recyclable, recyclable | drink","VERB + PACKAGING recycle","PACKAGING + NOUN materials | technology | waste | company, firm, group, manufacturer | industry"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdepackaging.mp3","us":"media/ldoce/hwd/ame/4/packaging.mp3","img":["media/pic/packaging_comp.jpg"]},"examples":[{"en":"His company offers a flexible packaging service for the food industry.","cn":"他的公司为食品工业提供灵活的包装业务。"},{"en":"Attractive packaging can help to sell products.","cn":"精美的包装有助于产品的销售。"}],"oxford":{"phon":"ˈpækɪdʒɪŋ","pos":"noun","senses":[{"en":"materials used to wrap or protect goods that are sold in shops","cn":"包装材料；外包装","ex":{"en":"Attractive packaging can help to sell products.","cn":"精美的包装有助于产品的销售。"}},{"en":"the process of wrapping goods","cn":"包装工作；包装","ex":{"en":"His company offers a flexible packaging service for the food industry.","cn":"他的公司为食品工业提供灵活的包装业务。"}}]}},"pardon":{"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"对不起,请再说一遍（美国英语用Pardon me?）","en":"You say 'Pardon?' or 'I beg your pardon?' or, in American English, 'Pardon me?' when you want someone to repeat what they have just said because you have not heard or understood it.","ex":{"en":"'Will you let me open it?' — 'Pardon?' — 'Can I open it?'","cn":"“我能打开它吗？”——“请再说一遍？”——“我能打开它吗？”"}},{"pos":"CONVENTION 惯用语","cn":"你说什么？（表示惊讶或者受到冒犯）","en":"People say 'I beg your pardon?' when they are surprised or offended by something that someone has just said.","ex":{"en":"'Would you get undressed, please?' — 'I beg your pardon?' — 'Will you get undressed?'","cn":"“请你脱掉衣服，好吗？”——“你说什么？”——“脱掉衣服，好吗？”"}},{"pos":"CONVENTION 惯用语","cn":"对不起；请原谅","en":"You say 'I beg your pardon' or 'I do beg your pardon' as a way of apologizing for accidentally doing something wrong, such as disturbing someone or making a mistake.","ex":{"en":"I was impolite and I do beg your pardon","cn":"我失礼了，真对不起。"}},{"pos":"CONVENTION 惯用语","cn":"对不起，不好意思打断一下（用于引起他人注意或者打断他人）","en":"Some people say 'Pardon me' instead of 'Excuse me' when they want to politely get someone's attention or interrupt them.","ex":{"en":"Pardon me, are you finished, madam?","cn":"对不起，您用完餐了吗，夫人？"}},{"pos":"CONVENTION 惯用语","cn":"恕我直言","en":"You can say things like 'Pardon me for asking' or 'Pardon my frankness' as a way of showing you understand that what you are going to say may sound rude.","ex":{"en":"That, if you'll pardon my saying so, is neither here nor there.","cn":"恕我直言，那根本就不重要。"}},{"pos":"CONVENTION 惯用语","cn":"请原谅我这么说；说句粗话您别介意","en":"Some people say things like 'If you'll pardon the expression' or 'Pardon my French' just before or after saying something which they think might offend people.","ex":{"en":"It's enough to make you wet yourself, if you'll pardon the expression.","cn":"这足以吓得你尿裤子了，请原谅我这么说。"}},{"pos":"VERB 动词","cn":"赦免","en":"If someone who has been found guilty of a crime is pardoned, they are officially allowed to go free and are not punished.","ex":{"en":"Hundreds of political prisoners were pardoned and released.","cn":"数百名政治犯被赦免释放。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"say this when you want to ask someone politely to repeat what they just said because you did not hear it","cn":""},{"en":"say this when you did not hear what someone said, or when you are surprised by what they said","cn":""},{"en":"use this in formal situations to ask someone to repeat something","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you belch, interrupt a conversation, or leave the table during dinner, you’re expected to say “ Pardon me.” Once you’ve requested your companions’ pardon , or forgiveness, you can assume you have it; you don’t need to wait for their response."}]},"collocations":{"phrases":["ADJ. full | partial | conditional | general | free | posthumous | presidential, royal","VERB + PARDON give sb, grant sb | offer sb The government offered a free pardon to the rebels. | buy, obtain, receive | ask (for), seek | re","PREP. ~ for She asked for pardon for her crime."]},"media":{"uk":"media/ldoce/hwd/bre/4/pardon_n0205.mp3","us":"media/ldoce/hwd/ame/5/pardon1.mp3"},"examples":[{"en":"‘You're very quiet today.’ ‘Pardon?’ ‘I said you're very quiet today.’ “","cn":"你今天话很少啊。” “什么？” “我说你今天话很少。”"},{"en":"‘Oh, just shut up!’ ‘Well, pardon me for breathing!’ “","cn":"你给我闭嘴！” “哦，真抱歉，我呼吸也打扰到你了！”"}],"oxford":{"phon":"ˈpɑːdn","pos":"exclamation","senses":[{"en":"used to ask somebody to repeat something because you did not hear it or did not understand it","cn":"（用于请求别人重复某事）什么，请再说一遍","lab":"especially in North American English","ex":{"en":"‘You're very quiet today.’ ‘Pardon?’ ‘I said you're very quiet today.’","cn":"“你今天话很少啊。”“什么？”“我说你今天话很少。”"}},{"en":"used by some people to say ‘sorry’ when they have said or done something wrong, usually by accident","cn":"（为无意之中说错话或行为失当表示歉意）对不起"},{"en":"an official decision not to punish somebody for a crime, or to say that somebody is not guilty of a crime","cn":"赦免；特赦","g":"[countable]","lab":"British English also","ex":{"en":"to ask/grant/receive a pardon","cn":"请求／准予／获得赦免"},"pos":"noun"},{"en":"the action of forgiving somebody for something","cn":"原谅；宽恕","g":"[uncountable]","lab":"formal","ex":{"en":"He asked her pardon for having deceived her.","cn":"他欺骗了她，向她请求原谅。"},"pos":"noun"},{"en":"to officially allow somebody who has been found guilty of a crime to leave prison and/or avoid punishment","cn":"赦免；特赦","ex":{"en":"She was pardoned after serving ten years of a life sentence.","cn":"她被判终身监禁，服刑十年后被赦免了。"},"pos":"verb"},{"en":"to forgive somebody for something they have said or done (used in many expressions when you want to be polite)","cn":"原谅（表示礼貌时常用的词语）","ex":{"en":"Pardon my ignorance, but what is a ‘duplex’?","cn":"请原谅我无知，duplex 是什么呢？"},"pos":"verb"}]}},"parody":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"戏仿作品","en":"A parody is a humorous piece of writing, drama, or music which imitates the style of a well-known person or represents a familiar situation in an exaggerated way.","ex":{"en":"'The Scarlet Capsule' was a parody of the popular 1959 TV series 'The Quatermass Experiment'","cn":"《红胶囊》戏仿了1959年大受欢迎的电视连续剧《夸特马斯试验》。"}},{"pos":"VERB 动词","cn":"戏仿；滑稽（或夸张）地模仿","en":"When someone parodies a particular work, thing, or person, they imitate it in an amusing or exaggerated way.","ex":{"en":"...a sketch parodying the views of Jean-Marie Le Pen","cn":"夸张模仿让－马里·勒庞观点的短剧"}},{"pos":"N-COUNT 可数名词","cn":"（对特定事物的）拙劣模仿","en":"When you say that something is a parody of a particular thing, you are criticizing it because you think it is a very poor example or bad imitation of that thing.","ex":{"en":"The first trial was a parody of justice.","cn":"第一次审判是对正义的愚弄。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a film, book etc that makes fun of a serious type of film, book etc by copying it in a funny way","cn":""},{"en":"a performance, film, article etc that makes fun of a situation or the behaviour of a group of people by copying it in a funny way","cn":""},{"en":"a piece of writing or music that is amusing because it makes fun of a famous piece of writing or music by clearly copying its style","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A parody is a humorous or mocking imitation of something, using the same form as the original. To parody a poem, you have to write another poem."}]},"collocations":{"phrases":["ADJ. brilliant, clever | cruel","VERB + PARODY compose, write","PREP. through ~ He attacked her ideas through parody. | ~ of She has written a cruel parody of his book. | ~ on The show included a parody o","ADJ. grotesque","PREP. in a ~ of He sighed in a parody of deep emotion. | ~ of She has become a grotesque parody of her former elegant self.","PHRASES a parody of justice The trial was a parody of justice."]},"media":{"uk":"media/ldoce/hwd/bre/0/parody_v0205.mp3","us":"media/ldoce/hwd/ame/e/parody1.mp3"},"examples":[{"en":"The trial was a parody of justice.","cn":"那次审判是对正义的嘲弄。"},{"en":"a parody of a horror film","cn":"一部恐怖电影的仿作"}],"oxford":{"phon":"ˈpærədi","pos":"noun","senses":[{"en":"a piece of writing, music, acting, etc. that deliberately copies the style of somebody/something in order to be humorous","cn":"滑稽模仿作品（文章、音乐作品或表演等的滑稽模仿）","g":"[countable, uncountable]","ex":{"en":"a parody of a horror film","cn":"一部恐怖电影的仿作"}},{"en":"something that is such a bad or an unfair example of something that it seems silly","cn":"拙劣的模仿；荒诞不经的事","g":"[countable]","lab":"disapproving","ex":{"en":"The trial was a parody of justice.","cn":"那次审判是对正义的嘲弄。"}},{"en":"to copy the style of somebody/something in an exaggerated way, especially in order to make people laugh","cn":"滑稽地模仿；夸张地演绎","ex":{"en":"Her work parodies genres such as the thriller and the spy novel.","cn":"她的作品对惊险和谍战一类小说进行夸张演绎。"},"pos":"verb"}]}},"paranoia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"疑惧；多疑","en":"If you say that someone suffers from paranoia, you think that they are too suspicious and afraid of other people.","ex":{"en":"The mood is one of paranoia and expectation of war.","cn":"那是一种对战争既畏惧又期待的心理。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"偏执狂；妄想症","en":"In psychology, if someone suffers from paranoia, they wrongly believe that other people are trying to harm them, or believe themselves to be much more important than they really are."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable belief that you cannot trust other people, or that they are trying to harm you or have a bad opinion of you","cn":"多疑﹐瞎猜疑"},{"en":"a mental illness that makes someone believe that they are very important and that people hate them and are trying to harm them","cn":"偏执狂﹐妄想狂"}]},"vocab":{"pos":"n","senses":[{"en":"Something that happens to a person's thinking can lead to paranoia. You may believe that your friends no longer like you, but it's just that your paranoia makes you suspicious of everyone."}]},"collocations":{"phrases":["ADJ. increasing, mounting","VERB + PARANOIA suffer from | border on, verge on Her passion for cleanliness borders on paranoia.","PARANOIA + VERB afflict sb"]},"media":{"uk":"media/ldoce/hwd/bre/0/paranoia0205.mp3","us":"media/ldoce/hwd/ame/8/paranoia.mp3"},"oxford":{"phon":"ˌpærəˈnɔɪə","pos":"noun","senses":[{"en":"the belief that other people dislike or want to harm you, when there is no evidence or reason for this","cn":"（对别人的）无端恐惧，多疑","ex":{"en":"External threats will just fuel paranoia among those in power.","cn":"外部威胁只会加剧当权者的偏执。"}},{"en":"false beliefs that are part of a mental illness, especially the belief that people are trying or planning to harm you","cn":"偏执狂；妄想症","lab":"psychology","ex":{"en":"The drugs can induce paranoia.","cn":"这些药物会诱发偏执。"}}]}},"patent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专利权","en":"A patent is an official right to be the only person or company allowed to make or sell a new product for a certain period of time.","ex":{"en":"P&G applied for a patent on its cookies","cn":"宝洁公司为它的饼干申请专利权。"}},{"pos":"VERB 动词","cn":"得到…的专利权","en":"If you patent something, you obtain a patent for it.","ex":{"en":"He patented the idea that the atom could be split","cn":"他获得了“原子可以再分”这一概念的专利权。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指坏事物）明显的，显而易见的","en":"You use patent to describe something, especially something bad, in order to indicate in an emphatic way that you think its nature or existence is clear and obvious.","ex":{"en":"This was patent nonsense.","cn":"这明显是胡说八道。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special document that gives you the right to make or sell a new invention or product that no one else is allowed to copy","cn":"专利证书"},{"en":"protected by a patent","cn":"受专利保护的﹔专利的"},{"en":"used to emphasize that something is clearly a lie etc","cn":"明显的谎言/胡说/不可能等"}]},"vocab":{"pos":"1 n v 2 adj v","senses":[{"en":"A patent is a government document that proves that an invention is yours and yours alone. In the US, as of 2009, over 7,000,000 patents were issued by the Patent and Trademark Office."}]},"collocations":{"phrases":["VERB + PATENT apply for, file In 1843 Bain filed a patent for his fax machine. | get, obtain, take out | protect sth by Genetically engineer","PATENT + NOUN application | protection | law a leading authority on patent law | Office","PREP. ~ for In 1995 he was granted a patent for his invention. | ~ on Edison took out a patent on the light bulb.","PHRASES patent pending (= waiting to be issued) The item is Patent Pending No. 912057."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdepatent.mp3","us":"media/ldoce/hwd/ame/0/patent1.mp3"},"examples":[{"en":"to apply for/obtain a patent on an invention","cn":"申请/获得发明专利权"},{"en":"The device was protected by patent.","cn":"这一装置受专利保护。"}],"oxford":{"phon":"ˈpætnt","pos":"noun","senses":[{"en":"an official right to be the only person to make, use or sell a product or an invention; a document that proves this","cn":"专利；专利证书","ex":{"en":"to apply for/obtain/take out a patent on an invention","cn":"申请／获得／取得发明专利"}},{"en":"made or sold by a particular company","cn":"专利生产的；专利经销的","ex":{"en":"patent medicines","cn":"专利药"},"pos":"adjective"},{"en":"used to emphasize that something bad is very clear and obvious","cn":"明显的；赤裸裸的","lab":"formal","ex":{"en":"It was a patent lie.","cn":"那是赤裸裸的谎言。"},"pos":"adjective"},{"en":"to obtain a patent for an invention or a process","cn":"获得专利","pos":"verb"}]}},"paste":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"糊糊；糨糊","en":"Paste is a soft, wet, sticky mixture of a substance and a liquid, which can be spread easily. Some types of paste are used to stick things together.","ex":{"en":"He then sticks it back together with flour paste","cn":"然后他用面糊把它重新粘了起来。"}},{"pos":"N-MASS 物质名词","cn":"（肉、水果或蔬菜弄碎做成的）酱","en":"Paste is a soft smooth mixture made of crushed meat, fruit, or vegetables. You can, for example, spread it onto bread or use it in cooking.","ex":{"en":"...tomato paste.","cn":"番茄酱"}},{"pos":"VERB 动词","cn":"粘贴；黏合","en":"If you paste something on a surface, you put glue or paste on it and stick it on the surface.","ex":{"en":"...pasting labels on bottles","cn":"把商标贴在瓶子上"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（制造人造宝石的）铅玻璃","en":"Paste is a hard shiny glass that is used for making imitation jewellery.","ex":{"en":"...paste emeralds.","cn":"铅玻璃翡翠"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put information into a computer by pressing the keys","cn":""},{"en":"to make a file, program etc that is exactly the same as another one","cn":""},{"en":"to make a computer keep the work that you have done in its memory or on a disk","cn":""}]},"collocations":{"phrases":["ADJ. firm, stiff, thick | lumpy, smooth | wallpaper | curry, fish, tomato, etc.","VERB + PASTE make (up), mix (up), mix sth into/to Mix the sugar mixture to a smooth paste. | form Mix the flour with enough water to form a "]},"media":{"uk":"media/ldoce/hwd/bre/c/paste_v0205.mp3","us":"media/ldoce/hwd/ame/8/paste1.mp3"},"examples":[{"en":"The children were busy cutting and pasting paper hats.","cn":"孩子们忙着剪裁和粘贴纸帽子。"},{"en":"This function allows you to cut and paste text.","cn":"本功能可使你剪切并粘贴文本。"}],"oxford":{"phon":"peɪst","pos":"noun","senses":[{"en":"a soft wet mixture, usually made of a powder and a liquid","cn":"面糊","g":"[singular]","ex":{"en":"She mixed the flour and water to a smooth paste.","cn":"她把面粉和水和成细滑的面糊。"}},{"en":"a smooth, soft mixture of meat, fish, etc. that is spread on bread or used in cooking","cn":"酱（肉、鱼等做成，涂抹或烹饪用）","g":"[countable]","ex":{"en":"meat/fish/tomato paste","cn":"肉酱；鱼酱；番茄酱"}},{"en":"a type of glue that is used for sticking paper to things","cn":"糨糊","g":"[uncountable]","ex":{"en":"wallpaper paste","cn":"贴壁纸用的糨糊"}},{"en":"a substance like glass, that is used for making artificial jewels, for example diamonds","cn":"（制作人造宝石的）铅质玻璃","g":"[uncountable]"},{"en":"to stick something to something else using glue or paste","cn":"粘贴；粘合","g":"[transitive]","ex":{"en":"He pasted the pictures into his scrapbook.","cn":"他把画片贴到他的剪贴簿里。"},"pos":"verb"},{"en":"to make something by sticking pieces of paper together","cn":"拼贴","g":"[transitive]","ex":{"en":"The children were busy cutting and pasting paper hats.","cn":"孩子们忙着剪裁和粘贴纸帽子。"},"pos":"verb"},{"en":"to copy or move text into a document from another place or another document","cn":"粘贴；贴入；插入","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"This function allows you to cut and paste text.","cn":"本功能可使你剪切并粘贴文本。"},"pos":"verb"}]}},"pallor":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（脸色或肤色的）苍白","en":"If you refer to the pallor of someone's face or skin, you mean that it is pale and unhealthy.","ex":{"en":"The deathly pallor of her skin had been replaced by the faintest flush of color","cn":"她如死灰般苍白的皮肤开始现出淡淡的血色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone’s skin is very pale in a way that makes them look weak or unhealthy","cn":"肤色苍白"}]},"vocab":{"pos":"n","senses":[{"en":"When you’ve got the flu, that pale, sickly color of your skin is called a pallor . Other causes of pallor include shock, stress, or 10 days spent indoors trying to beat your new video game."}]},"collocations":{"phrases":["ADJ. slight | deathly, ghostly, sickly the deathly pallor of her face | green, grey, white","VERB + PALLOR have He had a sickly green pallor."]},"media":{"uk":"media/ldoce/hwd/bre/5/pallor0205.mp3","us":"media/ldoce/hwd/ame/3/pallor.mp3"},"examples":[{"en":"Her cheeks had an unhealthy pallor.","cn":"她面色苍白，显得虚弱。"},{"en":"A sleepless night had added to her pallor.","cn":"一夜未眠﹐她的脸色更加苍白。"}],"oxford":{"phon":"ˈpælə(r)","pos":"noun","senses":[{"en":"a pale colour of the face, especially because of illness or fear","cn":"苍白的脸色（尤指因病或恐惧）","ex":{"en":"Her cheeks had an unhealthy pallor.","cn":"她面色苍白，显得虚弱。"}}]}},"packet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"包装盒；包装袋","en":"A packet is a small container in which a quantity of something is sold. Packets are either small boxes made of thin cardboard, or bags or envelopes made of paper or plastic.","ex":{"en":"Cook the rice according to instructions on the packet.","cn":"按照包装袋上的说明煮饭。"}},{"pos":"N-COUNT 可数名词","cn":"（扁平的）小包裹","en":"A packet is a small flat parcel.","ex":{"en":"...to send letters and packets abroad.","cn":"将信和包裹寄往国外"}},{"pos":"N-SING 单数名词","cn":"一大笔钱","en":"You can refer to a lot of money as a packet .","ex":{"en":"It'll cost you a packet","cn":"那会花你一大笔钱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container made of paper, plastic, or cardboard that something is sold in 〔","cn":"装商品的〕小包﹐小盒﹐小袋"},{"en":"a small flat paper or plastic container that a liquid or powder is sold in 〔","cn":"装有供出售的液体或粉末的〕小袋，小包"},{"en":"a small flat package that is sent by post or delivered to someone 〔","cn":"扁平〕小包裹"}]},"collocations":{"phrases":["ADJ. empty | cereal, cigarette, cornflake, crisp, seed | pay, wage a weekly pay packet (= wage) of &pound; 200","VERB + PACKET open, undo | take sth from/out of","PACKET + VERB contain sth a packet containing seeds","PACKET + NOUN soup","PREP. on a/the ~ Follow the instructions on the packet. | ~ of a packet of crisps"]},"media":{"uk":"media/ldoce/hwd/bre/e/packet0205.mp3","us":"media/ldoce/hwd/ame/5/packet.mp3","img":["media/thumb/packet.jpg"]},"examples":[{"en":"That car must have cost a packet.","cn":"买那辆汽车一定花了一大笔钱。"},{"en":"A packet of photographs arrived with the mail.","cn":"一包照片邮寄来了。"}],"oxford":{"phon":"ˈpækɪt","pos":"noun","senses":[{"en":"a small container made of paper or card in which goods are packed for selling","cn":"（商品的）小包装纸袋，小硬纸板盒","lab":"British English","ex":{"en":"a packet of biscuits/cigarettes/crisps","cn":"一包饼干／香烟／炸薯片"}},{"en":"a small object wrapped in paper or put into a thick envelope so that it can be sent by mail, carried easily or given as a present","cn":"（邮政）小件包裹","ex":{"en":"A packet of photographs arrived with the mail.","cn":"一包照片邮寄来了。"}},{"en":"a closed plastic or paper package that contains a very small amount of liquid or a powder","cn":"（密封的塑料或纸质）小袋","lab":"North American English","ex":{"en":"a packet of instant cocoa mix","cn":"一袋混合速溶可可粉"}},{"en":"a large amount of money","cn":"一大笔钱","g":"[singular]","lab":"British English, informal，，","ex":{"en":"That car must have cost a packet.","cn":"买那辆汽车一定花了一大笔钱。"}},{"en":"a piece of information that forms part of a message sent through a computer network","cn":"信息包；数据包","lab":"computing","ex":{"en":"The data transmission is split into a number of packets of equal size.","cn":"数据传输被分成许多大小相等的数据包。"}},{"en":"a set of documents that are supplied together for a particular purpose","cn":"一套文件；一套资料","lab":"North American English","ex":{"en":"a training packet","cn":"一套培训材料"}}]}},"paleontologist":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of fossil s (= ancient bones, plants etc that have been preserved in rock )","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A paleontologist is a scientist who studies fossils. If your basement is filled with fossils found while out on hikes, then you're an amateur paleontologist."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44paleontology.mp3","us":"media/ldoce/hwd/ame/6/paleontology.mp3"},"oxford":{"phon":"ˌpæliɒnˈtɒlədʒɪst","pos":"noun","senses":[{"en":"a person who studies fossils","cn":"古生物学家；化石学家"}]}},"password":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"口令；密码","en":"A password is a secret word or phrase that you must know in order to be allowed to enter a place such as a military base, or to be allowed to use a computer system.","ex":{"en":"Advance and give the password","cn":"上前说出口令。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to do the actions that will allow you to begin using a computer system, for example by typing a special word or giving a particular command","cn":""},{"en":"to do the actions you have to do when you finish using a computer system","cn":""},{"en":"if you start up a computer, or it starts up , you turn it on","cn":""}]},"collocations":{"phrases":["ADJ. correct, valid | invalid | user Please supply a valid user password.","VERB + PASSWORD know | give You must give the password before they'll let you in. | enter, provide, supply, type in | change","PHRASES be password protected Your mailbox can be password protected to ensure security."]},"media":{"uk":"media/ldoce/hwd/bre/8/password0205.mp3","us":"media/ldoce/hwd/ame/f/password.mp3"},"examples":[{"en":"Enter a username and password to get into the system.","cn":"进入系统请键入用户名称和密码。"},{"en":"Enter your password, then click on the ‘proceed’ icon.","cn":"键入密码﹐然后点击“继续”图标。"}],"oxford":{"phon":"ˈpɑːswɜːd","pos":"noun","senses":[{"en":"a series of letters, numbers, etc. that you must type into a computer or computer system in order to be able to use it","cn":"口令（字）；密码","ex":{"en":"Enter a username and password to get into the system.","cn":"进入系统请键入用户名和密码。"}},{"en":"a secret word or phrase that you need to know in order to be allowed into a place","cn":"暗语；暗号；口令","ex":{"en":"You must give the password before they'll let you in.","cn":"你必须给出口令，他们才会让你进去。"}}]}},"paddle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桨；短桨","en":"A paddle is a short pole with a wide flat part at one end or at both ends. You hold it in your hands and use it as an oar to move a small boat through water.","ex":{"en":"We might be able to push ourselves across with the paddle.","cn":"我们也许可以用桨把自己推过去。"}},{"pos":"VERB 动词","cn":"用桨划（船）","en":"If you paddle a boat, you move it through water using a paddle.","ex":{"en":"...the skills you will use to paddle the canoe.","cn":"划独木舟要用到的技术"}},{"pos":"VERB 动词","cn":"玩水；涉水","en":"If you paddle, you walk or stand in shallow water, for example at the edge of the sea, for pleasure.","ex":{"en":"Wear sandals when you paddle.","cn":"玩水的时候穿上凉鞋。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short pole that is wide and flat at the end, used for moving a small boat in water 〔","cn":"小船的〕短桨﹐桨"},{"en":"when you walk for pleasure without shoes or socks in water that is not very deep","cn":"赤脚涉水〔玩〕"},{"en":"a small round flat bat with a short handle, used for hitting the ball in table tennis 〔","cn":"乒乓球的〕球拍"}]},"vocab":{"pos":"1 n v 2 n 3 n v 4 v","senses":[{"en":"If you regularly ride around in a canoe, you’re undoubtedly already familiar with a paddle , a pole with a broad, flat end that is used to propel a boat forward."}]},"collocations":{"phrases":["ADV. downstream, upstream | frantically, furiously He paddled furiously against the current. | slowly"]},"media":{"img":["media/ldoce/img/canoeing.jpg"],"uk":"media/ldoce/hwd/bre/7/brelasdepaddle.mp3","us":"media/ldoce/hwd/ame/a/paddle1.mp3"},"examples":[{"en":"We paddled downstream for about a mile.","cn":"我们划船顺流而下约一英里。"},{"en":"We paddled the canoe along the coast.","cn":"我们划着独木舟沿海岸而行。"}],"oxford":{"phon":"ˈpædl","pos":"noun","senses":[{"en":"a short pole with a flat wide part at one or both ends, that you hold in both hands and use for moving a small boat, especially a canoe, through water","cn":"桨；船桨","g":"[countable]"},{"en":"a tool or part of a machine that is like a paddle in shape, especially one used for mixing food","cn":"（机具的）桨状部分；（尤指）食物搅拌器的桨叶","g":"[countable]"},{"en":"an act or period of walking in shallow water with no shoes or socks","cn":"蹚水；赤脚涉水","g":"[singular]","lab":"British English","ex":{"en":"Let's go for a paddle.","cn":"咱们去玩水吧。"}},{"en":"a bat used for playing table tennis","cn":"乒乓球拍","g":"[countable]","lab":"North American English"},{"en":"a piece of wood with a handle, used in the past for hitting children as a punishment","cn":"（旧时体罚用的）戒尺","g":"[countable]","lab":"North American English"},{"en":"to move a small boat through water using a paddle","cn":"用桨划船","g":"[intransitive, transitive]","ex":{"en":"We paddled downstream for about a mile.","cn":"我们划船顺流而下约一英里。"},"pos":"verb"},{"en":"to walk or stand with no shoes or socks in shallow water in the sea, a lake, etc.","cn":"蹚水；赤足涉水","g":"[intransitive]","lab":"British English","ex":{"en":"The children have gone paddling.","cn":"孩子们戏水去了。"},"pos":"verb"},{"en":"to swim with short movements of your hands or feet up and down","cn":"狗刨式游泳","g":"[intransitive]","pos":"verb"},{"en":"to hit a child with a flat piece of wood as a punishment","cn":"用戒尺打（孩子）","g":"[transitive]","lab":"North American English","pos":"verb"}]}},"patchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"分布不均衡的；散落的；斑驳的","en":"A patchy substance or colour exists in some places but not in others, or is thick in some places and thin in others.","ex":{"en":"Thick patchy fog and irresponsible driving were to blame","cn":"局部浓雾和驾驶员不负责任是罪魁祸首。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时好时坏的；不稳定的；差强人意的","en":"If something is patchy, it is not completely reliable or satisfactory because it is not always good.","ex":{"en":"The evidence is patchy","cn":"证据不充分。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good - use this when you are disappointed because you were expecting something better","cn":""},{"en":"something that is mediocre is of a lower standard than it should be, and does not show much quality or skill","cn":""},{"en":"not very bad, but not especially good","cn":""}]},"collocations":{"phrases":["VERBS be, seem | become | remain","ADV. decidedly, extremely, very The local provision of facilities is decidedly patchy. | a bit, a little, rather Attendance at these matches"]},"media":{"uk":"media/ldoce/hwd/bre/0/patchy0205.mp3","us":"media/ldoce/hwd/ame/4/patchy.mp3"},"examples":[{"en":"The grass was dry and patchy.","cn":"草都干了，东一片西一片的。"},{"en":"It was a patchy performance.","cn":"那是一场水准参差的演出。"}],"oxford":{"phon":"ˈpætʃi","pos":"adjective","senses":[{"en":"existing or happening in some places and not others","cn":"零散的；散落的；分布不匀的","ex":{"en":"patchy fog","cn":"团团的雾"}},{"en":"not complete; good in some parts, but not in others","cn":"不完整的；参差不齐的","lab":"North American English also","ex":{"en":"a patchy knowledge of Spanish","cn":"对西班牙语一知半解"}}]}},"parachute":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"降落伞","en":"A parachute is a device which enables a person to jump from an aircraft and float safely to the ground. It consists of a large piece of thin cloth attached to your body by strings.","ex":{"en":"They fell 41,000 ft. before opening their parachutes","cn":"他们下降了41,000英尺后才拉开伞。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）跳伞；（使）空降","en":"If a person parachutes or someone parachutes them somewhere, they jump from an aircraft using a parachute.","ex":{"en":"He was a courier for the Polish underground and parachuted into Warsaw","cn":"他是波兰地下组织的情报员，被空降到华沙。"}},{"pos":"VERB 动词","cn":"空投","en":"To parachute something somewhere means to drop it somewhere by parachute.","ex":{"en":"Planes parachuted food, clothing, blankets, medicine and water into the rugged mountainous border region","cn":"飞机将食品、衣物、毯子、药品和水空投到崎岖多山的边界地区。"}},{"pos":"VERB 动词","cn":"（使）空降（指突然从机构外调入）","en":"If a person parachutes into an organization or if they are parachuted into it, they are brought in suddenly in order to help it.","ex":{"en":"...a consultant who parachutes into corporations and helps provide strategic thinking.","cn":"空降到公司协助制定战略思想的顾问"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment fastened to the back of people who jump out of planes, which makes them fall slowly and safely to the ground","cn":"降落伞"},{"en":"to jump from a plane using a parachute","cn":"跳伞"},{"en":"to drop something from a plane with a parachute 〔","cn":"用降落伞〕空投"}]},"vocab":{"pos":"n v","senses":[{"en":"A parachute fills with air and breaks the fall of someone falling from an airplane."}]},"collocations":{"phrases":["VERB + PARACHUTE pack","PARACHUTE + VERB open | fail to open","PARACHUTE + NOUN descent, drop, jump He made his first parachute jump at the age of seventy. | instructor","PREP. by ~ Supplies were dropped by parachute."]},"media":{"img":["media/ldoce/img/parachute.jpg"],"uk":"media/ldoce/hwd/bre/1/parachute_n0205.mp3","us":"media/ldoce/hwd/ame/a/parachute1.mp3"},"examples":[{"en":"Planes dropped supplies by parachute.","cn":"飞机用降落伞空投补给。"},{"en":"The pilot was able to parachute to safety.","cn":"飞行员得以安全跳伞。"}],"oxford":{"phon":"ˈpærəʃuːt","pos":"noun","senses":[{"en":"a device that is attached to people or objects to make them fall slowly and safely when they are dropped from an aircraft. It consists of a large piece of thin cloth that opens out in the air.","cn":"降落伞","ex":{"en":"Planes dropped supplies by parachute.","cn":"飞机用降落伞空投补给。"}},{"en":"to jump from an aircraft using a parachute","cn":"跳伞","g":"[intransitive]","ex":{"en":"The pilot was able to parachute to safety.","cn":"飞行员得以跳伞脱险。"},"pos":"verb"},{"en":"to drop somebody/something from an aircraft by parachute","cn":"伞降；空投","g":"[transitive]","ex":{"en":"Supplies were parachuted into the region.","cn":"物资被空投到该地区。"},"pos":"verb"}]}},"pathologist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"病理学家","en":"A pathologist is someone who studies or investigates diseases and illnesses, and examines dead bodies in order to find out the cause of death."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of the causes and effects of illnesses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A student who is fascinated with the causes of disease and death might decide to go to medical school and become a pathologist ."}]},"collocations":{"phrases":["ADJ. consultant | forensic | independent | Home Office, police","PATHOLOGIST + VERB examine sth | confirm sth The police pathologist examined the body and confirmed that death was due to poisoning.","PHRASES pathologist's report"]},"media":{"uk":"media/ldoce/hwd/bre/9/pathology0205.mp3","us":"media/ldoce/hwd/ame/6/pathology.mp3"},"oxford":{"phon":"pəˈθɒlədʒɪst","pos":"noun","senses":[{"en":"a doctor who studies pathology and examines dead bodies to find out the cause of death","cn":"病理学医生；病理学家","ex":{"en":"The pathologist confirmed that death was due to poisoning.","cn":"病理学家证实，死亡是由中毒引起的。"}}]}},"palate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腭","en":"Your palate is the top part of the inside of your mouth."},{"pos":"N-COUNT 可数名词","cn":"（对美食或美酒的）品尝力；味觉","en":"You can refer to someone's palate as a way of talking about their ability to judge good food or drink.","ex":{"en":"...fresh pasta sauces to tempt more demanding palates.","cn":"诱惑较为挑剔的食客的新鲜意面调味酱"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the roof (= top inside part ) of your mouth","cn":"腭"},{"en":"the sense of taste, and especially your ability to enjoy or judge food","cn":"味觉"}]},"vocab":{"pos":"n","senses":[{"en":"Touch your tongue to the top of your mouth. What you're touching is your palate . Palate is often used when discussing taste in a broader sense, as in: chocolate cake is pleasing to the palate ."}]},"collocations":{"phrases":["ADJ. hard | soft | cleft Their baby had an operation to repair a cleft palate. 2 sense of taste","ADJ. discerning, discriminating, sophisticated | jaded Here is a dish that will revive jaded palates.","VERB + PALATE have She has a discerning palate. | appeal to, suit This kind of food appeals to more sophisticated palates. | clean, cleanse "]},"media":{"uk":"media/ldoce/hwd/bre/9/palate0205.mp3","us":"media/ldoce/hwd/ame/9/palate.mp3"},"examples":[{"en":"a menu to tempt even the most jaded palate","cn":"能引起最没胃口的人食欲的食谱"},{"en":"the hard/soft palate (= the hard/soft part at the front/back of the palate )","cn":"硬腭；软腭"}],"oxford":{"phon":"ˈpælət","pos":"noun","senses":[{"en":"the top part of the inside of the mouth","cn":"腭；上腭","ex":{"en":"the hard/soft palate (= the hard/soft part at the front/back of the palate)","cn":"硬腭；软腭"}},{"en":"the ability to recognize and/or enjoy good food and drink","cn":"味觉；品尝力","g":"[usually singular]","ex":{"en":"a menu to tempt even the most jaded palate (= a person who has eaten too much rich food and become bored of it)","cn":"一份连吃惯美食的人看到也会食指大动的菜单"}}]}},"partition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"隔断；隔扇；隔墙；隔板","en":"A partition is a wall or screen that separates one part of a room or vehicle from another.","ex":{"en":"...new offices divided only by glass partitions","cn":"只用玻璃隔板隔开的新办公室"}},{"pos":"VERB 动词","cn":"（用隔板、隔扇等）隔开，分隔","en":"If you partition a room, you separate one part of it from another by means of a partition.","ex":{"en":"Bedrooms have again been created by partitioning a single larger room","cn":"通过将一间大屋用隔断断开的方法再隔出了几间卧室。"}},{"pos":"VERB 动词","cn":"分割，分裂（国家）","en":"If a country is partitioned, it is divided into two or more independent countries.","ex":{"en":"...for the first time since Ireland was partitioned","cn":"自爱尔兰被分裂后第一次"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an upright flat structure made of stone or brick, that divides one area from another or surrounds an area","cn":""},{"en":"a structure made of wood, metal etc that surrounds a piece of land","cn":""},{"en":"a metal fence that is made of a series of upright bars","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A partition is something that divides space. When your younger brother decides to stop bathing, setting up a partition between his side of the room and yours seems like a good idea...until you realize your partition is not air-tight."}]},"collocations":{"phrases":["ADJ. movable | folding","VERB + PARTITION build, erect, put up | remove, take down","PARTITION + VERB divide sth (up), separate sth The cafe was divided up by glass partitions.","PARTITION + NOUN wall","PREP. ~ between There were no partitions between the showers."]},"media":{"uk":"media/ldoce/hwd/bre/6/partition_n0205.mp3","us":"media/ldoce/hwd/ame/d/partition1.mp3"},"examples":[{"en":"The room is partitioned into three sections.","cn":"这间屋子被隔为三小间。"},{"en":"the partition of Germany after the war","cn":"战后对德国的分割"}],"oxford":{"phon":"pɑːˈtɪʃn","pos":"noun","senses":[{"en":"a wall or screen that separates one part of a room from another","cn":"隔断；隔扇；隔板墙","g":"[countable]","ex":{"en":"The cafe was divided up by glass partitions.","cn":"这个咖啡馆里用玻璃隔断相隔。"}},{"en":"the division of one country into two or more countries","cn":"分割；分治；瓜分","g":"[uncountable]","ex":{"en":"the partition of Germany after the war","cn":"战后对德国的分割"}},{"en":"to divide something into parts","cn":"分割；使分裂","ex":{"en":"to partition a country","cn":"分割一个国家"},"pos":"verb"},{"en":"the division of India into the independent countries of India and Pakistan in August 1947 when British rule in India ended. This was one of the conditions of independence, though it led to much violence between Hindus and Muslims.","cn":"印巴分治（1947 年 8 月，英国结束对印度的统治，印度分裂为印度和巴基斯坦两个独立国家。这是印度独立的条件之一，尽管这导致了印度教徒和穆斯林之间的暴力冲突。）","pos":""}]}},"paris":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of France, on the River Seine, which is also the country’s business and financial centre. Paris is typically thought of as a very romantic city, and is known as a place where many famous artists lived, especially in the 19th and early 20th cen","cn":""},{"en":"in ancient Greek stories, a prince of troy who caused the trojan war by taking Helen away from Greece, and who killed achilles in this war","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000009512.mp3","us":"media/ldoce/hwd/ame/9/paris1.mp3"}},"panic":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"恐慌；惊慌失措","en":"Panic is a very strong feeling of anxiety or fear, which makes you act without thinking carefully.","ex":{"en":"An earthquake hit the capital, causing panic among the population","cn":"首都发生了地震，引发民众恐慌。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恐慌局面；人心惶惶的状态","en":"Panic or a panic is a situation in which people are affected by a strong feeling of anxiety.","ex":{"en":"There was a moment of panic in Britain as it became clear just how vulnerable the nation was","cn":"一时间，英国出现了大恐慌，因为人们清楚地看到了英国有多么不堪一击。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）惊慌失措；（使）恐慌","en":"If you panic or if someone panics you, you suddenly feel anxious or afraid, and act quickly and without thinking carefully.","ex":{"en":"Guests panicked and screamed when the bomb exploded","cn":"炸弹爆炸后，客人们惊慌失措，尖声惊叫。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of being frightened","cn":""},{"en":"a feeling of great fear, because you think that something terrible is about to happen","cn":""},{"en":"a sudden feeling of fear, or a situation that makes you feel this","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To panic is to become filled with fear and anxiety. Someone in a panic is totally freaking out."}]},"collocations":{"phrases":["ADJ. blind, mad, sheer, total | mild, minor | momentary | growing, mounting, rising | sudden | last-minute There was a last-minute panic whe","QUANT. surge, wave I felt a surge of panic when I realized my mistake.","VERB + PANIC feel He felt panic rising within him. | get into, go into She went into a mad panic when she couldn't find the exit. | cause, c","PANIC + VERB break out, spread (across/through, etc. sth), sweep over/through sth Panic swept through the crowd. | seize sb | grow, rise | s","PANIC + NOUN attack She still has panic attacks, two years after the accident. | button The shopkeeper pressed the panic button and the poli","PREP. in (a) ~ He jumped out of the car in a panic. People fled in panic. | with ~ Her mind went blank with panic. | ~ about panic about foo","PHRASES a feeling/sense of panic, in a state of panic, a look of panic A look of panic spread across the boy's face. | a moment of panic, a "]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdepanic.mp3","us":"media/ldoce/hwd/ame/6/panic1.mp3"},"examples":[{"en":"Careful planning at this stage will help to avoid a last-minute panic.","cn":"现在仔细规划就可以避免事到临头手忙脚乱。"},{"en":"I panicked when I saw smoke coming out of the engine.","cn":"我看见发动机冒烟时，吓得手足无措。"}],"oxford":{"phon":"ˈpænɪk","pos":"noun","senses":[{"en":"a sudden feeling of great fear that cannot be controlled and prevents you from thinking clearly","cn":"惊恐；恐慌","ex":{"en":"a moment of panic","cn":"一时惊慌"}},{"en":"a situation in which people are made to feel very anxious or frightened, causing them to act quickly and without thinking carefully","cn":"人心惶惶的局面；惶恐不安","ex":{"en":"News of the losses caused (a) panic among investors.","cn":"亏损的消息令投资者人心惶惶。"}},{"en":"to suddenly feel frightened so that you cannot think clearly and you say or do something stupid, dangerous, etc.; to make somebody do this","cn":"（使）惊慌，惊慌失措","ex":{"en":"I panicked when I saw smoke coming out of the engine.","cn":"我看见发动机冒烟时，吓得手足无措。"},"pos":"verb"}]}},"paradoxical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自相矛盾的；似矛盾而（可能） 正确的","en":"If something is paradoxical, it involves two facts or qualities which seem to contradict each other.","ex":{"en":"Some sedatives produce the paradoxical effect of making the person more anxious","cn":"一些镇静剂适得其反，加重了患者的焦虑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement or situation that contains two opposite ideas or parts, so that it seems strange that they could both be true at the same time","cn":""},{"en":"a situation that seems strange because it involves two ideas or qualities that are very different","cn":""},{"en":"a statement that seems impossible because it contains two opposing ideas that are both true","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"“You have to spend money to make money.” That’s a paradoxical statement used by people in business, and it seems to say two opposite things that contradict each other, but if you think about it, it’s actually kind of true."}]},"collocations":{"phrases":["VERBS appear, be, seem, sound","ADV. distinctly, very | slightly, somewhat | seemingly trying to understand her seemingly paradoxical behaviour | inherently | curiously He "]},"media":{"uk":"media/ldoce/hwd/bre/3/paradox0205.mp3","us":"media/ldoce/hwd/ame/f/paradox.mp3"},"examples":[{"en":"It is paradoxical that some of the poorest people live in some of the richest areas of the country.","cn":"某些最贫穷的人却住在这个国家一些最富有的地区，这似乎很矛盾。"},{"en":"It’s a paradox that in such a rich country there can be so much poverty.","cn":""}],"oxford":{"phon":"ˌpærəˈdɒksɪkl","pos":"adjective","senses":[{"en":"having two opposite features and therefore seeming strange","cn":"矛盾的人（或事物、情况）","ex":{"en":"It is paradoxical that some of the poorest people live in some of the richest areas of the country.","cn":"某些最贫穷的人却住在这个国家一些最富有的地区，这似乎很矛盾。"}},{"en":"containing two opposite ideas that make it seem impossible or unlikely, although it is probably true","cn":"似非而是的隽语；悖论；悖论修辞","ex":{"en":"These seemingly paradoxical statements need to be looked at a little further to get the true picture.","cn":"这些看似矛盾的陈述需要进一步研究才能了解真实情况。"}}]}},"painless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（治疗等）无痛的","en":"Something such as a treatment that is painless causes no physical pain.","ex":{"en":"Acupuncture treatment is gentle, painless, and, invariably, most relaxing","cn":"针灸疗法柔和，无痛，而且总是令人非常放松。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不费劲的；容易的","en":"If a process or activity is painless, there are no difficulties involved, and you do not have to make a great effort or suffer in any way.","ex":{"en":"House-hunting is in fact relatively painless in this region","cn":"在这个地区找房子事实上相对比较容易。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not difficult to do, and not needing much effort","cn":""},{"en":"easy and not complicated – used about things such as instructions and explanations, or about machines and systems","cn":""},{"en":"easy to understand or do, and unlikely to cause you any problems","cn":""}]},"collocations":{"phrases":["VERBS be The operation was relatively painless.","ADV. completely, entirely, totally | almost, virtually | comparatively, relatively"]},"media":{"uk":"media/ldoce/hwd/bre/d/painless0205.mp3","us":"media/ldoce/hwd/ame/4/painless.mp3"},"examples":[{"en":"The interview was relatively painless.","cn":"此次面试相对轻松。"},{"en":"The treatment is painless.","cn":"这种治疗无疼痛。"}],"oxford":{"phon":"ˈpeɪnləs","pos":"adjective","senses":[{"en":"causing you no pain","cn":"无痛的","ex":{"en":"a painless death","cn":"无痛死亡"}},{"en":"not unpleasant or difficult to do","cn":"愉快的；轻松的；不难的；不讨厌的","ex":{"en":"The interview was relatively painless.","cn":"此次面试相对轻松。"}}]}},"pact":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"协定；契约；盟约；条约","en":"A pact is a formal agreement between two or more people, organizations, or governments to do a particular thing or to help each other.","ex":{"en":"Last month he signed a new non-aggression pact with Germany","cn":"上个月，他与德国签订了新的互不侵犯条约。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an arrangement that is made when two or more people, countries, or organizations agree to do something","cn":""},{"en":"a written agreement between two or more countries, especially to end a war","cn":""},{"en":"a written agreement between two or more countries or political parties in which they promise to support each other or defend each other","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A pact is a treaty or other agreement between parties, and it's usually written. Countries can have pacts or you can make a pact with your friends, promising each other that you'll all show up for the spelling bee."}]},"collocations":{"phrases":["ADJ. bilateral, mutual | defence, military, security | non-agression, peace | electoral, political, social, trade | suicide","VERB + PACT have | conclude, enter into, form, make, strike The Social Democrats struck an electoral pact with the Liberals. | sign | break","PREP. in a/the ~ She died with her lover in a suicide pact. | under a/the ~ conditions under the recently signed non-aggression pact | ~ bet"]},"media":{"uk":"media/ldoce/hwd/bre/9/pact0205.mp3","us":"media/ldoce/hwd/ame/4/pact.mp3"},"examples":[{"en":"They have made a pact with each other not to speak about their differences in public.","cn":"他们彼此达成协议，不公开谈论他们的歧见。"},{"en":"a suicide pact (= an agreement by two or more people to kill themselves at the same time)","cn":"自杀协议（两人或多人约定同时自杀）"}],"oxford":{"phon":"pækt","pos":"noun","senses":[{"en":"a formal agreement between two or more people, groups or countries, especially one in which they agree to help each other","cn":"条约；协议；公约","ex":{"en":"He helped to negotiate a non-aggression pact between the two countries.","cn":"他协助两国达成了互不侵犯条约。"}}]}},"pane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（窗户或门上的）一块玻璃","en":"A pane of glass is a flat sheet of glass in a window or door."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thin flat piece of something such as paper, glass, or metal, usually with four straight sides","cn":""},{"en":"a thin flat piece of something such as cloth or paper","cn":""},{"en":"a small narrow piece of paper, usually with information written on it","cn":""}]},"collocations":{"phrases":["ADJ. broken | missing The missing pane has been replaced. | glass | window","VERB + PANE break, shatter, smash | blow in/out The wind blew in a pane of their front window. | replace","PREP. against/to a/the ~ Her face was pressed against the pane. | down a/the ~ The rain ran down the window pane. | on a/the ~ There was dir","PHRASES a pane of glass The burglars got in by smashing a pane of glass in a door."]},"media":{"uk":"media/ldoce/hwd/bre/6/pain_v0205.mp3","us":"media/ldoce/hwd/ame/2/pain1.mp3"},"examples":[{"en":"a pane of glass","cn":"一片窗玻璃"},{"en":"a windowpane","cn":"一块窗玻璃"}],"oxford":{"phon":"peɪn","pos":"noun","senses":[{"en":"a single sheet of glass in a window","cn":"（一片）窗玻璃","ex":{"en":"a pane of glass","cn":"一片窗玻璃"}}]}},"parenthood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"父母身份；家长身份","en":"Parenthood is the state of being a parent.","ex":{"en":"She may feel unready for the responsibilities of parenthood.","cn":"她可能觉得没有准备好承担为人父母的责任。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being a parent","cn":"父母的身份"}]},"collocations":{"phrases":["ADJ. lone, single | responsible education about family planning and responsible parenthood","PHRASES preparation for parenthood"]},"media":{"uk":"media/ldoce/hwd/bre/b/parenthood0205.mp3","us":"media/ldoce/hwd/ame/0/parenthood.mp3"},"examples":[{"en":"the responsibilities/joys of parenthood","cn":"做父母的责任/欢乐"},{"en":"Story-reading should be one of the great joys of parenthood.","cn":"读故事是做父母的最大快乐之一。"}],"oxford":{"phon":"ˈpeərənthʊd","pos":"noun","senses":[{"en":"the state of being a parent","cn":"做父母的身份","ex":{"en":"the responsibilities/joys of parenthood","cn":"做父母的责任／欢乐"}}]}},"partnership":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"伙伴关系；合作关系","en":"Partnership or a partnership is a relationship in which two or more people, organizations, or countries work together as partners.","ex":{"en":"...the partnership between Germany's banks and its businesses","cn":"德国的银行和企业之间的伙伴关系"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a relationship between people or groups working closely together","cn":""},{"en":"an arrangement involving two or more different groups or countries to work together to oppose an enemy, to do business, or to work together for something that they both believe in","cn":""},{"en":"if two groups work or fight side by side , they work closely together to achieve something, even though there may be big differences between them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"What do Lewis and Clark, Bonnie and Clyde, and Ben and Jerry have in common? They all formed partnerships — cooperative relationships where they worked as a team to reach a goal, whether it was robbing banks or inventing Cherry Garcia."}]},"collocations":{"phrases":["ADJ. close | limited | effective, good, great, successful | working We are trying to develop a working partnership between local schools and","VERB + PARTNERSHIP have | create, establish, form, set up (in) | enter into, go into The company has gone into partnership with Swiss Bank C","PARTNERSHIP + NOUN agreement, arrangement","PREP. in ~ with They are in partnership with Apex software. | ~ between a partnership between the university and local colleges | ~ in She h"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdepartnership.mp3","us":"media/ldoce/hwd/ame/2/partnership.mp3"},"examples":[{"en":"He developed his own program in partnership with an American expert.","cn":"他与一位美国专家合作开发自己的程序。"},{"en":"Marriage should be an equal partnership.","cn":"婚姻应当是平等的伴侣关系。"}],"oxford":{"phon":"ˈpɑːtnəʃɪp","pos":"noun","senses":[{"en":"the state of being a partner in business","cn":"伙伴关系；合伙人身份","g":"[uncountable]","ex":{"en":"to be in/to go into partnership","cn":"结成合作关系"}},{"en":"a relationship between two people, organizations, etc.; the state of having this relationship","cn":"合作关系；合作","g":"[countable, uncountable]","ex":{"en":"Marriage should be an equal partnership.","cn":"婚姻应当是平等的伴侣关系。"}},{"en":"a business owned by two or more people who share the profits","cn":"合伙企业","g":"[countable]","ex":{"en":"a junior member of the partnership","cn":"企业的次要合伙人"}}]}},"pavement":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人行道","en":"A pavement is a path with a hard surface, usually by the side of a road.","ex":{"en":"He was hurrying along the pavement.","cn":"他在人行道上疾行。"}},{"pos":"N-COUNT 可数名词","cn":"（硬化）路面","en":"The pavement is the hard surface of a road."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long, narrow piece of ground for people to walk along","cn":""},{"en":"a path built along the side of a street for people to walk on","cn":""},{"en":"a public path for people to walk on in the country","cn":""}]},"collocations":{"phrases":["ADJ. wide | narrow | hard She had sore feet from walking on hard pavements all day. | broken, uneven | crowded | empty","VERB + PAVEMENT step off, step onto | keep to | mount The car mounted the pavement and crashed into a lamp post.","PAVEMENT + NOUN cafe, table, terrace","PREP. along the ~, down the ~, on the ~ There was a car parked on the pavement and we couldn't get by. | up the ~","PHRASES the edge of the pavement"]},"media":{"uk":"media/ldoce/hwd/bre/8/pavement0205.mp3","us":"media/ldoce/hwd/ame/1/pavement.mp3"},"examples":[{"en":"Two cars skidded on the icy pavement.","cn":"两辆汽车在结冰的路面上打滑。"},{"en":"a pavement cafe","cn":"路边咖啡馆"}],"oxford":{"phon":"ˈpeɪvmənt","pos":"noun","senses":[{"en":"a flat part at the side of a road for people to walk on","cn":"（马路边的）人行道","g":"[countable]","lab":"British English","ex":{"en":"a pavement cafe","cn":"路边咖啡馆"}},{"en":"any area of flat stones on the ground","cn":"石板铺的地面","g":"[countable, uncountable]","ex":{"en":"a mosaic pavement","cn":"马赛克地面"}},{"en":"the surface of a road","cn":"路面","g":"[uncountable]","lab":"North American English","ex":{"en":"Two cars skidded on the icy pavement.","cn":"两辆汽车在结冰的路面上打滑。"}},{"en":"a large flat area of rock with nothing growing on it","cn":"一大块平坦的岩石，上面没有任何东西生长","g":"[countable]","lab":"geology","ex":{"en":"a limestone pavement","cn":"石灰石路面"}}]}},"payable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"应支付的；可支付的","en":"If an amount of money is payable, it has to be paid or it can be paid.","ex":{"en":"Purchase tax was not payable on goods for export.","cn":"出口商品不需要交购买税。"}},{"pos":"ADJ 形容词","cn":"（支票或邮政汇票）应付予…的","en":"If a cheque or postal order is made payable to you, it has your name written on it to indicate that you are the person who will receive the money.","ex":{"en":"Write, enclosing a cheque made payable to Cobuild Limited.","cn":"写封信，附上一张支付给Cobuild有限公司的支票。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a bill, debt etc that is payable must be paid 〔","cn":"账单﹑债务等〕应支付的"},{"en":"a cheque etc that is payable to someone has that person’s name written on it and should be paid to them 〔","cn":"支票等〕付给某人的"}]},"collocations":{"phrases":["VERBS be | become the date on which the rent becomes payable | make sth Cheques should be made payable to Brighton Borough Council.","ADV. immediately This amount is payable immediately.","PREP. by the costs payable by a client | on No tax is payable on these earnings. | to An initial fee is payable to the franchiser."]},"media":{"uk":"media/ldoce/hwd/bre/1/payable0205.mp3","us":"media/ldoce/hwd/ame/b/payable.mp3"},"examples":[{"en":"A 10% deposit is payable in advance.","cn":"须预付 10% 的押金。"},{"en":"The price is payable in monthly instalments.","cn":"本价格可按月分期付款。"}],"oxford":{"phon":"ˈpeɪəbl","pos":"adjective","senses":[{"en":"that must be paid or can be paid","cn":"应付；可偿付","ex":{"en":"A 10 per cent deposit is payable in advance.","cn":"须预付 10% 的订金。"}},{"en":"when a cheque, etc. is made payable to somebody, their name is written on it and they can then pay it into their bank account","cn":"应付予（抬头人、收款人等）","ex":{"en":"Please make the cheque payable to Rose Roger.","cn":"支票抬头请注明罗斯·罗杰 (Rose Roger)。"}}]}},"parole":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"假释","en":"If a prisoner is given parole, he or she is released before the official end of their prison sentence and has to promise to behave well.","ex":{"en":"Although sentenced to life, he will become eligible for parole after serving 10 years.","cn":"虽然被判终身监禁，但是他在服刑10年后可以申请假释。"}},{"pos":"VERB 动词","cn":"假释（囚犯）","en":"If a prisoner is paroled, he or she is given parole.","ex":{"en":"He faces at most 12 years in prison and could be paroled after eight years.","cn":"他面临最高12年监禁，8年后可以获得假释。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"permission for someone to leave prison, on the condition that they promise to behave well","cn":"假释﹐有条件的释放"},{"en":"to allow someone to leave prison on the condition that they promise to behave well","cn":"准许…假释﹔使获假释"}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"If you're in prison, after serving a few years you might be let out on parole , a promise to be good and check in regularly."}]},"collocations":{"phrases":["ADJ. early","VERB + PAROLE be on | give sb, grant sb | get She's got (her) parole. | let sb out on, release sb on She was released on parole after servin","PAROLE + NOUN board, system","PREP. on ~ He committed a burglary while on parole. | with ~ With parole, he could be out in two years. | without ~ sentenced to life impris"]},"media":{"uk":"media/ldoce/hwd/bre/7/parole_n0205.mp3","us":"media/ldoce/hwd/ame/5/parole1.mp3"},"examples":[{"en":"She was paroled after two years.","cn":"她两年后获假释。"},{"en":"She was released on parole.","cn":"她获得假释。"}],"oxford":{"phon":"pəˈrəʊl","pos":"noun","senses":[{"en":"permission that is given to a prisoner to leave prison before the end of their sentence on condition that they behave well","cn":"假释；有条件的释放","lab":"especially North American English","ex":{"en":"to be eligible for parole","cn":"符合假释条件"}},{"en":"language considered as the words individual people use, rather than as the communication system of a particular community","cn":"言语","lab":"linguistics"},{"en":"to give a prisoner permission to leave prison before the end of their sentence on condition that they behave well","cn":"假释；有条件地释放","ex":{"en":"She was paroled after two years.","cn":"她两年后获假释。"},"pos":"verb"}]}},"patriotic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱国的","en":"Someone who is patriotic loves their country and feels very loyal towards it.","ex":{"en":"Woosnam is fiercely patriotic","cn":"伍斯纳姆非常爱国。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing to support a person, party, belief etc for a long time","cn":""},{"en":"supporting a particular person, party, set of beliefs, etc – used especially about someone you can can trust and depend on to support you","cn":""},{"en":"strongly supporting someone or something because you admire them, love them, or enjoy what they do","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Respect for the country's flag, a desire to see your nation succeed, and a deep, abiding love of your country are all patriotic expressions, but being patriotic doesn’t mean you think your country’s perfect — just that you love it."}]},"collocations":{"phrases":["VERBS be | become","ADV. fiercely, intensely, strongly, very | quite | unashamedly The party framed its message in unashamedly patriotic language."]},"media":{"uk":"media/ldoce/hwd/bre/b/patriotic0205.mp3","us":"media/ldoce/hwd/ame/5/patriotic.mp3"},"examples":[{"en":"a patriotic man who served his country well","cn":"为国尽忠的爱国者"},{"en":"patriotic songs","cn":"爱国歌曲"}],"oxford":{"phon":"ˌpætriˈɒtɪk","pos":"adjective","senses":[{"en":"having or expressing a great love of your country","cn":"爱国的","ex":{"en":"a patriotic man who served his country well","cn":"为国尽忠的爱国者"}}]}},"parasite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"寄生虫；寄生物","en":"A parasite is a small animal or plant that lives on or inside a larger animal or plant, and gets its food from it."},{"pos":"N-COUNT 可数名词","cn":"不劳而获者；寄生虫","en":"If you disapprove of someone because you think that they get money or other things from other people but do not do anything in return, you can call them a parasite ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not work, but still expects society to provide them with money, food, a home etc","cn":""},{"en":"someone who regularly takes money from another person, from the government, etc with no intention of doing anything to earn it or change the situation","cn":""},{"en":"someone who always expects other people to give them money, food etc, especially because they are too lazy to earn money or get things for themselves","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A creature that lives off another organism is a parasite . The parasite might not hurt the host, but it doesn't do anything to help it, either."}]},"collocations":{"phrases":["ADJ. common | dangerous These flies carry a dangerous parasite. | external, internal | intestinal","VERB + PARASITE carry, have"]},"media":{"uk":"media/ldoce/hwd/bre/e/parasite0205.mp3","us":"media/ldoce/hwd/ame/f/parasite.mp3"},"oxford":{"phon":"ˈpærəsaɪt","pos":"noun","senses":[{"en":"a small animal or plant that lives on or inside another animal or plant and gets its food from it","cn":"寄生物；寄生植物；寄生虫","ex":{"en":"fleas, lice and other parasites","cn":"跳蚤、虱子和其他寄生虫"}},{"en":"a person who always relies on or benefits from other people and gives nothing back","cn":"寄生虫；依赖他人过活者","lab":"disapproving","ex":{"en":"He regards students as parasites on society.","cn":"他把学生视为社会的寄生虫。"}}]}},"pang":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一阵剧痛；突然而强烈的情感","en":"A pang is a sudden strong feeling or emotion, for example of sadness or pain.","ex":{"en":"For a moment she felt a pang of guilt about the way she was treating him.","cn":"有一阵子，她为自己那样对他感到内疚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden feeling of pain, sadness etc","cn":"一阵疼痛﹔一阵伤心"},{"en":"pang of jealousy/guilt/remorse/regret She felt a sudden pang of guilt.","cn":"一阵罪恶感突然涌上她的心头。 hunger pangs 饥饿引起的阵阵疼痛"}]},"vocab":{"pos":"n","senses":[{"en":"A pang is a sharp jab or an intense hurt that comes on suddenly. If you've felt an all-of-a-sudden, deep sadness that seems to hit you even in the back of the eyes, you've probably had a pang of emotion over a loss or a tragic story."}]},"collocations":{"phrases":["ADJ. sharp | little | passing a passing pang of regret | sudden, unexpected | hunger | birth (figurative) the birth pangs of the new technol","VERB + PANG experience, feel, suffer He experienced a sudden pang of conscience. | cause, give sb The photograph gave her a pang of homesick","PANG + VERB shoot through sb A sharp pang of guilt shot through him.","PREP. with a ~ With a pang she recalled the last time she had seen him. | ~ of She felt a little pang of jealousy."]},"media":{"uk":"media/ldoce/hwd/bre/c/pang0205.mp3","us":"media/ldoce/hwd/ame/8/pang.mp3"},"examples":[{"en":"a sudden pang of jealousy","cn":"突然涌来的嫉妒"},{"en":"hunger pangs/pangs of hunger","cn":"饥饿之苦"}],"oxford":{"phon":"pæŋ","pos":"noun","senses":[{"en":"a sudden strong feeling of physical or emotional pain","cn":"突然的疼痛（或痛苦）；一阵剧痛","ex":{"en":"hunger pangs/pangs of hunger","cn":"饥饿之苦"}}]}},"pastime":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"消遣；娱乐","en":"A pastime is something that you do in your spare time because you enjoy it or are interested in it.","ex":{"en":"His favourite pastime is golf.","cn":"他最喜欢的消遣是打高尔夫。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an activity that you enjoy, and that you like to spend time doing when you are not working","cn":""},{"en":"something that you are interested in and like doing or talking about","cn":""},{"en":"something that you do because it is enjoyable or interesting","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A pastime is any hobby or activity that you do to pass the time. Usually, people enjoy their pastimes ."}]},"collocations":{"phrases":["ADJ. enjoyable, rewarding | favourite, popular | dangerous | expensive | national Eating out is the national pastime in France.","VERB + PASTIME enjoy, indulge in, pursue","PREP. ~ among Fighting is a popular pastime among some of the town's boys. | ~ for Cycling is an enjoyable pastime for people of all ages."]},"media":{"uk":"media/ldoce/hwd/bre/4/pastime0205.mp3","us":"media/ldoce/hwd/ame/5/pastime.mp3"},"examples":[{"en":"Reading was her favourite pastime.","cn":"阅读是她最喜爱的消遣方式。"}],"oxford":{"phon":"ˈpɑːstaɪm","pos":"noun","senses":[{"en":"something that you enjoy doing when you are not working","cn":"消遣；休闲活动","ex":{"en":"Watching television is still the most popular national pastime.","cn":"看电视仍然是全国最受欢迎的消遣方式。"}}]}},"parse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"对（句子）作语法分析","en":"In grammar, if you parse a sentence, you examine each word and clause in order to work out what grammatical type each one is."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to describe the grammar of a word when it is in a particular sentence, or the grammar of the whole sentence","cn":"对〔句中的词或句子〕作语法分析"}]},"vocab":{"pos":"v","senses":[{"en":"When you parse a sentence, you break it into parts and analyze each element carefully. When your sweetheart shouts \"You never listen!\" it's a bad idea to parse that by replying, \"I just heard you, so I must be listening.\""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41parse.mp3","us":"media/ldoce/hwd/ame/c/parse.mp3"},"oxford":{"phon":"pɑːz","pos":"verb","senses":[{"en":"to divide a sentence into parts and describe the grammar of each word or part","cn":"（对句子）作语法分析；作句法分析"}]}},"panama":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country on the Isthmus of Panama, a narrow piece of land connecting Central and South America, between Costa Rica and Colombia. Population: 3,559,408 (2014). Capital: Panama City. Panama is known especially for the Panama Canal, a long, narrow stretch of wat","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/p028-000009485.mp3","us":"media/ldoce/hwd/ame/1/panama1.mp3","img":["media/thumb/panama.jpg"]},"oxford":{"phon":"ˈpænəmɑː","pos":"noun","senses":[{"en":"a man’s hat made from fine straw","cn":"巴拿马草帽"},{"en":"a country in Central America","cn":"巴拿马（中美洲国家）"}]}}});
